(window.GIM_TS=window.GIM_TS||{})["Pesachim.1"]={"from":24,"a":[["\u0003שתי פרות היו חורשות בהר המשחה\u0004 (הר הזיתים) בערב פסח \u0003כל זמן ששתיהן חורשות — כל העם אוכלין\u0004 עדיין חמץ, \u0003ניטלת\u0004 (פורשת) \u0003אחת מהן — תולין,\u0004 כלומר, \u0003לא אוכלין\u0004 עוד את החמץ \u0003ולא שורפין. ניטלו שתיהן — התחילו כל העם שורפין.\u0004","כיון שדנו בהלכות ביעור החמץ, ובכללו חמץ של לחמי תודה ותרומות בערב פסח, מביאים הלכה המתקשרת עם סוגיה זו. \u0003ר' חנינא סגן הכהנים אומר: מימיהם של כהנים לא נמנעו מלשרוף את הבשר שנטמא בוולד הטומאה\u0004 (כגון שנגע בראשון לטומאה ונעשה הוא עצמו שני לטומאה) \u0003עם הבשר שנטמא באב הטומאה,\u0004 (כלומר שנגע באב הטומאה שהוא עצמו ראשון לטומאה) \u0003אף על פי שמוסיפין\u0004 לו לפי שעה \u0003טומאה על טומאתו\u0004 שהרי קודם לכן היתה טומאתו פחותה בדרגה,","\u0003הוסיף ר' עקיבא ואמר: מימיהם של כהנים לא נמנעו מלהדליק את השמן\u0004 של תרומה \u0003שנפסל בטבול יום\u0004 ששמן זה היה בדרגת שלישי לטומאה, שכן טבול יום עצמו הוא שני לטומאה והשמן שנגע בו — שלישי, \u0003בנר שנטמא בטמא מת\u0004 שהוא ראשון לטומאה ונמצא השמן שנוגע בו נעשה שני\u0003, אף על פי שמוסיפין טומאה על טומאתו.\u0004","\u0003אמר ר' מאיר: מדבריהם למדנו ששורפין תרומה טהורה עם הטמאה בפסח\u0004 כלומר, בהגיע זמן הביעור מפני אותו נימוק, שכיון שסוף שתיהן לשריפה — שוב אין מקפידים אם תיטמא קודם לכן בדרגת טומאה חמורה יותר. \u0003אמר ר' יוסי: אינה היא המדה,\u0004 כלומר אין להשוות את הדברים, ששם דובר בשריפת דברים טמאים יחד, וכאן התרומה היא טהורה ודאי.","\u0003ומודים ר' אליעזר ור' יהושע\u0004 שנחלקו בענין ביעור תרומה, \u0003ששורפין, זו\u0004 — תרומה טהורה \u0003לעצמה, וזו\u0004 — הטמאה \u0003לעצמה, על מה נחלקו — על\u0004 התרומה \u0003התלויה\u0004 שהיא טמאה מספק \u0003ועל הטמאה. שר' אליעזר אומר: תשרף זו לעצמה וזו לעצמה, ור' יהושע אומר\u0004 במקרה זה אפשר לשרוף \u0003שתיהן כאחת.\u0004","מתחילה באים לברר את דברי המשנה כדיוקם; \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003בשר שנטמא בוולד הטומאה מאי הוי\u0004 \u0005[מה נעשה]\u0006 \u0003שני\u0004 לטומאה, \u0003כי שריף ליה בהדי\u0004 \u0005[כאשר ישרוף אותו עם]\u0006 \u0003בשר שנטמא באב הטומאה מאי הוי\u0004 \u0005[מה יהיה]\u0006 — \u0003שני,\u0004 שהרי הבשר שנטמא באב הטומאה הריהו ראשון לטומאה ויכול לעשות שני, ונמצא שסוף הבשר שמונח לידו אינו אלא שני,","אם כן \u0003שני ושני הוא. מאי\u0004 \u0005[מה]\u0006 \u0003מוסיף לו טומאה על טומאתו איכא\u0004 \u0005[יש\u0006 כאן\u0005]\u0006 הלוא אין כאן שינוי כלל!?","\u0003אמר רב יהודה:\u0004 יש לתקן ולומר כי \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בוולד וולד עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שמה שנאמר במשנה \"שנטמא בוולד הטומאה\" אין להבינו כדיוקו אלא הכוונה היא שנטמא ב\"ולד ולד הטומאה\" (שני לטומאה) ואם כן הבשר \u0003הוי ליה\u0004 \u0005[הריהו]\u0006 \u0003שלישי, וקסבר\u0004 ר' חנינא סגן הכהנים כי במקרה כזה \u0003שלישי\u0004 לטומאה \u0003מותר לעשותו שני,\u0004 שהרי כשנוגע הבשר שהוא שלישי לטומאה בבשר שהוא ראשון לטומאה הריהו נעשה שני לטומאה.","ומקשים מצד אחר: וכיצד אפשר לומר שבשר הנוגע בבשר נטמא על ידו? \u0003והא\u0004 \u0005[והרי]\u0006 כלל בידינו ש\u0003אין אוכל מטמא אוכל דתניא\u0004 \u0005[שכן שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יכול יהא אוכל מטמא אוכל — תלמוד לומר \"וכי יתן מים על זרע ונפל מנבלתם עליו טמא הוא לכם\"\u0004 (ויקרא יא, לח) ומכאן דייקו: \u0003הוא\u0004 האוכלים הראשונים — \u0003טמא, ואין עושה כיוצא בו טמא.\u0004 הרי, שאוכל אינו יכול לטמא אוכל אחר כלל.","\u0003הניחא\u0004 \u0005[דבר זה נוח]\u0006 לשיטת \u0003אביי\u0004 ש\u0003אמר: לא שנו\u0004 הלכה זו שאין אוכל מטמא אוכל \u0003אלא בחולין, אבל בתרומה וקדשים\u0004 אף אוכל \u0003עושה\u0004 את האוכל שנוגע בו \u0003כיוצא בו,\u0004","וכן \u0003לרב אדא בר אהבה משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא נמי\u0004 \u0005[גם כן]\u0006 ש\u0003אמר: לא שנו\u0004 הלכה זו שאין אוכל מטמא אוכל \u0003אלא\u0004 ב\u0003חולין ותרומה, אבל בקדשים — עושה כיוצא בהן — שפיר\u0004 \u0005[יפה]\u0006 שכיון שמדובר כאן בבשר קדשים הרי לשיטות אלו אף אוכל מטמא אוכל.","\u0003אלא לרבינא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא,\u0004 ש\u0003אמר: מקרא מלא דיבר הכתוב\u0004 שלא חילק, אלא \u0003לא שנא\u0004 \u0005[שונה]\u0006 \u0003חולין לא שנא\u0004 \u0005[שונה]\u0006 \u0003תרומה, לא שנא\u0004 \u0005[שונה]\u0006 \u0003קדשים — אינו עושה\u0004 אוכל אחר \u0003כיוצא בו.\u0004 אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 וכיצד תתווסף כאן טומאה?","ומתרצים לשיטה זו: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003משקין בהדי\u0004 \u0005[יחד עם]\u0006 ה\u0003בשר\u0004 בשעה שנטמא באב הטומאה ועדיין הוא עליו, \u0003דקא\u0004 \u0005[שהוא]\u0006 הבשר שנוגע בו ובמשקים שעליו \u0003מיטמא מחמת משקין,\u0004 שלמרות שאין האוכל מטמא אוכל אחר הרי המשקין מטמאים את האוכל האחר הנוגע בהם.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כן],\u0006 \u0003האי\u0004 \u0005[\u0006ביטוי \u0005זה]\u0006 \u0003\"עם הבשר שנטמא באב הטומאה\"\u0004 אינו ביטוי נכון, \u0003\"עם הבשר ומשקין\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]\u0006 שהרי מציאות המשקים כאן היא חלק מהותי מתהליך הטומאה! \u0003אלא\u0004 כך יש לתרץ: \u0003נהי\u0004 \u0005[אף על פי]\u0006 ש\u0003אין אוכל מטמא אוכל מדאורייתא\u0004 \u0005[מדין תורה],\u0006 \u0003מדרבנן\u0004 \u0005[מדברי חכמים]\u0006 \u0003מיהו\u0004 \u0005[על כל פנים]\u0006 \u0003מטמא\u0004 שגזרו חכמים טומאה אף על אוכל שנגע באוכל טמא.","שנינו במשנה ש\u0003הוסיף ר' עקיבא\u0004 הלכה אחרת: \u0003מימיהן של כהנים\u0004 אף \u0003לא נמנעו מלהדליק\u0004 שמן שנפסל בטבול יום בתוך נר שנטמא בטמא מת. ושואלים: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003שמן שנפסל בטבול יום מאי הוי\u0004 \u0005[מהו]\u0006 מבחינת ההלכה — \u0003שלישי,\u0004 שטבול יום שני הוא, והשמן שלישי. \u0003וכי מדליק ליה\u0004 \u0005[וכאשר מדליק אותו]\u0006 \u0003בנר שנטמא בטמא מת מאי הוי\u0004 \u0005[מה יהיה]\u0006 — \u0003שני.\u0004 כי הנר נטמא בטמא מת ונעשה ראשון, כאשר נוגע השמן בנר נעשה שני לטומאה.","ואם כן, \u0003מאי קא משמע לן\u0004 \u0005[מה\u0006 אם כן \u0005משמיע לנו]\u0006 בכך — כי \u0003שלישי מותר לעשותו שני, היינו הך\u0004 \u0005[הרי זה אותו דין עצמו]\u0006 שאמר ר' חנינא סגן הכהנים, לפי מה שהתבאר, ומה חידש ר' עקיבא?! \u0003אמר רב יהודה: הכא\u0004 \u0005[כאן]\u0006 \u0003בנר של מתכת עסקינן\u0004 \u0005[עוסקים אנו]\u0006 שיש בו דין מיוחד \u0003דרחמנא\u0004 \u0005[שהכתוב]\u0006 \u0003אמר\u0004"],["\"וכל אשר יגע על פני השדה \u0003בחלל חרב\u0004 או במת או בעצם אדם או בקבר יטמא שבעת ימים\" (במדבר יט. טז) ודרשו חכמים מן הבטוי חלל חרב כי \u0003חרב\u0004 של מתכת \u0003הרי היא\u0004 לענין דרגת הטומאה \u0003כחלל\u0004 עצמו, וכן כל כלי מתכת הנוגעים בדבר שנטמא במת (אב הטומאה) נטמאים באותה דרגת טומאה של הדבר שבו נגעו. \u0003והויא ליה\u0004 \u0005[הרי הוא נעשה]\u0006 אותו נר מתכת \u0003אב הטומאה,\u0004 ובכל זאת \u0003קסבר\u0004 \u0005[סבר]\u0006 ר' עקיבא שמן זה שהוא \u0003שלישי\u0004 לטומאה \u0003מותר לעשותו\u0004 אפילו \u0003ראשון\u0004 על ידי מגעו בנר שהוא אב הטומאה.","ושואלים: \u0003ומאי דוחקיה\u0004 \u0005[ומה דוחקו]\u0006 של \u0003רב יהודה לאוקמיה\u0004 \u0005[להעמיד,\u0006 להסביר את המשנה דוקא\u0005]\u0006 \u0003בנר של מתכת נוקמיה\u0004 \u0005[נעמידנה,\u0006 נסבירנה\u0005]\u0006 \u0003בנר של חרס\u0004 שהוא הנר הרגיל,","\u0003ומאי\u0004 \u0005[ומה]\u0006 חידוש \u0003הוסיף\u0004 ר' עקיבא בדבריו — נפרש כך — \u0003דאילו התם\u0004 \u0005[שם]\u0006 בעדותו של ר' חנינא בבשר מדובר ב\u0003טמא וטמא\u0004 ששני מיני הבשר טמאים היו, \u0003ואילו הכא\u0004 \u0005[כאן]\u0006 בעדות ר' עקיבא בשמן יש כאן הבדל בין \u0003פסול וטמא.\u0004 שאותו שמן, שהוא השלישי לטומאה בתרומה הוא פסול בלבד, כלומר אף שהוא עצמו נטמא אבל שוב אינו מטמא אחרים ונקרא רק בשם פסול, (מה שאין כן בבשר הקדשים ששלישי בקודש הרי הוא טמא, לאמור: מטמא אחרים). ואם כן חידש לנו ר' עקיבא שאף אין מקפידים כאשר כתוצאה ממגעו בראשון נעשה שני ומשתנה דינו מפסול לטמא שאף הוא עצמו מטמא.","\u0003אמר רבא: מתניתין קשיתיה\u0004 \u0005[משנתינו היתה קשה לו]\u0006 לרב יהודה ומשום כך נדחק לפרשה דוקא בנר של מתכת, וזה טעמו: \u0003מאי איריא דתני\u0004 \u0005[מה שייך,\u0006 מדוע דוקא \u0005שנה]\u0006 \u0003נר שנטמא בטמא מת? ניתני\u0004 \u0005[שישנה]\u0006 \u0003שנטמא בשרץ\u0004 שהיא טומאה מצויה בהרבה, ואף היא אב הטומאה,","\u0003אלא:\u0004 ודאי כוונה מיוחדת היתה לו בכך \u0003איזהו דבר שחלוקה\u0004 דרגת \u0003טומאתו בין טומאת מת לשרץ — הוי אומר זה מתכת\u0004 שמתכת שנגעה בשרץ נעשית ראשון לטומאה ואם נגעה בטמא מת נעשית אב הטומאה כטמא מת עצמו.","\u0003אמר רבא: שמע מינה\u0004 \u0005[למד ממנה,\u0006 ממשנתנו\u0005]\u0006 כי \u0003קסבר ר' עקיבא: טומאת משקין לטמא אחרים — דאורייתא\u0004 \u0005[מן התורה]\u0006 היא ולא כדעת הסוברים שמשקין מטמאים דברים אחרים רק מדיני סופרים. \u0003דאי סלקא דעתך דרבנן\u0004 \u0005[שאם יעלה על דעתך\u0006 שטומאה זו אינה אלא \u0005מדברי סופרים]\u0006 \u0003מכדי האי\u0004 \u0005[הרי אותו]\u0006 \u0003נר מאי קא מהניא\u0004 \u0005[מה הוא מועיל\u0006 מה גורם\u0005]\u0006 לאותו \u0003שמן, אי לאיפסולי גופיה\u0004 \u0005[אם\u0006 תאמר ש\u0005לפסול אותו עצמו] —\u0006 \u0003הא פסיל וקאי\u0004 \u0005[הרי הוא\u0006 כבר \u0005פסול ועומד]\u0006 אלא ודאי שמן זה נטמא ממש ואף מטמא אחרים מדברי תורה.","ודוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 מסיק אתה דבר זה \u0003דילמא\u0004 \u0005[שמא]\u0006 דיו בחידוש זה שהשמן יכול \u0003לטמא אחרים\u0004 ואף זה אינו אלא \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 ודוחים: \u0003אי מדרבנן מאי איריא\u0004 \u0005[אם\u0006 תאמר \u0005ש\u0006הוא \u0005מדברי חכמים מה שייך,\u0006 מדוע דוקא\u0005]\u0006 שנטמא \u0003באב הטומאה\u0004 שאילו רצה ר' עקיבא להביא דוגמה לטומאה שמדברי חכמים הרי \u0003אפילו\u0004 אם היה נוגע \u0003בראשון\u0004 או \u0003שני\u0004 לטומאה \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003תחלה הוי\u0004 \u0005[היה נעשה]\u0006 שוב ראשון לטומאה, ומטמא אחרים, משום גזירת חכמים מיוחדת בדבר זה,","\u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל\u0004 דבר \u0003הפוסל את התרומה\u0004 כלומר שהוא בדרגת שני לטומאה — \u0003מטמא משקין להיות תחלה\u0004 שהמשקין שנגעו בו גזרו חכמים שייעשו ראשון לטומאה כלומר טמאים יותר מהדבר המטמא אותם עצמו, \u0003חוץ מטבול יום\u0004 (מי שהיה טמא וטבל, ועדיין לא שקעה השמש, שיש בו עוד מקצת טומאה) שגם אם נגע במשקין לא טימא אותם ולא עשאם ראשון לטומאה אלא שלישי (פסולין)","\u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 ממה שלא השתמש ר' עקיבא בדוגמה זו, כי טומאת המשקין לטמא אחרים לדעת ר' עקיבא \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003היא.\u0004","במשנה שנינו: \u0003אמר ר' מאיר מדבריהם למדנו\u0004 שמותר לשרוף תרומה טהורה עם טמאה בערב הפסח. ושואלים: \u0003מדבריהם דמאן\u0004 \u0005[של מי]\u0006 למדנו דבר זה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003מדברי ר' חנינא סגן הכהנים\u0004 הרי אפשר להקשות: \u0003מי דמי\u0004 \u0005[האם דומים]\u0006 הדברים? \u0003התם\u0004 \u0005[שם]\u0006 אמר ר' חנינא ששורפים יחד כי מדובר ב\u0003טמא וטמא,\u0004 אבל \u0003הכא\u0004 \u0005[כאן]\u0006 בתרומה דנים על \u0003טהור וטמא!\u0004","\u0003ואלא\u0004 תאמר ללמוד זאת \u0003מדברי ר' עקיבא,\u0004 אף כאן \u0003מי דמי\u0004 \u0005[האם דומה]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בדבריו מדובר ב\u0003פסול וטמא\u0004 שהם נשרפים יחד, אבל \u0003הכא\u0004 \u0005[כאן]\u0006 מדובר — ב\u0003טהור וטמא!\u0004","ומציעים: \u0003נימא קסבר\u0004 \u0005[נאמר שסבר]\u0006 \u0003ר' מאיר\u0004 כי \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 מדברת בדבר שהוא \u0003אב הטומאה דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003וולד הטומאה\u0004 לא מדברי התורה אלא \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 בלבד, ואם כן \u0003דמדאורייתא\u0004 \u0005[שמדברי התורה]\u0006 \u0003טהור מעליא\u0004 \u0005[גמור]\u0006 הוא. ולכן כיון שטהור גמור הוא נמצא חידושו בכך שבכל זאת סומכים אנו על גזירת חכמים שטמאוהו ושורפים אותם יחד כיון ששניהם טמאים, אף שהאחד טהור לגמרי (מן התורה) ואינו טמא אלא מדברי סופרים."],["\u0003ומאי\u0004 \u0005[ומהו]\u0006 \u0003מדבריהם\u0004 שאמר ר' מאיר כוונתו \u0003מדברי ר' חנינא סגן הכהנים.\u0004","\u0003אמר ריש לקיש משום\u0004 \u0005[בשם]\u0006 \u0003בר קפרא:\u0004 הסבר אחר למשנה, לדעתו \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 מדברת \u0003באב הטומאה דאורייתא וולד הטומאה דאורייתא, ומאי\u0004 \u0005[ומה\u0006 משמעות\u0005]\u0006 \u0003\"מדבריהם\"\u0004 לא על דברי התנאים הנזכרים במשנתנו, אלא הכוונה היא \u0003מדברי ר' אליעזר ור' יהושע\u0004 במקום אחר.","ושואלים: \u0003הי\u0004 \u0005[איזה]\u0006 \u0003ר' יהושע\u0004 על אלו מדבריו מוסבים דברי ר' מאיר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 של \u0003ר' יהושע דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003חבית של תרומה שנולד לה ספק טומאה,\u0004 ולכן אי אפשר לאוכלה, נחלקו מה עושים בה. \u0003ר' אליעזר אומר\u0004 כי עדיין יש לשמור עליה, כגון: \u0003אם היתה מונחת במקום התורפה,\u0004 מקום שבו עלולה היא להיטמא, \u0003יניחנה במקום המוצנע, ואם היתה מגולה — יכסנה.\u0004","\u0003ר' יהושע אומר:\u0004 לא כן, אלא גם \u0003אם היתה מונחת במקום המוצנע — יניחנה\u0004 אם ירצה \u0003במקום התורפה, ואם היתה מכוסה — יגלנה,\u0004 שכבר אינו חייב עוד בשמירתה. הרי שלדעת ר' יהושע כיון שאינה ראויה אלא להדלקה, יכול לגרום לה לטומאה, וכן לענייננו אפילו שהיא טהורה ניתן לטמא אותה ולבערה.","אולם \u0003מי דמי\u0004 \u0005[האם דומה]\u0006 מחלוקת זו לענינה של הנחת תרומה טהורה וטמאה יחד? שהרי \u0003התם\u0004 \u0005[שם]\u0006 שהותר \u0005—\u0006 \u0003גרמא בעלמא\u0004 \u0005[גורם בלבד\u0006 הוא\u0005],\u0006 שאף ר' יהושע אינו מתיר לטמא את התרומה התלויה אלא רק להיות גורם שתתקלקל או תטמא מאליה. ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 — הריהו מטמא \u0003בידים!\u0004","\u0003אלא\u0004 לא מדבר זה למד ר' מאיר כי אם \u0003הא\u0004 \u0005[זה],\u0006 ענין אחר שבו דן \u0003ר' יהושע, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003חבית של תרומה שנשברה בגת העליונה\u0004 במקום דריכת הענבים, \u0003ו\u0004בגת ה\u0003תחתונה\u0004 שבה מצטבר היין היוצא מן הגת מונחים \u0003חולין טמאין.\u0004 ואם ישפך יין התרומה לתוך החולין תיטמא התרומה על ידי כך ואף יהא הפסד ממון ניכר בדבר, כי בשל תערובת התרומה הטמאה האסורה לכל אף לכוהנים יהא כל היין שבגת התחתונה אסור בשתיה.","\u0003מודה ר' אליעזר ור' יהושע שאם יכול להציל ממנה\u0004 מחבית התרומה שנשברה אפילו \u0003רביעית\u0004 הלוג \u0003בטהרה,\u0004 שיוכל למצוא במשך הזמן כלי אפילו קטן המחזיק רק רביעית כדי לשאוב בו את יין התרומה עד שלא נטמא כולו — \u0003יציל,\u0004 ולא ישאבנו מיד בכלים טמאים גדולים כדי שיינצלו החולין. \u0003ואם לאו\u0004 \u0005[לא],\u0006 שיש בידו רק כלים טמאים, ואם יבוא לשאוב את היין או לסתום בהם את פי הגת העליונה תיטמא התרומה, מתעוררת השאלה: האם מותר להקדים ולטמא את היין הזה בידים, שהרי בין כה וכה יטמא לאחר מכן. \u0003ר' אליעזר אומר: תרד ותטמא\u0004 מעצמה, \u0003ואל יטמאנה ביד. ר' יהושע אומר: אף יטמאנה ביד,\u0004 שכיון שסופה להטמא ממילא, אין להקפיד אם יטמאנה קודם לכן, ונמנע מהפסד גדול. הרי שלדברי ר' יהושע, כיון שסופו לאיבוד, מותר לטמאותו.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מבין, \u0003האי\u0004 \u0005[\u0006ביטוי \u0005זה]\u0006 \u0003\"מדבריהם\"\u0004 שלמדנו אינו מדויק, שהרי מדברי ר' אליעזר לא למד דבר אלא \u0003\"מדבריו\" מיבעי ליה\u0004 \u0005[צריך היה\u0006 לומר\u0005],\u0006 שהרי למד שיטה זו מדברי ר' יהושע בלבד!","ומתקנים: \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 \"מדבריהם\", כלומר: \u0003ממחלוקתן של ר' אליעזר ור' יהושע למדנו\u0004 סברה זו. וכיון שהלכה כר' יהושע, לימוד גדול הוא. ומעירים \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 מלשון משנתנו שמכאן למד, שהרי ממשיכים אחר כך: \u0003\"מודה ר' אליעזר ור' יהושע\",\u0004 משמע שעל דברים אלה היו דברי ר' מאיר מוסבים. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא פירוש הדברים.","\u0003וכן אמר רב נחמן אמר רבה בר אבוה\u0004 כשיטת פירוש זו, ש\u0003מתניתין\u0004 \u0005[משנתנו]\u0006 מדברת \u0003באב הטומאה דאורייתא\u0004 \u0005[מדין תורה]\u0006 \u0003וולד הטומאה דאורייתא\u0004 \u0005[מדין תורה].\u0006 \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"מדבריהם\",\u0004 הכוונה \u0003מדברי\u0004 מחלוקתם של \u0003ר' אליעזר ור' יהושע\u0004 אלה שהבאנו.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 מתוספתא המרחיבה את הדברים שבמשנתנו. \u0003אמר ר' יוסי\u0004 לר' מאיר: \u0003אין הנדון\u0004 של שריפת החמץ שאתה רוצה להוכיח \u0003דומה לראיה\u0004 שאתה מביא לו, \u0003שכשהעידו רבותינו על מה העידו — אם\u0004 כדברי ר' חנינא סגן הכוהנים \u0003על הבשר שנטמא בוולד הטומאה ששורפין אותו עם הבשר שנטמא באב הטומאה,\u0004 סוף כל סוף \u0003זה טמא וזה טמא.\u0004","ו\u0003אם\u0004 כשיטת ר' עקיבא \u0003על השמן שנפסל בטבול יום שמדליקין אותו בנר שנטמא בטמא מת,\u0004 הרי \u0003זה פסול וזה טמא.\u0004 וכן \u0003אף אנו מודים בתרומה שנטמאת בוולד הטומאה, ששורפין אותה עם התרומה שנטמאת באב הטומאה\u0004 ומסכימים ללימוד זה","\u0003אבל היאך נשרף התלויה עם הטמאה? שמא יבא אליהו ויטהרנה\u0004 לאחר מכן. שהרי התרומה התלויה אין דינה כטמאה אלא מספק, ושמא יתברר שהיא טהורה, וכיצד אפשר לטמא תרומה טהורה בידיים!"],["וממשיכה התוספתא: \u0003הפיגול\u0004 כלומר קרבן שתוך כדי העבודות הנעשות בו חשב הכהן לאוכלו או להקריבו שלא בזמנו ונעשה הקרבן על ידי כך פיגול, \u0003ו\u0004כן \u0003הנותר\u0004 מבשר הקודשים לאחר זמן הראוי לאכילתו, שדינם שישרפו, גזרו עליהם חכמים לטמא את הידים \u0003ו\u0004כן \u0003הטמא\u0004 — בשר קודש שנטמא ממש \u0003בית שמאי אומרים: אין נשרפין כאחת,\u0004 שהרי הטמא — טמא הוא מן התורה, ואילו השאר רק מדברי סופרים ואין להוסיף להם טומאה. \u0003ובית הלל אומרים: נשרפין כאחת.\u0004","ולעניננו: \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 כי \u0003ר' מאיר מדברי ר' יהושע קאמר\u0004 \u0005[אמר]\u0006 והביא ראיה, \u0003אמאי מהדר ליה\u0004 \u0005[מדוע משיב לו]\u0006 \u0003ר' יוסי מ\u0004דברי \u0003ר' חנינא סגן הכהנים? אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: ר' יוסי לאו אדעתיה\u0004 \u0005[לא היה\u0006 הדבר \u0005על דעתו],\u0006 שלא הבין את כוונת ר' מאיר, ש\u0003הוא\u0004 ר' יוסי \u0003סבר\u0004 כי \u0003ר' מאיר מדר' חנינא סגן הכהנים קאמר ליה\u0004 \u0005[אמר לו]\u0006 ראיה, \u0003ואמר ליה\u0004 \u0005[לו]\u0006 ר' מאיר: \u0003אנא\u0004 \u0005[אני]\u0006 \u0003מדר' יהושע קאמינא\u0004 \u0005[אומר אני],\u0006","\u0003ואמר ליה\u0004 \u0005[לו]\u0006 ר' יוסי כתשובה שכנגד: \u0003ואפילו לר' יהושע נמי\u0004 \u0005[גם כן]\u0006 \u0003אינה היא המדה\u0004 (אין זו אותה מידה), \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003מודה ר' אליעזר ור' יהושע ששורף זו בפני עצמה וזו בפני עצמה,\u0004 וחלק זה מן המחלוקת ביניהם הוא האמור במשנתנו, ומצירוף דברי המשנה והתוספתא יחד יכולים אנו לשחזר את המחלוקת כהוייתה.","\u0003ו\u0004מקשים: ולגופו של דבר, \u0003אמאי\u0004 \u0005[מדוע]\u0006 אומר אתה \u0003אינה היא המדה,\u0004 הלוא \u0003מדה ומדה היא!\u0004 שהרי לכאורה היא היא המחלוקת — אם דבר העתיד ללכת לאיבוד מותר לטמאו בידים קודם לכן.","ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 בחבית שבגת שיש נימוק נוסף לטמא בידים, \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003הפסד חולין,\u0004 שאם לא יטמא את היין שבגת העליונה בידים תפסול את החולין שבגת התחתונה, וכאן כיון שאין הפסד בדבר מדוע לא ישרפו זו בפני עצמה וזו בפני עצמה?","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' ירמיה: מתניתין נמי איכא\u0004 \u0005[\u0006ב\u0005משנתנו גם כן יש]\u0006 \u0003הפסד\u0004 של \u0003עצים,\u0004 שהרי יש להוסיף עצים ולעשות מדורה מיוחדת לתרומה טמאה. \u0003אמר ליה ההוא סבא\u0004 \u0005[לו אותו זקן]:\u0006 בענין זה וכיוצא בו \u0003להפסד מרובה — חששו,\u0004 ואילו \u0003להפסד מועט\u0004 של עצים אחדים — \u0003לא חששו.\u0004","\u0003אמר ר' אסי אמר ר' יוחנן: מחלוקת\u0004 זו בין ר' מאיר ור' יוסי היא \u0003בשש\u0004 שעות, כאשר תרומת החמץ אסורה עדיין רק מדברי סופרים. \u0003אבל בשבע\u0004 כאשר אסורה היא לגמרי מן התורה ל\u0003דברי הכל שורפין\u0004 תרומת חמץ טהורה עם תרומה טמאה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לר' אסי: נימא קסבר\u0004 \u0005[האם נאמר שסבר]\u0006 \u0003ר' יוחנן:\u0004 כי \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 מדברת \u0003באב הטומאה דאורייתא\u0004 \u0005[שמן התורה]\u0006 \u0003וולד הטומאה דרבנן\u0004 \u0005[שמדברי סופרים],\u0006 \u0003ומאי\u0004 \u0005[ומה\u0006 משמעות\u0005]\u0006 ההוכחה של ר' מאיר \u0003\"מדבריהם\" — מדברי ר' חנינא סגן הכהנים,\u0004 כפי ההסבר הקודם. שכן רואים שהמחלוקת היא בדבר שאיסורו מדברי חכמים בלבד כולד הטומאה או כחובת שריפה בשש שעות שמדברי סופרים, בשעה שאף לדברי סופרים אינו אסור, וכגון בשעה רביעית או חמישית, אף ר' מאיר מודה שאין שורפים.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן]\u0006 הדבר, כך סבר באמת ר' יוחנן. \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 במפורש ש\u0003אמר ר' יוחנן: מתניתין\u0004 \u0005[משנתנו]\u0006 מדברת \u0003באב הטומאה דאורייתא\u0004 \u0005[שמן התורה]\u0006 \u0003וולד הטומאה דרבנן\u0004 \u0005[שמדברי סופרים],\u0006 \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"מדבריהם\" — מדברי רבי חנינא סגן הכהנים. ומחלוקת\u0004 ר' מאיר ור' יוסי בשעה השישית, \u0003אבל בשבע — דברי הכל שורפין.\u0004","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם נאמר\u0006 שאפשר \u0005לסייע לו\u0006 לר' יוחנן\u0005]\u0006 מסופה של אותה ברייתא, שנאמר: \u0003הפיגול והנותר והטמא, בית שמאי אומרים: אין נשרפין כאחת, ובית הלל אומרים: נשרפין כאחת.\u0004 משמע שדברים שטמאים מן התורה ודינם מן התורה לשריפה לשיטת בית הלל נשרפים כאחד עם דברים שאינם טמאים אלא מדברי סופרים.","ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 ואפשר לדחות: שהרי הפיגול והנותר \u0003אית להו\u0004 \u0005[יש להם]\u0006 \u0003טומאה\u0004 על כל פנים \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הפיגול והנותר — מטמאין את הידים\u0004 הרי שגזרו עליהם חכמים טומאה מסויימת.","ומציעים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 שיש מקור ש\u0003מסייע ליה\u0004 \u0005[לו]?\u0006 ששנינו: \u0003הפת שעיפשה\u0004 (שנתעפשה) \u0003ונפסלה מלאכול לאדם, ו\u0004עדיין \u0003הכלב יכול לאכלה,\u0004 שראויה היא לו — \u0003מטמאה טומאת אוכלין\u0004 אם היה שיעורה \u0003כביצה,\u0004 שעדיין תורת אוכל עליה. ואם היתה תרומה טהורה של חמץ — \u0003נשרפת עם הטמאה בפסח.\u0004 הרי שדבר שאינו ראוי לאכילה, שוב אין מקפידים שלא לשורפו עם הטמא.","ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 בפת שעיפשה, \u0003דעפרא בעלמא\u0004 \u0005[שכעפר סתם]\u0006 נחשב \u0003הוא\u0004 כבר, ואין דינה כבר כאוכל של ממש.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שהראיה היא מדברי ר' חנינא סגן הכהנים \u0003מאי\u0004 \u0005[מה]\u0006 מקום יש כאן להזכיר ולענות לו מכך ש\u0003מודה\u0004 ר' אליעזר ור' יהושע? ומסבירים: \u0003הכי קאמר ליה\u0004 \u0005[כך אמר לו]\u0006 \u0003ר' יוסי לר' מאיר: אפילו לר' יהושע\u0004 שהוא \u0003מיקל\u0004 בכגון זה — \u0003כי\u0004 \u0005[כאשר]\u0006 הוא \u0003מיקל\u0004 הרי זה \u0003בתלויה וטמאה, אבל בטהורה\u0004 גמורה \u0003וטמאה — לא,\u0004 אינו כן.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שלמד ר' מאיר מדברי ר' חנינא סגן הכהנים, \u0003אמאי\u0004 \u0005[מדוע]\u0006 אמר ר' יוסי \u0003אינה היא המדה\u0004 ואי אפשר להשוות? הרי \u0003מדה ומדה היא,\u0004 שכן לדעת ר' מאיר בשעה השישית קיים איסור על הטהורה מדברי סופרים, וכשם שלדברי ר' חנינא ניתן לטמא דבר הטמא רק מדברי סופרים בדבר הטמא מן התורה, אף לר' מאיר ניתן לטמא דבר שאינו אסור אלא מדברי סופרים, בדבר הטמא מן התורה!","\u0003אמר ר' ירמיה: הכא\u0004 \u0005[כאן,\u0006 במשנתנו\u0005]\u0006 מדובר \u0003בבשר שנטמא\u0004 בולד הטומאה על ידי \u0003משקין שנטמאו מחמת שרץ,\u0004 ונעשה על ידי כך שני לטומאה, \u0003ואזדא\u0004 \u0005[והלך]\u0006 \u0003ר' מאיר לטעמיה\u0004 \u0005[לשיטתו]\u0006 \u0003ור' יוסי לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006","כיצד, \u0003ר' מאיר\u0004 הלך בענין זה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר: טומאת משקין לטמא אחרים דרבנן\u0004 \u0005[שמדברי סופרים]\u0006 היא, ואם כן אותו בשר שנטמא בולד הטומאה טהור גמור היה מן התורה, ומכאן הוא מוכיח שמותר לשרוף את הטהור עם הטמא.","\u0003ור' יוסי\u0004 אף הוא \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 הלך, שכן \u0003אמר: טומאת משקין לטמא אחרים דאורייתא\u0004 \u0005[מן התורה]\u0006 היא, ולכן הבשר שהעיד עליו ר' חנינא סגן הכוהנים טמא היה מן התורה, ואין להוכיח מכאן לענין שריפת תרומה טהורה גמורה עם הטמאה בפסח. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 באותו ענין:"],["\u0003ספק משקין ליטמא\u0004 כשיש ספק לגבי משקה מסויים אם אמנם נטמא, הרי הוא \u0003טמא.\u0004 כי ספק זה הוא בדבר שאיסורו מן התורה, וספק שמן התורה פוסקים בו להחמיר. ואולם אם היה הספק \u0003לטמא אחרים — טהור,\u0004 שמשקים מטמאים רק מדברי סופרים, וספק שמדברי סופרים דינו — להקל, אלו \u0003דברי ר' מאיר. וכן היה ר' אלעזר אומר כדבריו. ר' יהודה אומר: לכל טמא,\u0004 גם לטמא אחרים, שלדעתו טומאת משקים היא מן התורה.","\u0003ר' יוסי ור' שמעון אומרים:\u0004 אם ספק הוא אם טימאו משקים אלו \u0003לאוכלין — הרי אוכלים אלו טמאין\u0004 כדין ספק שבדברי תורה, כיון שלדעתם המשקה מטמא אוכל מן התורה. ואולם אם ספק טומאה זה הוא לגבי טומאת \u0003כלים — הרי הם טהורין,\u0004 שכן אף לדעתם אין המשקים מטמאים כלים אלא מדברי סופרים. ולכן כשאינו אלא ספק, הרי הם טהורים. ולעניננו למדנו שאכן נחלקו ר' מאיר ור' יוסי אם טומאת משקים היא מן התורה.","כיון שהוזכרו דברי תוספתא זו שואלים: \u0003וכי סבר ר' אלעזר: משקין אית להו\u0004 \u0005[יש להם]\u0006 \u0003טומאה\u0004 מן התורה \u0003בעולם\u0004 [בכלל]? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אלעזר אומר: אין טומאה למשקין כל עיקר\u0004 מן התורה. \u0003תדע, שהרי העיד יוסף בן יועזר איש צרידה על\u0004 החגב המכונה \u0003איל קמצא\u0004 שהוא \u0003דכן\u0004 \u0005[טהור]\u0006 ומותר באכילה, \u0003ועל משקין\u0004 הנוזלים הנמצאים ב\u0003בית מטבחיא\u0004 \u0005[בבית המטבחיים]\u0006 של בית המקדש שהם \u0003דכן\u0004 \u0005[טהורים]\u0006 ולא גזרו בהם טומאה. ואם משקים אלה טהורים משמע שמן התורה אין טומאת משקים כל עיקר וטומאתם רק מדברי סופרים, והם לא גזרו טומאה במקדש!","ומוסיפים: \u0003הניחא\u0004 \u0005[\u0006דבר \u0005זה נוח]\u0006 \u0003ל\u0004שיטת \u0003שמואל,\u0004 ש\u0003אמר\u0004 כי הביטוי \u0003דכן\u0004 \u0005[טהורים]\u0006 פירושו טהורים \u0003מלטמא טומאת אחרים, אבל טומאת עצמן יש להם, שפיר\u0004 \u0005[יפה].\u0006 ואם ר' אלעזר מחזיק בשיטה זו, הרי מכוונת דעתו לדעת ר' מאיר, שטומאת משקים לטמא אחרים אינה אלא מדברי סופרים. \u0003אלא לרב,\u0004 ש\u0003אמר דכן\u0004 \u0005[טהורים]\u0006 \u0003ממש,\u0004 שמשקים אלה אינם מקבלים טומאה אפילו לגבי טומאת עצמם. \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הלוא לשיטה זו אין טומאה כלל למשקים מן התורה!","ומתרצים, \u0003אמר רב נחמן בר יצחק: אחדא\u0004 \u0005[על אחת],\u0006 כלומר שר' אלעזר הסכים רק לאחד מדברי ר' מאיר, שספק משקים לטמא אחרים — טהור, אך לדעתו אף לגבי ספקם להיטמא טהור, שאין להם טומאה מן התורה.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"כדבריו\"\u0004 של ר' מאיר \u0003קאמר, דנפישי\u0004 \u0005[אמר, שמרובים]\u0006 כלומר בלשון רבים, משמע שמסכים לכל דבריו. \u0003ועוד, והא\u0004 \u0005[והרי]\u0006 \u0003\"וכן\" קתני\u0004 \u0005[שנינו]!\u0006 ומכאן שר' אלעזר מצטרף לשיטת ר' מאיר במלואה! כיון שלא נמצא הסבר לסתירה זו מסכמים כי אכן \u0003קשיא\u0004 \u0005[קשה]\u0006 להבין סתירה זו.","כיון שהובאה עדותו של ר' יוסי בן יועזר דנים בה ל \u0003גופא, רב אמר: דכן\u0004 \u0005[טהורים]\u0006 שאמר ר' יוסי בן יועזר משמע \u0003ממש,\u0004 שאין למשקים אלה כל טומאה בין להיטמא בעצמם, בין לטמא אחרים. \u0003ושמואל אמר: דכן\u0004 \u0005[טהורים]\u0006 משמע \u0003מלטמא טומאת אחרים, אבל טומאת עצמן\u0004 (להיטמא) — \u0003יש להן.\u0004 ומפרשים את הדברים: \u0003רב אמר דכן\u0004 \u0005[טהורים]\u0006 \u0003ממש, קסבר\u0004 \u0005[סבור הוא]\u0006 כי בכלל \u0003טומאת משקין דרבנן\u0004 \u0005[מדברי סופרים]\u0006 היא, ולכן \u0003כי גזרו רבנן\u0004 \u0005[כאשר גזרו חכמים]\u0006 טומאה זו — \u0003במשקין דעלמא\u0004 \u0005[בכלל]\u0006 גזרו, \u0003ו\u0004אולם \u0003במשקין\u0004 של \u0003בית מטבחיא\u0004 \u0005[בית המטבחיים]\u0006 בבית המקדש, \u0003לא גזור\u0004 \u0005[גזרו].\u0006","\u0003ושמואל אמר:\u0004 משמעות \u0003דכן\u0004 \u0005[טהורים]\u0006 הוא \u0003מלטמא טומאת אחרים, אבל טומאת עצמן — יש להן. קסבר\u0004 \u0005[סבור הוא]\u0006 כי \u0003טומאת משקין עצמן\u0004 היא מ\u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 אבל שיהא בהם כדי \u0003לטמא אחרים\u0004 — מ\u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 הוא, \u0003וכי גזור רבנן\u0004 \u0005[וכאשר גזרו חכמים] —\u0006 היה זה \u0003במשקין דעלמא\u0004 \u0005[בכלל],\u0006 אבל \u0003במשקין\u0004 של \u0003בית מטבחיא\u0004 \u0005[בית המטבחיים]\u0006 בבית המקדש — \u0003לא גזור\u0004 \u0005[גזרו].\u0006 \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003לא גזור רבנן\u0004 \u0005[גזרו חכמים]\u0006 בהם — הרי זה \u0003לטמויי\u0004 \u0005[לטמא]\u0006 \u0003אחרים, אבל טומאת עצמן — יש להן\u0004 ככל שאר המשקים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בר חיננא לבריה\u0004 \u0005[לבנו]:\u0006 \u0003כי עיילת לקמיה\u0004 \u0005[כאשר תבוא לפני]\u0006 \u0003רב פפא, רמי ליה\u0004 \u0005[הקשה לו]\u0006 כך: \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר שמואל דכן\u0004 \u0005[טהורים]\u0006 \u0003מלטמא טומאת אחרים, אבל טומאת עצמן — יש להן,\u0004 וכי אפשר לומר שיש דבר שהוא טמא מן התורה ואינו מטמא אחרים? \u0003קרי\u0004 \u0005[קרא]\u0006 \u0003כאן,\u0004 כלומר השתמש אף כאן במקרא הבסיסי שממנו אפשר ללמוד שדבר שהוא טמא בעצמו, ממילא הנוגע בו נטמא אף הוא, שכן נאמר \u0003\"והבשר אשר יגע בכל טמא לא יאכל\u0004 באש ישרף\u0003\"\u0004 (ויקרא ז, יט).","\u0003אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: מידי דהוה\u0004 \u0005[הדבר\u0006 הוא \u0005כשם שהינו]\u0006 לגבי \u0003רביעי בקדש,\u0004 שלכל הדעות רביעי לטומאה שהיה בדבר של קודש אינו מטמא אחרים, אף שהוא עצמו טמא. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 על דחיה זו \u0003רב אשי:\u0004 כיצד אפשר לומר זאת? הרי \u0003רביעי בקדש לא איקרי\u0004 \u0005[נקרא]\u0006 \u0003טמא\u0004 אלא נקרא פסול בלבד, ו\u0003האי איקרי\u0004 \u0005[\u0006ו\u0005זה נקרא]\u0006 \u0003טמא!\u0004 לקושיה זו לא נמצאה תשובה והיא הושארה ב\u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר.","מכאן באים ומנסים להביא ראיות ממקורות שונים להכריע במחלוקת זו של רב ושמואל ותנאים שלפניהם בדבר טומאת משקים מן התורה. \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 נאמר במקרא \u0003\"וכל משקה אשר ישתה בכל כלי יטמא\"\u0004 (ויקרא יא, לד), הרי שמפורש כתוב בתורה שהמשקה נטמא! ודוחים: \u0003מאי\u0004 \u0005[מה\u0006 משמעו\u0005]\u0006 של \u0003\"יטמא\"\u0004 כאן — \u0003הכשיר,\u0004 כלומר שהמשקה הנשפך על מיני מאכל מכשיר אותם לקבל טומאה, כמבואר שם.","ודוחים: \u0003הכשיר\u0004 — הלוא \u0003מרישא דקרא שמעת ליה\u0004 \u0005[מראשו של המקרא שומע אתה\u0006 זאת\u0005],\u0006 שנאמר \u0003\"מכל האכל אשר יאכל\u0004 אשר יבוא עליו מים יטמא\u0003\"\u0004 (ויקרא יא, לד)! ומשיבים: בכל זאת יש צורך בלימוד זה שאין ללמוד מקטע הפסוק הראשון, כי \u0003חד\u0004 \u0005[\u0006קטע \u0005אחד]\u0006 סופו של הפסוק מדבר \u0003ב\u0004מים \u0003תלושין,\u0004 כלומר שנשאבו בכלים ממקורם (\"בכל כלי\"), \u0003וחד\u0004 \u0005[ו\u0006קטע \u0005אחד]\u0006 תחילתו של הפסוק מדבר \u0003במחוברין\u0004 לקרקע.","\u0003וצריכי\u0004 \u0005[ונצרכו]\u0006 שני הדברים ואין ללמוד זה מזה, כיצד? \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 \u0003בתלושין\u0004 בלבד — היינו אומרים שהם מכשירים \u0003משום דאחשבינהו\u0004 \u0005[שהחשיב אותם],\u0006 שהרי הוציאם ושאבם ממקומם, \u0003אבל מחוברין — אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יכשירו לטומאה.","ולהיפך, \u0003ואי תנא\u0004 \u0005[ואם היה שונה]\u0006 רק מים \u0003מחוברין\u0004 — היינו סבורים \u0003משום דקיימי בדוכתייהו\u0004 \u0005[שהם עומדים במקומם] —\u0006 \u0003חשיבי\u0004 \u0005[החשיב אותם],\u0006 \u0003אבל תלושין — אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יכשירו לטומאה, על כן \u0003צריכי\u0004 \u0005[נצרכו].\u0006","כיון שנדחתה ראיה זו מנסים להביא ראיה אחרת \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 שאמר הכתוב \u0003\"אך מעין ובור מקוה מים יהיה טהור\u0004 ונוגע בנבלתם יטמא\u0003\"\u0004 (ויקרא יא, לו) ומכאן נלמד שמים בכלל, חוץ ממי מעין ובור שהם מחוברים, מקבלים טומאה. הרי שטומאת משקים מן התורה! ודוחים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"יהיה טהור\"\u0004 שהטובל באלה יהיה טהור \u0003מטומאתו,\u0004 ואין ללמוד מכאן לטומאת המשקים עצמם.","בתירוץ הקודם היתה הנחה כי הכתוב צריך ללמדנו לענין הכשרה לטומאה הן במים תלושים והן במחוברים, ותוהים: \u0003ותלושין מי\u0004 \u0005[האם]\u0006 \u0003מכשירין\u0004 מן התורה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוסי בר' חנינא: משקין בית מטבחיא\u0004 \u0005[בית המטבחיים]\u0006 בבית המקדש \u0003לא דיין שהן דכן\u0004 \u0005[טהורים]\u0006 מטומאה \u0003אלא שאין מכשירין.\u0004 ומכאן אפשר ללמוד לכאורה שמשקים תלושים אינם מכשירים מדין תורה, שהרי אין בידי החכמים לבטל דין תורה, אלא מכשירים בודאי רק מדברי סופרים, והם לא גזרו בבית המקדש.","ודוחים: \u0003תירגמא\u0004 \u0005[הסבר\u0006 זאת\u0005]\u0006 \u0003על\u0004 ענין \u0003דם,\u0004 שדברי ר' יוסי בר' חנינא לא היו על כל המשקים שבבית המקדש אלא רק על דם שבמקדש, וטעם הלכה זו כפי ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: מנין לדם קדשים\u0004 שנשפך על מאכל, \u0003שאינו מכשיר\u0004 אותו לקבל טומאה — \u0003שנאמר \"\u0004רק הדם לא תאכלו \u0003על הארץ תשפכנו כמים\"\u0004 (דברים יב, טז) ומכאן לומדים: \u0003דם שנשפך כמים\u0004 כלומר דם שחיטת בהמת חולין שהוא נשפך סתם ואין חוששים לקבלו בכלי — \u0003מכשיר\u0004 לטומאה, שרואים שהכתוב משווה אותו למים שנאמר בהם שמכשירים לטומאה."],["\u0003דם שאינו נשפך כמים\u0004 שהוא דם הקדשים שמקבלים אותו בכלי כדי לזורקו על המזבח — \u0003אינו מכשיר\u0004 לטומאה. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב שמואל בר אמי: הרי דם התמצית\u0004 הדם השותת ויוצא מן הבהמה לאחר גמר שחיטתה ש\u0003נשפך כמים,\u0004 כי דם זה אינו ראוי לזריקה על המזבח, \u0003ו\u0004בכל זאת \u0003אינו מכשיר!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא: הנח דם התמצית,\u0004 ש\u0003אפילו בחולין נמי\u0004 \u0005[גם כן]\u0006 \u0003לא מכשיר,\u0004 כי דם זה אינו נחשב דם כלל.","ומעירים: הלכה זו \u0003קבלה מיניה\u0004 \u0005[ממנו]\u0006 \u0003רב שמואל בר אמי\u0004 מר' זירא ומצא סיוע בכתוב להלכה זו, שכן \u0003אמר רחמנא\u0004 \u0005[הכתוב]\u0006 \u0003\"רק חזק לבלתי אכל הדם כי הדם הוא הנפש\"\u0004 (דברים יב, כג), והוא מדייק מלשון הכתוב \u0003דם שהנפש יוצאה בו — קרוי דם, דם שאין הנפש יוצאה בו\u0004 אלא יוצא ושותת אחר כך — \u0003אינו קרוי דם.\u0004","ושוב מנסים להביא ראיה אחרת שטומאת משקים מן התורה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003דם שנטמא וזרקו\u0004 על המזבח, אם זרקו \u0003בשוגג — הורצה\u0004 הקרבן, אם זרקו \u0003במזיד — לא הורצה.\u0004 הרי שדם הקדשים יכול להיטמא מן התורה ואינו טהור אלא מלטמא אחרים! ודוחים: הכוונה היא שנטמא רק \u0003מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003ו\u0004אף \u0003לא כדברי ר' יוסי בן יועזר איש צרידה,\u0004 שהרי לדעתו (על פי שיטת רב) דם קודשים אינו נטמא כלל.","ומנסים להביא ראיה ממשנה אחרת, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003על מה הציץ\u0004 של כהן גדול \u0003מרצה — על הדם ועל הבשר,\u0004 שאם נטמא הבשר לפני זריקת הדם, הציץ מרצה ומותר הדם בזריקה, \u0003ועל החלב, שנטמא בין בשוגג בין במזיד, בין באונס בין ברצון, בין ביחיד בין בצבור.\u0004 הרי שהדם מקבל טומאה!","ודוחים: הכוונה היא שהוא מקבל טומאה \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 בלבד, \u0003ו\u0004גם הלכה זו היא ש\u0003לא כיוסף בן יועזר איש צרידה\u0004 האומר שדם קודשים אינו נטמא.","ומנסים להביא ראיה אחרת, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה שנאמר בציץ: \"והיה על מצח אהרן \u0003ונשא אהרן את עון הקדשים\u0004 אשר יקדישו בני ישראל לכל מתנות קדשיהם והיה על מצחו תמיד לרצון להם לפני ה'\" (שמות כח, לח),","ודרשו חכמים: \u0003וכי איזה עו‍ן הוא נושא\u0004 (מכשיר)? \u0003אם\u0004 תאמר שנושא \u0003עון פיגול — הרי כבר נאמר\u0004 \"ואם האכל יאכל ביום השלישי פיגול הוא \u0003לא ירצה\"\u0004 (ויקרא יט, ז). ו\u0003אם עון נותר — הרי כבר נאמר\u0004 \"ואם האכל יאכל מבשר זבח שלמיו ביום השלישי לא ירצה המקריב אותו \u0003לא יחשב\u0004 לו\" (ויקרא ז, יח).","\u0003הא\u0004 \u0005[הרי]\u0006 ודאי הכוונה היא ש\u0003אינו נושא אלא עון טומאה שהותרה מכללה בציבור,\u0004 שהותר להקריב קרבן ציבור במקדש בטומאה והציץ מכפר על עוון זה. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה גם ל\u0003טומאת דם?\u0004 ונלמד שדם מקבל טומאה! \u0003אמר רב פפא:\u0004 אפשר לדחות, \u0003לא,\u0004 המדובר הוא ב\u0003טומאת קמצים,\u0004 כלומר שנטמא קומץ המנחה שקומצים הכהנים, שהוא המתיר את המנחה כשם שהדם מתיר את הקרבן.","ושוב רוצים להביא ראיה ממקור אחר, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה שנאמר לחגי הנביא: \u0003\"\u0004כה אמר ה' צבאות שאל נא את הכהנים תורה לאמר. \u0003הן ישא איש בשר קדש בכנף בגדו ונגע בכנפו אל הלחם ואל הנזיד ואל היין ואל שמן ואל כל מאכל היקדש ויענו הכהנים ויאמרו לא\"\u0004 (יקדש) (חגי ב, יא-יב)."],["\u0003ואמר רב: אישתבש כהני\u0004 \u0005[טעו הכהנים]\u0006 כי על פי ההלכה דבר כגון זה נטמא. ואגב דרכנו אנו למדים שיש טומאה לא רק בבשר קודש אלא גם במשקים כנזיד, יין, ושמן המנויים שם! את הקושיה דוחים: \u0003מידי\u0004 \u0005[הרי]\u0006 לשיטת מי \u0003הוא טעמא\u0004 \u0005[הטעם]\u0006 \u0003אלא\u0004 לשיטת \u0003רב\u0004 הסבור שמשקים אין להם טומאה מהתורה, ואולם \u0003רב\u0004 בעדותו של יוסי בן יועזר \u0003\"משקי בית מטבחייא\" תני\u0004 \u0005[\" בית המטבחיים\" שנה]\u0006 והן הדם והמים בלבד שהם קשורים בהם בשחיטת— טביחת הקרבנות. \u0003אבל משקי בי מדבחיא\u0004 \u0005[בית המזבח]\u0006 כלומר, שאר משקים המשמשים בקודש, כגון היין והשמן — \u0003מטמא,\u0004 שגזרו חכמים טומאה על משקים ולא הוציאו את משקי המזבח מכללם, אלא משקי בית המטבחיים בלבד. ואם כן, על פי דברי חכמים אכן אותם המשקים שמנה חגי הנביא מקבלים טומאה ומטמאים אחרים.","כיון שהוזכרו דברי רב בענין שאלת חגי לכהנים מרחיבים את הדיבור באותו ענין \u0003גופא\u0004 \u0005[עצמו],\u0006 \u0003רב אמר: אישתבש כהני\u0004 \u0005[טעו הכהנים]\u0006 בתשובתם והיו צריכים לומר שהשמן נטמא, \u0003ושמואל אמר: לא אישתבש כהני\u0004 \u0005[טעו הכהנים].\u0006","ומפרטים, \u0003רב אמר: אישתבש כהני\u0004 \u0005[טעו הכהנים]\u0006 כי \u0003רביעי בקדש בעא מינייהו\u0004 \u0005[שאל מהם]\u0006 אם טמא הוא או לא, שפירשו את השאלה בכתוב באופן זה: אם נושא שרץ מת בכנף בגדו, ונגע בלחם (שהוא לשיטה זו ראשון לטומאה) והלחם בנזיד, (שני לטומאה) והנזיד ביין (שלישי) והיין בשמן (רביעי), \u0003ואמרו ליה\u0004 \u0005[לו]\u0006 \u0003טהור,\u0004 ובכך טעו, שהרי הלכה שהוא טמא בקודש.","\u0003ושמואל אמר: לא אישתבש כהני\u0004 \u0005[טעו הכהנים],\u0006 כי באותה שאלה \u0003חמישי בקדש בעא מינייהו\u0004 \u0005[שאל מהם],\u0006 שיש לפרש את שאלתו כך: שנגע כנף הבגד בשרץ (ובכך הוא נעשה ראשון לטומאה), והבגד בלחם (שני לטומאה), והלחם בנזיד (שלישי), והנזיד ביין (רביעי), והיין בשמן (חמישי). \u0003ואמרו ליה\u0004 \u0005[לו]\u0006 כדין: \u0003טהור.\u0004","ודנים בדבר: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב, היינו דכתיב\u0004 \u0005[זהו שכתוב]\u0006 \u0003ארבעה\u0004 דברים: \u0003לחם ונזיד ויין ושמן,\u0004 הרי שהשאלה היא על רביעי בקודש. \u0003אלא לשמואל, חמשה מנא ליה\u0004 \u0005[מנין לו]?\u0006","ודוחים: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"ונגע כנפו\u0004 אל הלחם וכו' \u0003\"\u0004? כלומר שהטומאה עצמה נגעה בלחם, \u0003\"ונגע בכנפו\" כתיב\u0004 \u0005[נאמר]\u0006 — \u0003במה שנגע בכנפו,\u0004 כלומר לא הטומאה עצמה נגעה בלחם וטמאתו אלא כנף הבגד. והבגד עצמו אינו אב הטומאה אלא רק ראשון לטומאה, הרי שהשמן שבסוף חמישי לטומאה היה, וטהור.","\u0003תא שמע\u0004 ורוצים להביא ראיה ממה שנאמר הלאה מכן \u0003\"ויאמר חגי אם יגע טמא נפש בכל אלה היטמא ויענו הכהנים ויאמרו יטמא\"\u0004 (חגי ב, יג). \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דברי \u0003שמואל, מדהכא\u0004 \u0005[מ\u0006כיון \u0005שכאן]\u0006 בענין טמא נפש \u0003לא אישתבש\u0004 \u0005[טעו]\u0006, שהרי לדבריו שאלתו אכן היתה בחמישי לטומאה — \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 \u0003לא אישתבש\u0004 \u0005[טעו].\u0006 \u0003אלא לרב, מאי שנא הכא דאישתבש, ומאי שנא התם\u0004 \u0005[\u0006ב\u0005מה שונה כאן\u0006 בשרץ \u0005שטעו, ומה שונה שם]\u0006 בטמא לנפש ש\u0003לא אישתבש\u0004 \u0005[טעו]?\u0006","\u0003אמר רב נחמן אמר רבה בר אבוה: בקיאין הן בטומאת מת\u0004 שהיא חמורה ויודעים שעושה רביעי בקודש, \u0003ואין בקיאין הן בטומאת שרץ.\u0004","\u0003רבינא אמר\u0004 הבדל אחר: \u0003התם\u0004 \u0005[שם]\u0006 בשאלה הראשונה, היה זה \u0003רביעי\u0004 בקודש. \u0003הכא\u0004 \u0005[כאן]\u0006 היה זה \u0003שלישי,\u0004 כי מדובר כאן לא במגע בטמא מת אלא במת עצמו שהוא אבי אבות הטומאה, ועל כן היה האחרון רק שלישי לטומאה, ובזה בקיאים היו.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לענין, שנאמר בהמשך \u0003\"ויען חגי ויאמר כן העם הזה וכן הגוי הזה לפני נאם ה'\u0004 וכן כל מעשי ידיהם ואשר יקריבו שם טמא הוא\u0003\"\u0004 (חגי ב, יד), \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב\u0004 שטעו הכהנים - \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \u0003\"טמא\"\u0004 שאם אינם בקיאים בהלכות טומאה, ממילא כל מה שעושים טמא הוא. \u0003אלא לשמואל, אמאי\u0004 \u0005[מדוע]\u0006 \u0003טמא?\u0004","ומשיבים: לשיטת שמואל לא נאמר הפסוק בניחותא \u0003אלא איתמוהי קא מתמה\u0004 \u0005[תמיהה הוא תמה],\u0006 שהוא שואל: האומנם כל מעשי ידיהם טמא? שהרי נראה שבקיאים הם בהלכות טומאה. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"וכן כל מעשה ידיהם\" כתיב\u0004 \u0005[נאמר],\u0006 שהוא לשון ודאות ולא בתמיהה! \u0003אמר מר זוטרא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003רב אשי: מתוך שקלקלו את מעשיהם\u0004 בכלל בעבירות, ונתנבא על העתיד — לכן \u0003מעלה עליהם הכתוב כאילו הקריבו בטומאה.\u0004","כבר הוזכר קודם שהיו חילופי גרסות בדברי ר' יוסי בן יועזר, ומעתה נכנסים לדון בגופו של דבר \u0003גופא\u0004 \u0005[עצמו].\u0006 \u0003רב תני\u0004 \u0005[היה שונה]\u0006 \u0003\"משקי בית מטבחיא\"\u0004 \u0005[בית המטבחיים]\u0006 ובכלל זה רק דם ומים, \u0003ולוי תנא\u0004 \u0005[היה שונה]\u0006 כל \u0003\"משקי בי מדבחיא\"\u0004 \u0005[בית המזבח]\u0006 הכוללים גם יין ושמן הדרושים למנחות ולנסכים.","ומעירים: \u0003ל\u0004שיטת \u0003לוי, הניחא אי סבירא ליה\u0004 \u0005[זה נוח אם סבור הוא]\u0006 \u0003כ\u0004שיטת \u0003שמואל\u0004 ש\u0003אמר\u0004 בעדות יוסי בן יועזר שפירוש \u0003\"דכן\"\u0004 \u0005[טהורים]\u0006 \u0003מלטמא טומאת אחרים אבל טומאת עצמן יש להן — משכחת לה\u0004 \u0005[מוצא אתה אותה\u0006 את האפשרות\u0005],\u0006 להסביר את שאלתו השניה של חגי הנביא, ששאלם על מקרה בו \u0003נגעי כולהו\u0004 \u0005[נגעו כולם]\u0006 \u0003בראשון\u0004 לטומאה. שהוא יפרש שאלת הנביא לא שנגעו דברים שונים זה בזה, כי לשיטה זו אין משקים מטמאים זה את זה, אלא שהנזיד, היין והשמן נגעו כולם בראשון לטומאה עצמו. וכל זאת לשיטת שמואל שאף משקי קודש מקבלים טומאה בעצמם, וכדין ענו הם שאכן יטמא.","\u0003אלא אי סבר ליה\u0004 \u0005[אם סבור הוא]\u0006 \u0003כ\u0004שיטת \u0003רב\u0004 ש\u0003אמר \"דכן\"\u0004 \u0005[טהורים]\u0006 \u0003ממש\u0004 אם כן \u0003היכי משכחת לה\u0004 \u0005[כיצד מוצא אתה אותה\u0006 אפשרות\u0005]\u0006 למצוא טומאה לשיטת לוי ביין ושמן, שהם משקי המזבח. אלא \u0003על כרחך\u0004 יש להוכיח מכאן כי \u0003כשמואל סבירא ליה\u0004 \u0005[סבור הוא]\u0006 לענין פירוש 'דכן'.","ועוד מעירים: \u0003ולשמואל, הניחא\u0004 \u0005[זה נוח]\u0006 \u0003אי סבר לה\u0004 \u0005[אם סבור הוא]\u0006 לענין גרסת הגזירה \u0003כרב, דתני \"משקי בית מטבחיא\"\u0004 \u0005[השונה משקי בית המטבחיים]\u0006 \u0003אבל \"משקי בי מדבחיא\"\u0004 \u0005[בית המזבח]\u0006 \u0003אחריני נמי מיטמאו\u0004 \u0005[אחרים גם כן מטמאים],\u0006 ו\u0003רביעי הוא\u0004 ש\u0003לא עביד\u0004 \u0005[עושה]\u0006 \u0003חמישי, הא\u0004 \u0005[הרי,\u0006 אבל\u0005]\u0006 \u0003שלישי — עביד\u0004 \u0005[עושה]\u0006 \u0003רביעי,\u0004 ויש מקום לשאלת חגי.","\u0003אלא אי סבר ליה\u0004 \u0005[אם סבור הוא]\u0006 \u0003כ\u0004שיטת \u0003לוי דתני \"משקי בי מדבחיא\"\u0004 \u0005[השונה משקי בית המזבח]\u0006 הכוללים גם יין ושמן, \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דוקא\u0005]\u0006 \u0003רביעי דלא עביד\u0004 \u0005[שאינו עושה]\u0006 \u0003חמישי? אפילו שני ושלישי נמי\u0004 \u0005[גם כן]\u0006 \u0003לא עבדי\u0004 \u0005[עושים]\u0006 שהרי אף לשיטת שמואל משקי קודש אינם מטמאים! אלא: \u0003על כרחיך\u0004 עליך לומר שלענין הגרסה — \u0003כ\u0004שיטת \u0003רב סבירא ליה\u0004 \u0005[סבור הוא].\u0006","ולבירור הגרסות מעירים כי \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003רב, תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא אחרת \u0005כשיטת]\u0006 \u0003לוי.\u0004 ומפרטים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003לוי, הדם והיין והשמן והמים,\u0004 כל אלא \u0003משקי בי מדבחיא\u0004 \u0005[בית המזבח]\u0006 \u0003שנטמאו בפנים\u0004 (בקודש) \u0003והוציאן לחוץ — טהורין\u0004 מלטמא אחרים, אף שהם עצמם טמאים, שבהיותם בקודש לא חלה עליהם טומאה חמורה. \u0003נטמאו בחוץ והכניסם בפנים — טמאין\u0004 אפילו לטמא אחרים, שאני אומר שדברים שנכנסו לבית המקדש אין טומאה בטלה מהם.","לגופה של הלכה זו שואלים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יהושע בן לוי: משקי בי מדבחיא\u0004 \u0005[בית המזבח]\u0006 \u0003לא אמרו דכן\u0004 \u0005[טהורים\u0006 הם\u0005]\u0006 \u0003אלא במקומן. מאי לאו\u0004 \u0005[האם לא]\u0006 שבאו דבריו \u0005—\u0006 \u0003למעוטי\u0004 \u0005[למעט]\u0006 ש\u0003נטמאו בפנים והוציאן לחוץ,\u0004 שחלה עליהם טומאה למפרע, ובניגוד לדברים שאמרנו! ודוחים: \u0003לא\u0004 כן, אלא באו הדברים \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003נטמאו בחוץ והכניסן בפנים.\u0004","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"במקומן\" קאמר\u0004 \u0005[אמר],\u0006 משמע שטהרתם היא במקומם בלבד! ומתקנים: \u0003הכי קאמר\u0004 \u0005[כך אמר\u0006 כך יש להבין\u0005]\u0006 \u0003לא אמרו דכן\u0004 \u0005[טהורים] —\u0006 \u0003אלא שנטמאו במקומן.\u0004 ומכל מקום לענין הגרסה למדנו מכאן שגם היין והשמן בכלל משקי הקודש הם כדברי לוי.","ו\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא אחרת \u0005כשיטת]\u0006 \u0003רב, הדם והמים\u0004 שהם \u0003משקי בית מטבחיא\u0004 \u0005[בית המטבחיים]\u0006 הדברים השייכים לשחיטה בלבד, \u0003שנטמאו בין\u0004 שהיו \u0003בכלים בין בקרקע — טהורין.\u0004"],["\u0003רבן שמעון אומר:\u0004 אם היו משקים אלה \u0003בכלים — טמאין\u0004 הם, אבל אם היו הם \u0003בקרקע — טהורין\u0004 וכאשר יבואר טעמו להלן.","\u0003אמר רב פפא — אפילו ל\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 שבכלל \u0003טומאת משקין דאורייתא\u0004 \u0005[מן התורה]\u0006 היא — \u0003משקי בית מטבחיא הלכתא גמירי לה\u0004 \u0005[\u0006טהרת \u0005משקה בית המטבחיים\u0006 במקדש \u0005הלכה\u0006 למשה מסיני \u0005למדו אותה]\u0006 שאין טומאה חלה עליהם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן לרב פפא: ואלא הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 ש\u0003אמר ר' אליעזר: אין טומאה למשקין כל עיקר, תדע, שהרי העיד יוסף בן יועזר איש צרידה על משקי בית מטבחיא\u0004 \u0005[בית המטבחיים]\u0006 שהם \u0003דכן\u0004 \u0005[טהורים]\u0006 ומכאן הסיק שטומאת משקים אינה אלא גזירת חכמים בלבד, ולא גזרו חכמים במקדש.","\u0003ואי הלכתא גמירי לה\u0004 \u0005[ואם הלכה\u0006 למשה מסיני היא \u0005שלמדו אותה] —\u0006 \u0003מי גמרינן מינה\u0004 \u0005[האם לומדים אנו ממנה]?\u0006 שידוע שאין למדים כללי הלכה מדבר שהוא הלכה למשה מסיני, ואיך הביא אם כן ר' אליעזר ראיה לדבריו מהלכה זו.","ועוד, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי\u0004 בדחיית דברי רב פפא: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' שמעון\u0004 ש\u0003אמר\u0004 בכלל \u0003טומאת משקין דאורייתא\u0004 \u0005[מן התורה]\u0006 היא, \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' יוסי ור' שמעון אומרים: לכלים — טהורין,\u0004 שאין משקה מטמא כלי מן התורה. \u0003לאוכלין — טמאין,\u0004 שהמשקים מטמאים אוכלים מן התורה.","\u0003והכא\u0004 \u0005[וכאן]\u0006 לענין משקי בית המקדש \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' שמעון: בכלים — טמאין, בקרקע — טהורין. ואי\u0004 \u0005[ואם]\u0006 אומר אתה שטהרת משקה בית המטבחיים \u0003הלכתא\u0004 \u0005[הלכה\u0006 למשה מסיני\u0005]\u0006 \u0003היא, מה לי בכלים מה לי בקרקע?\u0004 שאם הלכה מקובלת בידינו שאין טומאה חלה עליהם, אין לחלק בין קרקע לכלים. ומעירים: אכן \u0003קשיא\u0004 \u0005[קשה]\u0006 לשיטת רב פפא.","\u0003אמר רב פפא: הא\u0004 \u0005[זה]\u0006 ש\u0003אמרת\u0004 שמשקי המקדש \u0003בקרקע טהורין — לא שנו אלא מים, אבל דם — לא.\u0004 שדם, גם אם היה בקרקע הריהו מקבל טומאה לשיטת ר' שמעון.","\u0003ומים נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא דהוי\u0004 \u0005[שהיה]\u0006 שיעורם \u0003רביעית\u0004 הלוג, \u0003דחזי\u0004 \u0005[שראוי]\u0006 \u0003להטביל ביה מחטין וצינורות.\u0004 שמן התורה מי גשמים בשיעור רביעית שנקוו במקומם הרי הם כמקוה טהרה לכל דבר, ואפשר להטביל בהם דברים קטנים כגון מחטים וצינורות שנכנסים ומתכסים בתוכם, ונמצא שמי רביעית הריהם כמקוה שאינו מקבל טומאה כלל. ואף שחכמים גזרו שלא להשתמש במי רביעית לטהרת כלים, מכל מקום מן התורה מים אלה טהורים, ולכן לא גזרו חכמים טומאה עליהם במקדש. \u0003אבל\u0004 אם \u0003לא הוי\u0004 \u0005[אין הם]\u0006 \u0003רביעית —\u0004 אף מים שבקרקע \u0003טמאים,\u0004 שהרי אינם יכולים להיחשב כמקוה, ולכן אינם נכנסים בגדר המים הטהורים מדין תורה.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא שעסקה בדין ספק מגע משקים הטמאים, \u0003ר' יהודה אומר: לכל טמא\u0004 שבספק אם נגעו המשקים בכלים, אף הם טמאים. \u0003למימרא\u0004 \u0005[האם לומר]\u0006 מכאן ש\u0003סבר ר' יהודה\u0004 כי \u0003טומאת משקין לטמא טומאת כלים דאורייתא\u0004 \u0005[מן התורה]\u0006 היא?","\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל הכלים שיש להם אחורים ותוך,\u0004 כלומר שיש בהם בית קיבול, ולכן יש להם גם פנים וגם צד חיצוני, וניתן להשתמש בהם משני צידיהם, \u0003כגון הכרים והכסתות והשקין והמרצופין\u0004 (מעין שקים מעור שמכניסים בתוכם תבואה) בכל אלה, אם \u0003נטמא תוכו\u0004 של הכלי — \u0003נטמא גבו, נטמא גבו — לא נטמא תוכו.\u0004 שכיון שעיקר השימוש בכלי הוא בתוכו, אין טומאת גבו מטמאה אף את תוכו.","\u0003אמר ר' יהודה: במה דברים אמורים — שנטמאו\u0004 כלים אלה \u0003מחמת משקין\u0004 טמאים שנגעו בהם, \u0003אבל\u0004 אם \u0003נטמאו מחמת שרץ\u0004 הרי אם \u0003נטמא תוכו — נטמא גבו,\u0004 אם \u0003נטמא גבו — נטמא תוכו.\u0004","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003טומאת משקין לטמא את הכלים\u0004 מ\u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 היא, \u0003מה לי נטמא\u0004 הכלי \u0003מחמת משקין, מה לי נטמא מחמת שרץ?\u0004 אלא ודאי לשיטת ר' יהודה אינה אלא מדברי סופרים שחילקו בין טומאת גבו לטומאת תוכו כדי ליצור היכר בין טומאה זו לטומאה שמן התורה, לומר שאין שורפים תרומה עליה. \u0003אמר רב יהודה אמר שמואל: חזר בו ר' יהודה\u0004 משיטתו המפורשת בברייתא, וקיבל את השיטה שטומאת משקים היא רק מדברי סופרים.","\u0003רבינא אמר: לעולם\u0004 יכול אתה לפרש ש\u0003לא הדר\u0004 \u0005[חזר בו]\u0006 מדבריו, אלא \u0003הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 שיש לחלק בין תוכו וגבו — \u0003במשקין הבאין מחמת ידים,\u0004 כלומר שנטמאו מחמת מגע בסתם ידים שלא נרחצו, שרק חכמים הם שגזרו טומאה בכך. וטומאת משקים אלה ודאי מדברי סופרים היא. \u0003הא\u0004 \u0005[זה]\u0006 שאמר טומאת משקים מן התורה — \u0003במשקין הבאין מחמת שרץ,\u0004 ובמשקים אלו אין חילוק אם נגעו בתוכו או בגבו.","מקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אדתני\u0004 \u0005[עד ש\u0006הוא \u0005שונה]\u0006 \u0003\"במה דברים אמורים שנטמאו מחמת משקין\". ליפלוג וליתני בדידה\u0004 \u0005[שיחלוק וישנה בה עצמה]\u0006 בתוך משנה זו: \u0003במה דברים אמורים — במשקין הבאין מחמת ידים. אבל במשקין הבאין מחמת שרץ — נטמא תוכו נטמא גבו, נטמא גבו — נטמא תוכו! אלא\u0004 עלינו לחזור בנו מפירוש זה ו\u0003מחוורתא כדשנין מעיקרא\u0004 \u0005[ברור כפי שתירצנו בתחילה]\u0006 ש\u0003חזר בו ר' יהודה.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 האם רק מן ההנחה שטומאת משקים לטמא \u0003כלים\u0004 מן התורה \u0003הוא דהדר ביה\u0004 \u0005[שחזר בו],\u0006 \u0003אבל באוכלין\u0004 עדיין \u0003כר' יוסי ור' שמעון סבירא ליה\u0004 \u0005[סבור הוא],\u0006 שטומאת משקים לטמא אוכלים היא מן התורה. \u0003או דילמא\u0004 \u0005[שמא]:\u0006 \u0003לגמרי הדר ביה\u0004 \u0005[חזר בו]\u0006 \u0003כ\u0004שיטת \u0003ר' מאיר,\u0004 הסבור שטומאת משקים אינה מן התורה כלל?","\u0003אמר רב נחמן בר יצחק: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלתך ממשנה זו: \u0003פרה ששתתה מי חטאת\u0004 (מי אפר פרה אדומה שמזים לטהר מטומאת המת) ונשחטה לפני שנתעכלו המים במעיה — \u0003בשרה טמא\u0004 על ידי מים אלה, כי מי חטאת מטמאים את הטהורים מגזירת הכתוב. \u0003ר' יהודה אומר:\u0004"],["\u0003בטלו במעיה\u0004 ושוב אינם מטמאים. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 \u0003מכלים הוא דהדר ביה\u0004 \u0005[שחזר בו]\u0006 שאין משקים מטמאים את הכלים, \u0003אבל באוכלין כר' יוסי ור' שמעון סבירא ליה\u0004 \u0005[סבור הוא]\u0006 שמשקים מטמאים אוכלים מן התורה. \u0003אמאי\u0004 \u0005[מדוע]\u0006 אומר הוא כי מי חטאת \u0003בטלו במעיה לגמרי,\u0004 ושוב אינם מטמאים כלל?","\u0003נהי\u0004 \u0005[אף כי]\u0006 ש\u0003טומאה חמורה לא מטמאו\u0004 \u0005[מטמאים],\u0006 ואין אדם וכלים הנוגעים בהם נטמאים, כיון ששוב אינם ראויים להזייה, בכל אופן עדיין \u0003טומאה קלה\u0004 לטמא אוכלים ובשר \u0003מיהא ניטמאו\u0004 \u0005[מכל מקום יטמאו]!\u0006 ואם כן, אפשר להוכיח מכאן שחזר בו ר' יהודה לגמרי וסבור שטומאת משקים אינה מן התורה בכלל. וכיון שרק מדברי חכמים היא, לא גזרו חכמים במקרה נדיר כגון זה.","ודוחים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"בטלו במעיה\"\u0004 שאמר ר' יהודה \u0003נמי\u0004 \u0005[גם כן]\u0006 משמעו: \u0003בטלו מטומאה חמורה\u0004 בלבד. ומקשים: אם כן, לפי תירוץ זה \u0003אבל טומאה קלה מטמאו\u0004 \u0005[מטמאים\u0006 הם\u0005]\u0006 לדברי ר' יהודה, \u0003מכלל\u0004 הדברים נלמד \u0003דתנא קמא\u0004 \u0005[שהתנא הראשון]\u0006 \u0003סבר: טומאה חמורה נמי\u0004 \u0005[גם כן]\u0006 \u0003מטמאו\u0004 \u0005[מטמאים\u0006 הם\u0005],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003\"בשרה טמא\" קתני\u0004 \u0005[שנינו],\u0006 ומכאן ברור שרק בשרה טמא, אבל אין המים מטמאים עוד אדם וכלים. ואם כן, אין איפוא כל הבדל בין השיטות!","ומתרצים: אפשר להסביר כי כל המשנה \u0003כולה\u0004 כשיטת \u0003ר' יהודה היא, וחסורי מיחסרא, והכי קתני\u0004 \u0005[וחסרה\u0006 המשנה, \u0005וכך יש לשנותה]\u0006 ולהשלים לשונה: \u0003פרה ששתתה מי חטאת — בשרה טמא, במה דברים אמורים\u0004 — שטמאה \u0003טומאה קלה, אבל טומאה חמורה — לא, שר' יהודה אומר: בטלו\u0004 המים \u0003במעיה\u0004 ואין להם דין מי חטאת ממש, ואין טומאתם אלא כשאר משקים שטמאים רק מדברי סופרים.","\u0003רב אשי אמר: לעולם\u0004 אפשר לפרש \u0003בטלו במעיה לגמרי\u0004 מכל טומאה שבעולם, ואין הדבר תלוי בשאלה אם טומאת משקים מן התורה או מדברי סופרים, אלא טעמו של דבר \u0003משום דהוה ליה\u0004 \u0005[שנהיו להם]\u0006 מי החטאת \u0003משקה סרוח,\u0004 וכלל הוא כי משקה סרוח איננו נטמא ואינו מטמא.","שנינו בברייתא לענין ספק טומאה של משקים כי \u0003ר' יוסי ור' שמעון אומרים:\u0004 אם לטמא \u0003לאוכלין — טמאין, לכלים — טהורין. אמר רבה בר בר חנה אמר ריש לקיש: ר' יוסי בשיטת ר' עקיבא רבו אמרה\u0004 את ההלכה הזו, \u0003דדריש\u0004 \u0005[ש\u0006הוא \u0005דרש]\u0006 את המלה \u0003'יטמא'\u0004 בבנין הקל שנאמרה בדיני טומאה כאילו היה כתוב \u0003יטמא\u0004 בפיעל, שמשמעו — יטמא אחרים.","\u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003בו ביום\u0004 שמינו לנשיאות את ר' אלעזר בן עזריה \u0003דרש ר' עקיבא: \"וכל כלי חרש אשר יפל מהם\u0004 אל תוכו כל אשר בתוכו יטמא ואותו תשבורו\u0003\"\u0004 (ויקרא יא, לג), \u0003אינו אומר \"טמא\" אלא \"יטמא\"\u0004 — ללמדנו כי אף \u0003יטמא אחרים, לימד על ככר שני\u0004 ככר שנטמאה על ידי כלי שנטמא מחמת השרץ והוא שני לטומאה, \u0003שעושה\u0004 במגעו \u0003שלישי\u0004 לטומאה אף \u0003בחולין.\u0004","ושואלים: \u0003והכא\u0004 \u0005[וכאן]\u0006 לענין טומאת משקים \u0003היכי דריש\u0004 \u0005[כיצד דרש]\u0006 ר' יוסי על פי שיטה זו? ומשיבים: נאמר \u0003\"\u0004מכל האוכל אשר יאכל אשר יבוא עליו מים יטמא \u0003וכל משקה אשר ישתה בכל כלי יטמא\"\u0004 (ויקרא יא, לד), וכיון שנאמר במשקה \u0003יטמא\u0004 נלמד שמשמעו שהוא גם מטמא אחרים, שטומאתו אף \u0003לטמא טומאת אוכלין.\u0004 ודנים: \u0003אתה אומר\u0004 שבא ביטוי זה ללמד \u0003לטמא טומאת אוכלין, או\u0004 אולי \u0003אינו\u0004 בא \u0003אלא\u0004 ללמד \u0003לטמא טומאת משקין\u0004 שמשקים אלה יטמאו משקים אחרים, אבל לא את האוכל? \u0003אמרת\u0004 (משיב אתה): \u0003לא כך היה\u0004 כלומר, אי אפשר לומר כן.","ותוהים על כוונתו של ביטוי זה: \u0003מאי\u0004 \u0005[מה\u0006 משמע\u0005]\u0006 \u0003\"לא כך היה\"? אמר רב פפא:\u0004 כוונתו, ש\u0003לא מצינו\u0004 (מצאנו) \u0003טומאה שעושה כיוצא בה,\u0004 שאין טומאה גורמת לטמא דבר אחר שהוא כמותה. ולכן אין לומר שהמשקה יטמא רק משקה אחר, אלא ודאי מטמא גם אוכל.","\u0003רבינא אמר: מגופיה דקרא נמי לא מצית אמרת\u0004 \u0005[מגופו של המקרא גם כן אין אתה יכול לומר,\u0006 לפרש\u0005]\u0006 \u0003\"יטמא\" — לטמא טומאת משקין. דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר ש\u0003\"יטמא\" דסיפא\u0004 \u0005[של סופו\u0006 של הפסוק\u0005]\u0006 כוונתו \u0003לטמא טומאת משקין, \"יטמא\" דרישא\u0004 \u0005[שבתחילה]\u0006 שנאמר במאכל, \u0003נמי\u0004 \u0005[גם כן]\u0006 כוונתו \u0003לטמא טומאת משקין.\u0004 ואם כן, \u0003ניערבינהו וניכתבינהו\u0004 \u0005[שיערב אותם\u0006 הכתוב את שני הדברים \u0005ויכתבם\u0006 יחד\u0005]\u0006 בצורה זו: \u0003\"מכל האכל אשר יאכל אשר יבוא עליו מים וכל משקה אשר ישתה בכל כלי יטמא\",\u0004","ואולם \u0003תרי\u0004 \u0005[שני]\u0006 \u0003\"יטמא\"\u0004 בכל פיסקה לחוד \u0003למה לי? אלא\u0004 ודאי כך יש להבין: \u0003\"יטמא\" דרישא\u0004 \u0005[שבתחילה]\u0006 ללמדנו \u0003לטמא טומאת משקין\u0004 טמאים הנוגעים באוכל שמטמאים אותו, \u0003\"יטמא\" דסיפא\u0004 \u0005[שבסוף]\u0006 ללמדנו \u0003לטמא טומאת אוכלין\u0004 את האוכל הנוגע במשקה הטמא.","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שכוונתו \u0003לטמא את הכלים!\u0004 ודוחים: \u0003ולאו\u0004 \u0005[ו\u0006כי \u0005לא]\u0006 \u0003קל וחומר הוא, ומה כלי\u0004 טמא שכוח טומאתו מגיע ש\u0003מטמא משקה\u0004 שבתוכו — בכל זאת \u0003אין מטמא כלי\u0004 אחר, \u0003משקין הבאין\u0004 לטומאה \u0003מחמת כלי — אינו דין שלא יטמאו את הכלים?\u0004","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 אולי כך: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא מטמאו\u0004 משקים טמאים את הכלי, הרי זה ב\u0003משקין הבאין\u0004 לטומאתם \u0003מחמת כלי\u0004 טמא, שהרי הכלי שטימא אותם עצמו אינו מטמא כלי. \u0003אבל משקין הבאין מחמת שרץ\u0004 שיש בהם טומאה חמורה לעצמם, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 \u0003דמטמאו\u0004 \u0005[שמטמאים]\u0006 אף כלים! ודוחים: \u0003משקין הבאין מחמת שרץ\u0004 עצמו \u0003מי כתיבי\u0004 \u0005[האם נכתבו]\u0006 במפורש בתורה?"],["\u0003ולאו\u0004 \u0005[ו\u0006כי \u0005לא]\u0006 \u0003מקל וחומר קאתי\u0004 \u0005[בא],\u0006 ובדרך זו: \u0003ומה משקין הבאין\u0004 לטומאתן \u0003מחמת כלי\u0004 שנטמא מן השרץ — \u0003מטמאין, משקין הבאין\u0004 לטומאה \u0003מחמת שרץ — לא כל שכן\u0004 שיטמאו אף כלי!","אך מאחר שעיקר דין משקים אלה נלמד בקל וחומר, אין להוסיף חומרה במשקים שנטמאו מחמת שרץ, על פי הכלל: \u0003דיו לבא מן הדין להיות כנדון,\u0004 כלומר: דבר הנלמד מקל וחומר אין להחמיר בו יותר מן הדבר שממנו הוא נלמד, ולכן משקים הבאים מחמת שרץ מטמאים רק כמשקים הבאין מחמת כלי.","ושואלים: \u0003\"יטמא\" דרישא היכי דריש\u0004 \u0005[שבתחילת\u0006 הפסוק \u0005כיצד דורשו\u0006 ר' עקיבא\u0005]?\u0006 \u0003\"מכל האכל אשר יאכל אשר יבא עליו מים יטמא\"\u0004 (ויקרא יא, לד), ונלמד: \u0003יטמא\u0004 — כלומר, \u0003לטמא את המשקין. אתה אומר\u0004 שאפשר ללמוד מכאן \u0003לטמא את המשקין, או אינו\u0004 בא ללמד \u0003אלא לטמא את הכלי?\u0004","\u0003אמרת קל וחומר\u0004 לשלול אפשרות זו: \u0003ומה משקה\u0004 שיפה כוחו \u0003שמטמא אוכל,\u0004 בכל זאת \u0003אינו מטמא כלי. אוכל שאין מטמא אוכל — אינו דין שלא יטמא כלי. הא מה אני מקיים \"יטמא\"\u0004 שמשמעו שמוסיף טומאה גם למשהו אחר — \u0003לטמא את המשקין שהן עלולין לקבל טומאה,\u0004 כלומר הם רגישים ומסוגלים לקבלת הטומאה.","על הוכחה זו שואלים: \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע שנה\u0005]\u0006 \u0003משקין משום\u0004 ש\u0003עלולין לקבל טומאה, תיפוק ליה\u0004 \u0005[תצא לו]\u0006 הוכחה זו מטעם אחר \u0003משום דליכא מידי אחרינא\u0004 \u0005[שאין דבר אחר]\u0006 שיטמא, שאם אוכל אינו מטמא אוכל, לא נותר אלא שיטמא משקים!","ומתרצים: \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבין\u0005],\u0006 \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003אוכל\u0004 כיון ש\u0003חמור\u0004 כח טומאתו, שכן הוא \u0003מטמא משקין\u0004 אף שמשקים עצמם אינן מטמאים משקים, אם כן אף \u0003ניטמייה\u0004 \u0005[יטמא]\u0006 \u0003לכלי,\u0004 אף שאין המשקה מטמא כלי. על כן מסבירים כי \u0003ההוא\u0004 \u0005[דבר זה]\u0006 שמטמא משקים \u0003חומרא\u0004 של \u0003משקין הוא.\u0004 שאין להבין שבאוכל יש טומאה חמורה, אלא \u0003משום\u0004 רגישותם של ה\u0003משקין\u0004 לטומאה כי הם \u0003עלולין לקבל טומאה.\u0004","\u0003ומה היא עלילתן\u0004 \u0005[\u0006אותה \u0005רגישות שבהם]\u0006 — \u0003שמקבלין טומאה שלא בהכשר,\u0004 שהרי דבר מאכל אינו מקבל טומאה אלא אם כן היו עליו קודם מים או שאר משקים, שהכשירוהו לקבל טומאה. אבל משקים אינם צריכים כל הכשר לקבלת טומאה.","ושואלים: כיון שחזר הכתוב והדגיש \"יטמא\" ולמדנו מכאן ש\u0003יטמא\u0004 כוונתו — ש\u0003אין עושה\u0004 טומאה \u0003כיוצא בה\u0004 שאין אוכל מטמא אוכל וכו', האם \u0003מהכא נפקא\u0004 \u0005[מכאן\u0006 מפסוק זה, היא \u0005יוצאת,\u0006 נלמדת\u0005]?\u0006 הרי \u0003מהתם נפקא\u0004 \u0005[משם\u0006 היא \u0005יוצאת\u0006 נלמדת\u0005]\u0006 שנאמר \u0003\"וכי יתן מים על זרע ונפל מנבלתם עליו טמא הוא\u0004 לכם\u0003\"\u0004 (ויקרא יא, לח), ומדקדקים מן ההדגשה \"הוא\", שמשמעו: \u0003הוא\u0004 עצמו \u0003טמא, ו\u0004אולם \u0003אין עושה טומאה כיוצא בה,\u0004 ולשם מה אם כן צריך הדגשה נוספת לאותו ענין? ומתרצים: יש צורך בשני לימודים, \u0003אחד\u0004 בא ללמדנו הלכה זו \u0003במשקין הבאין\u0004 לטומאה \u0003מחמת שרץ\u0004 שנגעו בו, והאחר \u0003במשקין הבאין\u0004 לטומאה \u0003מחמת כלי\u0004 טמא שנגעו בו.","\u0003וצריכי\u0004 \u0005[ונצרכו]\u0006 שני הפסוקים, ואינם למדים זה מזה. כיצד? \u0003דאי אשמועינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 \u0003במשקין הבאין מחמת כלי\u0004 בלבד היינו אומרים שאינם עושים כיוצא בהם \u0003משום\u0004 ש\u0003לא חמירי\u0004 \u0005[חמורים]\u0006 שהרי לא קבלו טומאתם במישרין מאב הטומאה. \u0003אבל במשקין הבאין מחמת שרץ דחמירי\u0004 \u0005[ש\u0006הם \u0005חמורים],\u0006 שהרי נטמאו מאב הטומאה, \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003עושה טומאה כיוצא בה.\u0004","ושואלים: \u0003ו\u0004אם כן, \u0003לשמעינן\u0004 \u0005[ושישמיע לנו]\u0006 הלכה זו רק ב\u0003משקין הבאין מחמת שרץ\u0004 שאין עושים טומאה כיוצא בהם, \u0003ו\u0004נלמד \u0003כל שכן\u0004 לענין \u0003משקין הבאין מחמת כלי!\u0004 ומשיבים: זו אינה קושיה, כי לפעמים \u0003מילתא דאתיא\u0004 \u0005[דבר הבא,\u0006 הנלמד\u0005]\u0006 \u0003בקל וחומר — טרח וכתב לה קרא\u0004 \u0005[אותו המקרא]\u0006 במפורש ואין לראות בכך ייתור.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: והא\u0004 \u0005[והרי]\u0006 \u0003אמר רבא: לא ר' יוסי סבר כר' עקיבא\u0004 לענין דיני טומאת שלישי בחולין, שלדעתו — בניגוד לדעת ר' עקיבא — שני עושה שלישי בחולין מן התורה,","\u0003ולא ר' עקיבא סבר כר' יוסי\u0004 לענין טומאת רביעי בקודש!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ר' יוסי בשיטת ר' עקיבא רבו אמרה\u0004 להלכה זו, \u0003וליה לא סבירא ליה\u0004 \u0005[והוא עצמו אינו סבור אותה],\u0006 ואינו מקבל הלכה זו, ולדבריו אין טומאת משקים לטמא אחרים מן התורה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרב כהנא\u0004 על דברי רבא: \u0003בשלמא\u0004 \u0005[נניח]\u0006 ממה שאמרנו כי \u0003ר' יוסי לא סבר לה כר' עקיבא,\u0004 יש הוכחה לדבר מן הברייתא. \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמר ר' יוסי: מניין לרביעי בקודש שהוא פסול\u0004 בלבד, ואינו מטמא אחרים?","נלמד דבר זה כך: \u0003ודין הוא, ומה מחוסר כפורים\u0004 שהוא אדם שטבל לטהרתו אבל עדיין לא הביא את קרבן כפרתו (כגון זב ומצורע) \u0003שמותר\u0004 באכילת \u0003תרומה,\u0004 ואם נגע בקודש הרי הוא \u0003פסול בקודש. שלישי\u0004 לטומאה \u0003שפסול בתרומה,\u0004 ואם כן חמור הוא ממחוסר כיפורים — \u0003אינו דין שיעשה רביעי בקודש?\u0004 לפחות כמו מחוסר כיפורים.","ושואלים: הרי \u0003למדנו שלישי בקודש מן התורה, ורביעי\u0004 בקודש \u0003מקל וחומר\u0004 זה, ודיו לבא מן הדין להיות כנידון, ואף קודש לא יעשה רביעי אלא שלישי בלבד, כמו תרומה ממנה הוא נלמד.","ומבארים: \u0003שלישי מן התורה\u0004 כיצד? \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"והבשר אשר יגע\u0004"],["\u0003בכל טמא לא יאכל\"\u0004 (ויקרא ז, יט) \u0003מי לא עסקינן\u0004 \u0005[האם אין אנו עוסקים]\u0006 אפילו במקרה ש\u0003נגע\u0004 אותו בשר \u0003בשני\u0004 לטומאה (שעליו מפורש בתורה שהוא טמא), ומכאן נלמד שדבר הנוגע בשני לטומאה נקרא אף הוא טמא. \u0003רביעי מקל וחומר, כדאמרינן\u0004 \u0005[כמו שאמרנו].\u0006","\u0003ואי סלקא דעתך\u0004 \u0005[ואם יעלה על דעתך]\u0006 ש\u0003סבר\u0004 ר' יוסי \u0003כר' עקיבא\u0004 שיש בחולין שלישי לטומאה, \u0003ניתני נמי\u0004 \u0005[שישנה גם כן]:\u0006 \u0003רביעי בתרומה וחמישי בקודש\u0004 על פי אותו קל וחומר שהשתמש בו. וכיון שאינו עושה כן, הרי זו ראיה שאין ר' יוסי מקבל את דעת ר' עקיבא בדבר זה.","\u0003אלא\u0004 ש\u0003ר' עקיבא לא סבר כר' יוסי מנלן\u0004 \u0005[מניין לנו]?\u0006","שמא קיבל את שיטת קל וחומר של ר' יוסי, ולדעתו יש באמת רביעי בתרומה וחמישי בקודש, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 יש ראיה — אמנם לא ישירה — לדבר זה: ש\u0003לא\u0004 יתכן \u0003לישתמיט\u0004 \u0005[שישתמט]\u0006 הדבר שלא יהיה \u0003תנא\u0004 אחד לפחות \u0003וליתני\u0004 \u0005[שישנה]\u0006 גם \u0003רביעי בתרומה וחמישי בקודש, ונימא\u0004 \u0005[ונאמר]\u0006 שיטת \u0003ר' עקיבא היא\u0004 שלמד קל וחומר כשיטת ר' יוסי. וכיון שלא מצאנו מקור כזה — מן הסתם אין ר' עקיבא סבור כר' יוסי. ושואלים: \u0003ואנן אהכי ניקום ונסמוך\u0004 \u0005[ואנחנו על כך נעמוד ונסמוך]?!\u0006 מה טיבה של הוכחה ממה שלא מצאנו? שמא יש בכל זאת מקור כזה!","\u0003נפק\u0004 \u0005[יצא]\u0006 \u0003רב אשי, ואיתימא\u0004 \u0005[וישאומרים]\u0006 שהיה זה \u0003רב כהנא,\u0004 אל מחוץ לבית המדרש לעיין בעצמו בדבר. \u0003דק ואשכח\u0004 \u0005[דקדק ומצא]\u0006 ראיה גמורה שר' עקיבא אינו סבור שיש חמישי בקודש. \u0003הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]\u0006 \u0003הכלי מצרף את מה שבתוכו\u0004 להיחשב כיחידה אחת. כגון פירות פרודים, אם נטמא אחד מהם, נטמאים כולם מפני היותם מצורפים בכלי אחד. דבר זה נאמר \u0003ל\u0004ענין \u0003קודש, אבל לא בתרומה\u0004 שבה אין אומרים צירוף כלי. \u0003והרביעי בקודש פסול\u0004 ואינו מטמא, \u0003והשלישי\u0004 פסול \u0003בתרומה.\u0004","\u0003ואמר ר' חייא בר אבא אמר ר' יוחנן: מעדותו של ר' עקיבא נשנית משנה זו. דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הוסיף ר' עקיבא\u0004 בעדותו אף את \u0003הסולת והקטורת והלבונה והגחלים\u0004 שאינם מיני מאכל וכרגיל אינם נטמאים בכל זאת מפני חיבת קדושתם, \u0003אם נגע טבול יום,\u0004 שהוא פסול בלבד, \u0003במקצתן — פסל את כולן,\u0004 שהכלי מצרפם להיות אחד.","וממשנה זו שהיא כר' עקיבא אפשר ללמוד: \u0003רביעי — אין\u0004 \u0005[כן]\u0006 פסול בקודש, ואולם \u0003חמישי — לא, שלישי\u0004 בתרומה — \u0003אין\u0004 \u0005[כן],\u0006 \u0003רביעי — לא.\u0004","כיון שהוזכרו הדברים מעירים: \u0003אלמא קסבר\u0004 \u0005[מכאן\u0006 למדים ש\u0005סבר]\u0006 ר' יוחנן: \u0003צירוף\u0004 קטורת לבונה, או גחלים בכלי אחד לטמא \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 הוא ולא מן התורה, שלדעתו יודעים אנו דין צירוף רק מעדותו של ר' עקיבא ולא ממקרא מפורש בענין זה. \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דעה זו על שיטת \u0003ר' חנין\u0004 ש\u0003אמר: צירוף דאורייתא\u0004 \u0005[מן התורה]\u0006 הוא, \u0003שנאמר \"כף אחת עשרה זהב מלאה קטרת\"\u0004 (במדבר ז, כ), והוא לומד מלשון המקרא: \u0003הכתוב עשה כל מה שבכף\u0004 כלומר, את הקטורת — אחת, שנחשבת כדבר אחד.","מתוך שאנו עוסקים כאן בדיני טומאה וטהרה שבמקדש מביאים גם \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]\u0006 שהעידו חכמים \u0003על מחט שנמצאת בבשר, שהסכין והידים\u0004 שנגעו בה — \u0003טהורות, והבשר טמא\u0004 בשל חשש הטומאה במחט. ואם \u0003נמצאת\u0004 המחט \u0003בפרש\u0004 שבקיבת הבהמה — \u0003הכל טהור,\u0004 שאין הפרש מטמא את הבשר. \u0003אמר ר' עקיבא: זכינו\u0004 (הצלחנו) ללמוד מכך הלכה חדשה זו \u0003שאין טומאת ידים במקדש,\u0004 שהרי לא נטמאו הידים מחמת מגען במחט הטמאה."],["ושואלים: \u0003ונימא\u0004 \u0005[ושיאמר]\u0006 ר' עקיבא יתירה מזו שלמדנו מכאן \u0003שאין טומאת ידים וכלים במקדש,\u0004 שהרי נאמר שגם הסכין שנגע במחט טהור! \u0003אמר רב יהודה אמר רב, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יוסי בר' חנינא:\u0004 גזירת חכמים על טומאת \u0003ידים קודם גזירת כלים נשנו.\u0004 שבזמן אותה עדות עדיין לא נגזרה אותה גזירה שכלים הנוגעים במשקים שנטמאו יטמאו אף הם, אפילו מחוץ למקדש, וממילא אין כל רבותה בכך שאין כלים נטמאים במקדש עצמו.","\u0003אמר רבא: והא תרוייהו\u0004 \u0005[והרי שניהם]\u0006 \u0003בו ביום גזרו, דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 טומאת \u0003הספר\u0004 (תורה) ושאר כתבי קודש, וטומאת \u0003הידים\u0004 שלא נרחצו ולא נטבלו, \u0003ו\u0004טומאת \u0003טבול יום, והאוכלין והכלים שנטמאו במשקין,\u0004 כולן נגזרו יחד כשגזרו \"שמונה עשר דבר\"!","\u0003אלא אמר רבא,\u0004 יש לדחות את מה שאמרנו ולמצוא ישוב אחר לשאלה, וכך יש לומר: \u0003הנח לטומאת סכין,\u0004 ש\u0003אפילו בחולין נמי\u0004 \u0005[גם כן]\u0006 \u0003לא מטמא.\u0004 כיצד, \u0003האי\u0004 \u0005[אותו]\u0006 \u0003סכין\u0004 ש\u0003נגע במאי\u0004 \u0005[במה]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003נגע בבשר — הא\u0004 \u0005[הרי]\u0006 \u0003אין אוכל מטמא כלי, ואלא\u0004 תאמר ש\u0003נגע במחט\u0004 עצמה — \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אין כלי מטמא כלי!\u0004","לגופה של אותה הלכה שואלים: \u0003האי\u0004 \u0005[אותה]\u0006 \u0003מחט מאי עבידתיה\u0004 \u0005[מה מעשיה]\u0006 כלומר, אותה מחט שנמצאה בבשר ומטמאתו מה טומאה היתה בה? \u0003אי נימא\u0004 \u0005[אם נאמר]\u0006 \u0003ספק מחט,\u0004 כלומר שספק בידינו אם מחט זו טמאה, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003איתמר\u0004 \u0005[נאמר]\u0006 ש\u0003ר' אלעזר ור' יוסי בר' חנינא, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: לא גזרו על ספק הרוקין שבירושלים.\u0004 שרוק הנמצא בכל מקום חוששים שמא הוא רוקו של זב (או של גוי שדינו כזב) ומטמא מספק כאב הטומאה, אבל בירושלים לא גזרו על כך. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: לא גזרו על ספק הכלים שבירושלים.\u0004 שסתם כלי הנמצא בירושלים, אין חוששים שמא נטמא.","\u0003אמר רב יהודה אמר רב:\u0004 מדובר כאן \u0003כגון שאבדה לו מחט\u0004 שנטמאה ב\u0003טמא מת.\u0004 ובאשר היא כלי מתכת, דינה כחרב שטמאה באותה דרגת טומאה של הדבר שטימא אותה, והריהי כטמא מת עצמו. \u0003ו\u0004לבסוף \u0003הכירה,\u0004 כשנמצאה \u0003בבשר. ר' יוסי בר' אבין אמר:\u0004 אין צורך בכך, אלא \u0003כגון שהיתה פרה חסומה\u0004 בפיה, שברור לנו שלא אכלה מאומה, \u0003ובאה מחוץ לירושלים.\u0004 וכיון שברור שהמחט נבלעה מחוץ לירושלים, אף אם אינו בטוח שהמחט טמאה, הרי כל ספק טומאת הכלים מחוץ לירושלים — טמא.","כיון שהוזכרו הדינים המיוחדים לירושלים דנים עתה ב הלכה זו \u0003גופא\u0004 \u0005[עצמה].\u0006 \u0003ר' אלעזר ור' יוסי בר' חנינא: חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: לא גזרו על ספק הרוקין שבירושלים, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: לא גזרו על ספק הכלים שבירושלים.\u0004 ותוהים: \u0003רוקין תנינא\u0004 \u0005[שנינו]\u0006 כבר, וכן \u0003כלים תנינא\u0004 \u0005[שנינו]\u0006 אם כן מה חידשו אמוראים אלה בדבריהם?","ומבארים: \u0003רוקין תנינא\u0004 \u0005[שנינו],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל הרוקין הנמצאין בירושלים טהורין,\u0004 שאין אנו גוזרים בהם טומאה מספק, \u0003חוץ משל שוק העליון,\u0004 שבסביבה זו היו מצויים כרגיל גוים (רמב\"ם)! ודוחים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכתו של האמורא אלא ללמדנו \u0003אף על גב דאיתחזק\u0004 \u0005[אף על פי שהוחזק\u0006 בידינו\u0005]\u0006 שהיה \u0003זב\u0004 בסביבה זו שבה נמצא הרוק, בכל זאת אין גוזרים טומאה על הרוק בירושלים.","וכן \u0003כלים תנינא\u0004 \u0005[שנינו],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כל הכלים הנמצאים בירושלים,\u0004 אם נמצאו ב\u0003דרך ירידה לבית הטבילה\u0004 — הרי הם \u0003טמאין,\u0004 שמן הסתם עדיין לא הטבילם, שהרי אין מביאין לבית הטבילה אלא כלים טמאים. ומכאן נדייק: \u0003הא דעלמא\u0004 \u0005[הרי בכלל]\u0006 — הכלים \u0003טהורין!\u0004","ומקשים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאתה מדייק באופן זה, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של המשנה שנאמר בה: אם מצאו את הכלים \u0003דרך עליה\u0004 מבית הטבילה — \u0003טהורין,\u0004 ואף שם יכולים לדייק: \u0003הא דעלמא\u0004 \u0005[הרי בכלל]\u0006 — \u0003טמאין!\u0004","\u0003אלא\u0004 יש לומר: ש\u0003רישא\u0004 \u0005[ההתחלה]\u0006 \u0003דוקא\u0004 \u0005[מדוייקת],\u0006 כלומר מנוסחת כך שאפשר לדייק מן הדברים שנאמרו לדברים שלא נאמרו. \u0003וסיפא לאו דוקא\u0004 \u0005[אינה מדוייקת]\u0006 עד כדי כך, \u0003ו\u0004יש ללמוד ממנה רק \u0003לאפוקי גזייתא\u0004 \u0005[להוציא סמטאות\u0006 קטנות\u0005]\u0006 שהן בצד בית הטבילה, ולא ברור אם הן דרך עליה או דרך ירידה. ומאחר והיו הכלים ודאי טמאים, והספק אינו אלא אם נטבלו לטהרתם, לכך מעמידים אותם על חזקת טומאתם. אבל כאשר הספק הוא אם בכלל נטמאו, בכך לא גזרו חכמים ונחשבים הם כטהורים.","ושואלים: \u0003ול\u0004שיטת \u0003רב\u0004 ש\u0003אמר\u0004 שמדובר שם \u0003כגון שאבדה לו מחט טמא מת והכירה בבשר,\u0004 הרי \u0003כיון\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 שאת הכתוב \u0003\"בחלל חרב\"\u0004 יש ללמוד כי \u0003חרב\u0004 וכל כלי מתכת \u0003הרי הוא כחלל\u0004 עצמו, ולכן מתוך שנגעה בטמא מת הרי אף היא טמאה בדרגת \"אב הטומאה\" כמותו. ואם כן, \u0003אדם וכלים נמי\u0004 \u0005[גם כן]\u0006 \u0003ליטמא\u0004 במגע בה, ולא רק את הבשר!","\u0003אמר רב אשי: זאת אומרת עזרה\u0004 שבמקדש \u0003רשות הרבים היא\u0004 לענין דיני ספקות שבטומאה, \u0003והוה ליה\u0004 \u0005[ונהיה לו,\u0006 נעשה\u0005]\u0006 הדבר כ\u0003ספק טומאה ברשות הרבים,\u0004 שהרי אין בידינו הוכחה שנגעו הכלים או הידים במחט טמאה זו. \u0003ו\u0004כלל בידינו כי \u0003כל ספק טומאה ברשות הרבים — ספיקו טהור,\u0004 ולכן רק הבשר שודאי נגעה בו המחט טמא, אבל השאר טהור.","על תירוץ זה תוהים: \u0003הא\u0004 \u0005[הרי]\u0006 אפשר להסיק מכאן כי אם היה הדבר \u0003ברשות היחיד — ספיקו טמא הוא.\u0004 ומדוע? \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003האי\u0004 \u0005[אותה]\u0006 ה\u0003מחט דבר שאין בו דעת לישאל הוא,\u0004 שדבר דומם איננו יכול להישאל ולהיחקר כיצד בדיוק ואם בכלל נטמא. \u0003ו\u0004שנינו כלל בדבר: \u0003כל דבר שאין בו דעת לישאל\u0004 כגון חפץ או אדם שאינו מסוגל להישאל, \u0003בין\u0004 שהיה \u0003ברשות הרבים ובין ברשות היחיד — ספיקו טהור!\u0004","ודוחים: אמנם מחט היא דבר שאין בו דעת להישאל, ואולם הטומאה בה היא \u0003משום דהוי\u0004 \u0005[שהריהי]\u0006 \u0003ספק טומאה בידי אדם,\u0004 שהרי מגע הסכין במחט לא בא מעצמו אלא הסכין מוחזקת בידי אדם, \u0003ו\u0004כבר \u0003אמר ר' יוחנן\u0004 כלל אחר: \u0003ספק טומאה הבאה בידי אדם\u0004"],["\u0003נשאלין עליה, אפילו בכלי המונח על גבי קרקע — כדבר שיש בו דעת לישאל.\u0004 וכיון שכך, הרי משום נימוק זה בלבד לא היה מקום לטהר את הסכין, ולכן הוצרך לומר שהעזרה כרשות הרבים, וספק טומאה בה איננו מטמא.","שנינו שלאחר שנמצאה מחט טמאה בבהמה \u0003\"הבשר טמא\".\u0004 ושואלים: \u0003האי\u0004 \u0005[אותו]\u0006 \u0003בשר דאיתכשר\u0004 \u0005[שהוכשר]\u0006 לטומאה \u0003במאי\u0004 \u0005[במה]?\u0006 שהרי דבר אוכל אינו מקבל טומאה אלא אם כן הוכשר לטומאה על ידי שנרטב במשקה. ולכאורה כיצד יתכן שבשר קודשים זה יוכשר מיד עם שחיטתו?","\u0003אי נימא דאיתכשר\u0004 \u0005[אם תאמר שהוכשר]\u0006 לטומאה על ידי \u0003דם\u0004 השחיטה, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: מנין לדם קדשים שאינו מכשיר\u0004 לטומאה — \u0003שנאמר \"לא תאכלנו על הארץ תשפכנו כמים\"\u0004 (דברים יב, כד), ללמדנו: \u0003דם שנשפך כמים\u0004 — דינו כמים, ואף \u0003מכשיר\u0004 לקבל טומאה. \u0003ושאינו נשפך כמים — אינו מכשיר.\u0004","\u0003ואלא\u0004 תאמר \u0003דאיתכשר\u0004 \u0005[שהוכשר]\u0006 אותו בשר \u0003במשקי בית מטבחיא\u0004 \u0005[במשקים\u0006 אחרים כמים הנמצאים \u0005בבית המטבחיים]\u0006 במקדש ליד המזבח לצורך הדחת הקרבנות. \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יוסי בר' חנינא: משקי בית מטבחיא\u0004 \u0005[בית המטבחיים]\u0006 \u0003לא דיין שהן דכן\u0004 \u0005[טהורים]\u0006 כפי עדותו של יוסי בן יועזר \u0003אלא ש\u0004אף \u0003אין מכשירין\u0004 לקבל טומאה!","\u0003אלא\u0004 עליך לומר \u0003דאיתכשר\u0004 \u0005[שהוכשר]\u0006 בשר זה \u0003בחיבת הקודש.\u0004 כי לגבי דברים שונים אומרים אנו שאף שאין להם טומאה מן התורה, נעשו כמקבלי טומאה, מפני קדושתם היתירה. ואולם \u0003אימור\u0004 \u0005[אמור,\u0006 אמנם\u0005]\u0006 \u0003דמהניא ליה\u0004 \u0005[שמועילה לו]\u0006 \u0003חיבת הקודש לאיפסולי גופיה\u0004 \u0005[לפסול\u0006 את הבשר \u0005עצמו]\u0006 למרות שלא הוכשר, ואולם \u0003למימנא ביה\u0004 \u0005[למנות בו]\u0006 \u0003ראשון ושני\u0004 כלומר שיחשב טמא ממש לטמא גם אחרים \u0003נמי\u0004 \u0005[גם כן]?!\u0006","ואם כן, על ידי כך \u0003תיפשוט\u0004 \u0005[תפתור]\u0006 אותה שאלה \u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003ריש לקיש: צריד של מנחות\u0004 (גוש יבש מתוך קרבן המנחה) האם \u0003מונין בו ראשון ושני או לא!\u0004 שאמנם הוא עצמו מקבל טומאה משום חיבת הקודש אף שלא הוכשר לטומאה, אלא שלא נתברר לנו אם טומאתו היא כזו שמונים בו אף ראשון ושני כשאר טומאות.","ודוחים: אפשר לומר כי בעיית חיבת הקודש לא נפתרה עדיין, אך \u0003אמר רב יהודה אמר שמואל:\u0004 כאן היה הכשר בצורה זו, \u0003כגון שהיתה\u0004 ה\u0003פרה של זבחי שלמים\u0004 שעורה ובשרה לבעליה, \u0003והעבירה\u0004 בעליה \u0003בנהר\u0004 לנקותה \u0003ושחטה, ועדיין משקה טופח\u0004 (לח) \u0003עליה,\u0004 ומן העור נפלו המים בשעת הפשטתה על הבשר והכשירוהו לקבל טומאה.","ששנינו שם שאם \u0003נמצאת\u0004 המחט \u0003בפרש\u0004 שבקיבת הבהמה \u0003הכל טהור,\u0004 ומקשים: \u0003וניהדר\u0004 \u0005[ויחזור]\u0006 \u0003פרש\u0004 זה שהוא נוזל, וכדין משקה שנטמא ייעשה ראשון לטומאה (שגזרו חכמים שכל משקה טמא יהא ראשון) \u0003וניטמייה\u0004 \u0005[ויטמא]\u0006 את \u0003הבשר\u0004 עצמו! \u0003אמר רב אדא בר אהבה:\u0004 מדובר כאן \u0003בפרש עבה\u0004 ומוצק שאינו נדון כמשקה. \u0003רב אשי אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר כאן \u0003בפרש רכה,\u0004 הרי זה \u0003משום דהוי\u0004 \u0005[שהינו]\u0006 \u0003משקה סרוח,\u0004 ומשקה סרוח אינו מטמא.","\u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רב ששת:\u0004 שעל פי המקראות אפשר לסדר אפשרות כגון זו: \u0003שרץ מטמא את המשקין, ומשקין מטמאין את הכלי, וכלי מטמא את האוכלין, והאוכלין מטמאין את המשקין, ולמדנו שלש טומאות\u0004 כלומר דרגות זו אחר זו של טומאה בשרץ. ותוהים: \u0003הני\u0004 \u0005[אלה]\u0006 \u0003ארבעה הן\u0004 ולא שלוש דרגות. ומשיבים: \u0003גוז\u0004 \u0005[חתוך]\u0006 הסר את \u0003משקין\u0004 המוזכרים ב\u0003רישא\u0004 \u0005[תחילה],\u0006 ואמור כך: שרץ לכלי וכלי לאוכלין וכו'.","ושואלים: \u0003אדרבא\u0004 (להיפך) \u0003גוז\u0004 \u0005[חתוך]\u0006 את ענין ה\u0003משקין דסיפא\u0004 \u0005[שבסוף]\u0006 שאוכלים מטמאים את המשקים. ומשיבים: אין לומר כן כי \u0003לא אשכחן\u0004 \u0005[מצאנו]\u0006 \u0003תנא\u0004 ש\u0003אמר משקין מטמאין כלי, אלא ר' יהודה\u0004 בלבד, \u0003ו\u0004אף הוא \u0003הדר ביה\u0004 \u0005[חזר בו]\u0006 משיטתו זו. \u0003וסימניך, נזייתא\u0004 \u0005[וסימנך, כלי השכר].\u0006 ושיהיה לך סימן בברייתא זו כיצד סדר טומאות בה שים לב לעשיית השכר: שקודם מביאים כלי, ואחר כך מכניסים בתוכו את השעורים (אוכל), ואחר כך שופכים מים. וכן הוא סדר הטומאות שבברייתא.","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003שרץ שנמצא בתנור — הפת שבתוכו שניה\u0004 לטומאה, \u0003מפני שהתנור\u0004 נעשה \u0003תחלה\u0004 (ראשון לטומאה) וטימא התנור את הפת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר אהבה לרבא: וניחזי להאי\u0004 \u0005[ונראה את אותו]\u0006 \u0003תנור כמאן דמלי\u0004 \u0005[כמי שמלא]\u0006 \u0003טומאה דמי\u0004 \u0005[נחשב],\u0006 שהרי כלי חרס מקבל טומאה מן השרץ גם אם היה תלוי באוירו ולאו דוקא נוגע בו, \u0003ותיהוי האי\u0004 \u0005[ותהיה זו\u0006 הפת\u0005]\u0006 \u0003ראשונה\u0004 לטומאה! שתיחשב כמקבלת טומאה במישרין מן השרץ. שהרי כיון שחללו מטמא, הרי זה כאילו כולו מלא שרצים, וכיון שכן, תיטמא הפת ותיעשה ראשון כאילו נגעה בשרץ עצמו.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא סלקא דעתך\u0004 \u0005[לא תעלה על דעתך]\u0006 סברה כגון זו, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יכול יהו כל הכלים\u0004 המצויים בתנור \u0003מטמאין מאויר כלי חרס\u0004 שנטמא —"],["\u0003תלמוד לומר\u0004 נאמר בשרצים: \"וכל כלי חרש אשר יפול מהם אל תוכו \u0003כל אשר בתוכו יטמא\u0004 ואותו תשבורו\" (ויקרא יא, לג) \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 הפסוק הזה \u0003\"מכל האכל\u0004 אשר יאכל אשר יבוא עליו מים יטמא\u0003\"\u0004 (ויקרא יא, לד), למדנו מכאן כי \u0003אוכל מטמא מאויר כלי חרס, ו\u0004אולם \u0003אין כל הכלים מטמאין מאויר כלי חרס.\u0004 ומכאן הוכחה שאין אומרים כאילו הכלי עצמו מלא שרצים ומטמא כל שבתוכו במישרין להיות ראשון לטומאה, שאם לא כן, היו אף כלים מיטמאים באויר כלים בדרך זו ונעשים ראשון.","\u0003רב חסדא רמי פיסחא אפיסחא ומשני\u0004 \u0005[היה משליך,\u0006 מראה סתירה, מענין \u0005פסח על\u0006 ענין \u0005פסח ו\u0006הוא עצמו \u0005מתרץ].\u0006 ומפרטים: \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר ר' יהושע\u0004 ששורפים תרומת חמץ תלויה (מסופקת) וטמאה \u0003שתיהן כאחת\u0004 בערב פסח,","\u0003ורמינהו\u0004 \u0005[והשליך,\u0006 הראה סתירה לכך\u0005]\u0006 ממה ש\u0003אמר ר' יוסי: אין הנדון דומה לראיה, כשהעידו רבותינו\u0004 ר' חנינא סגן הכוהנים ור' עקיבא \u0003על מה העידו — אם על הבשר שנטמא בולד הטומאה\u0004 (ראשון לטומאה) \u0003ששורפין אותו\u0004 יחד \u0003עם הבשר שנטמא באב הטומאה — הרי זה טמא וזה טמא\u0004 אף כי לא באותה דרגה.","ו\u0003אם על השמן שנפסל בטבול יום, שמדליקין אותו בנר שנטמא בטמא מת\u0004 (ראשון לטומאה) — עדיין \u0003זה פסול וזה טמא. אף אנו מודים בתרומה שנטמאת\u0004 ודאי \u0003בולד הטומאה ששורפין אותה\u0004 יחד \u0003עם התרומה שנטמאת באב הטומאה\u0004 אף שנגרמת לה טומאה חמורה משהיתה, \u0003אבל היאך נשרוף אפילו\u0004 תרומה \u0003תלויה\u0004 (מסופקת) \u0003עם הטמאה, שמא יבא אליהו ויטהרם.\u0004","\u0003ומשני\u0004 \u0005[והיה מתרץ]\u0006 רב חסדא עצמו: \u0003הא\u0004 \u0005[זו\u0006 ששנינו\u0005]\u0006 בשם ר' יהושע ששורפים תרומה תלויה עם טמאה — הוא כדברי \u0003ר' שמעון, ואליבא\u0004 \u0005[ולפי\u0006 שיטת\u0005]\u0006 \u0003ר' יהושע. הא\u0004 \u0005[זו]\u0006 שאין שורפין — \u0003ר' יוסי, ואליבא\u0004 \u0005[ולפי\u0006 שיטת\u0005]\u0006 \u0003ר' יהושע.\u0004","והיכן מצינו במפורש מחלוקת תנאים זו בדברי ר' יהושע — \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ארבעה עשר\u0004 בניסן \u0003שחל להיות בשבת,\u0004 שאי אפשר לבער את החמץ בו ביום משום השבת, \u0003מבערין את הכל מלפני השבת, ושורפין\u0004 יחד \u0003תרומות טמאות תלויות וטהורות,\u0004 אלו \u0003דברי ר' מאיר. ר' יוסי אומר:\u0004 שורפים \u0003טהורה בפני עצמה, ותלויה בפני עצמה, וטמאה בפני עצמה.\u0004","\u0003אמר ר' שמעון: לא נחלקו ר' אליעזר ור' יהושע על\u0004 התרומה \u0003הטהורה ועל הטמאה שאין שורפין\u0004 אותן כאחת, \u0003על התלויה ועל הטהורה ששורפין\u0004 אותן כאחת, כיון שלא הוחזקה כאן כל טומאה, אינו נראה בכך כמטמא תרומה בידים. \u0003על מה נחלקו — על התלויה ועל הטמאה, שר' אליעזר אומר: תישרף זו בעצמה וזו בעצמה,\u0004 כיון שהוחזקה כאן טומאה ודאית יש לחשוש שמא התלויה אכן טהורה, והריהו מטמא אותה בידים. \u0003ור' יהושע אומר:\u0004 שורף את \u0003שתיהן כאחת.\u0004","ותוהים, כיצד אפשר לתרץ כך? \u0003והא מתניתין\u0004 \u0005[והרי משנתנו]\u0006 כ\u0003ר' יוסי היא,\u0004 וכיצד אפשר לומר שאותו דבר שאומר ר' יוסי לא הוא אמרו אלא ר' שמעון! ומתרצים: \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 \u0003ר' יוסי לר' מאיר: אפילו ר' שמעון ואליבא\u0004 \u0005[ולפי\u0006 שיטת\u0005]\u0006 \u0003ר' יהושע,\u0004 ש\u0003מיקל, כי\u0004 \u0005[כאשר]\u0006 הוא \u0003מיקל\u0004 הרי זה \u0003ב\u0004שריפת \u0003תלויה וטמאה, אבל בטהורה וטמאה\u0004 כדבריך — אף הוא \u0003לא\u0004 הודה.","בדומה לכך, \u0003ר' יוסי בר' חנינא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]\u0006 בין דין \u0003תרומה\u0004 ובין \u0003פיסחא\u0004 \u0005[פסח],\u0006 \u0003ו\u0004הוא עצמו \u0003משני\u0004 \u0005[מתרץ].\u0006 ומפרטים: \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר ר' יהושע\u0004 ששורפים \u0003שתיהן\u0004 התלויה והטמאה \u0003כאחת,\u0004","\u0003ורמינהו\u0004 \u0005[והשליך,\u0006 הראה סתירה לכך\u0005]\u0006 ממה ששנינו: \u0003חבית של תרומה שנולד בה ספק טומאה, ר' אליעזר אומר: אם היתה\u0004 החבית \u0003מונחת במקום התורפה\u0004 שעשויה להישבר או להיטמא בו — \u0003יניחנה במקום המוצנע, ואם היתה מגולה — יכסנה. ר' יהושע אומר\u0004 היפך הדברים: \u0003אם היתה מונחת במקום המוצנע\u0004 — \u0003יניחנה במקום התורפה, ואם היתה מכוסה — יגלנה.\u0004","ונדייק: מכל מקום \u0003גרמא\u0004 \u0005[לגרום]\u0006 שתבוא טומאה וודאית לספק תרומה טמאה \u0005—\u0006 \u0003אין\u0004 \u0005[כן,\u0006 מותר\u0005],\u0006 ואולם לטמא אותה במעשה ממש \u0003בידים — לא!\u0004 ואילו כאן אמרנו ששורפים את שתיהן יחד! \u0003ומשני\u0004 \u0005[והיה מתרץ]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 האומרת שמותר לשרפו כאחת — שיטת \u0003ר' שמעון אליבא\u0004 \u0005[לפי\u0006 שיטת\u0005]\u0006 \u0003ר' יהושע, הא\u0004 \u0005[זו]\u0006 המתירה רק גרם טומאה — היא כשיטת \u0003ר' יוסי אליבא\u0004 \u0005[לפי\u0006 שיטת\u0005]\u0006 שיטת \u0003ר' יהושע.\u0004","ובדומה לכך \u0003ר' אלעזר רמי\u0004 \u0005[היה משליך,\u0006 מראה סתירה\u0005]\u0006 מענין \u0003תרומה\u0004 לענין \u0003תרומה, ומשני\u0004 \u0005[ומתרץ]\u0006 בעצמו. ומפרטים: \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר ר' יהושע\u0004 כי לטמא ספק תרומה \u0003גרמא\u0004 \u0005[לגרום\u0006 בלבד\u0005] —\u0006 \u0003אין\u0004 \u0005[כן,\u0006 מותר\u0005],\u0006 ואולם \u0003בידים\u0004 ממש — \u0003לא,\u0004","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003חבית של\u0004 יין \u0003תרומה שנשברה בגת העליונה ותחתיה\u0004 בגת התחתונה היו \u0003חולין טמאין —\u0004","\u0003מודה ר' אליעזר לר' יהושע שאם יכול להציל ממנה\u0004 מן הגת העליונה מקצת התרומה הטהורה, אפילו אינו מוצא אלא כלי טהור המכיל \u0003רביעית\u0004 אחת בלבד כדי לקבל את היין \u0003בטהרה — יציל,\u0004 ולא ישגיח על השאר. \u0003ואם לאו\u0004 שאינו יכול להציל כלום — \u0003ר' אליעזר אומר: תרד\u0004 התרומה הזו מעצמה \u0003ותטמא\u0004 כשתכנס לגת התחתונה, אבל \u0003לא יטמאנה ביד.\u0004","\u0003ר' יהושע אומר: יטמאנה ביד,\u0004 שיפקוק את הצינור המוליך בין הגת העליונה לתחתונה בכלי טמא או יוציא את היין בכלים טמאים. הרי ברור שר' יהושע מתיר אף לטמא תרומה טהורה בידים!","\u0003ומשני\u0004 \u0005[ומתרץ]:\u0006 \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 בענין חבית שנשברה \u0003דאיכא\u0004 \u0005[שיש]\u0006 בדבר \u0003הפסד חולין,\u0004 שאם תישפך החבית לגת התחתונה יאסרו אף החולין הטמאים המצויים שם, מחמת חלק התרומה שהתערב בהם ושאסור באכילה לזר.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא: מתניתין נמי איכא\u0004 \u0005[\u0006ב\u0005משנתנו גם כן יש]\u0006 \u0003הפסד עצים,\u0004 אם צריך לשרוף תרומה טהורה לעצמה וטמאה לעצמה, ובכל זאת אמר ר' יוסי משום ר' יהושע שאין נשרפים כאחת! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: להפסד מרובה — חששו\u0004 חכמים והתירו, ו\u0003להפסד מועט\u0004 של עצים בלבד — \u0003לא חששו.\u0004","\u0003ומנא תימרא\u0004 \u0005[ומנין תאמר]\u0006 ותוכיח שאכן \u0003להפסד מרובה חששו, ולהפסד מועט לא חששו — דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חבית של שמן תרומה שנשברה בגת העליונה, ובתחתונה חולין טמאין — מודה ר' אליעזר לר' יהושע שאם יכול להציל ממנה רביעית בטהרה — יציל, ואם לאו — תרד ותטמא ואל יטמאנה ביד.\u0004","ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 \u0003שמן\u0004 שהכל מודים שאין לטמא אותו ביד משום ש\u0003ראוי להדליק,\u0004 שגם אם תישפך התרומה לגת התחתונה ותיטמא ותהא בתערובת גם תרומה טמאה, מכל מקום כיון שאף בתרומה טמאה מותר להשתמש לצורך הדלקה, אין זה הפסד גמור. אם כן, \u0003יין נמי\u0004 \u0005[גם כן]\u0006 \u0003ראוי לזילוף\u0004 להתיזו ולזלפו בבית לשם ריח טוב, ואפשר לצורך זה להשתמש גם בתרומה טמאה!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003זילוף לאו מילתא היא\u0004 \u0005[לא דבר\u0006 חשוב \u0005הוא],\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל משום\u0004 (בשם) \u0003ר' חייא: שותין\u0004 יין \u0003מלוג בסלע,\u0004 שלוג ממנו שווה סלע, \u0003ומזלפין מלוג\u0004 ששוה \u0003שנים.\u0004 הרי שזילוף חשוב אף משתיה! ומשיבים: מדובר כאן \u0003ב\u0004יין \u0003חדש,\u0004 שאין ריחו חזק ואינו ראוי לזילוף.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ראוי\u0004 הוא \u0003לישנו\u0004 (להמתין בו עד שיהא ישן), ואז יזלף הכל ואינו בא לידי הפסד! ומשיבים: \u0003אתי ביה\u0004 \u0005[\u0006עלול \u0005לבוא בו]\u0006 \u0003לידי תקלה,\u0004 שמא בתוך הזמן ישכחו שיין זה טמא, וישתוהו. ושואלים: אם כן \u0003שמן נמי\u0004 \u0005[גם כן]\u0006 \u0003אתי ביה\u0004 \u0005[יבוא בו]\u0006 \u0003לידי תקלה\u0004 שישכחו שהוא טמא וישתמשו בו לשתיה.","ומשיבים: \u0003דרמי ליה\u0004 \u0005[שמטיל אותו]\u0006 \u0003בכלי מאוס,\u0004 ושוב אין בני אדם עלולים לשתות ממנו, אלא מדליקים בלבד. ושואלים: \u0003יין נמי\u0004 \u0005[גם כן]\u0006 \u0003רמי ליה\u0004 \u0005[מטיל אותו]\u0006 \u0003בכלי מאוס!\u0004 ודוחים: דבר זה לא יתכן, כי אם \u0003לזילוף קא בעי ליה\u0004 \u0005[הוא זקוק לו],\u0006 \u0003בכלי מאוס רמי ליה\u0004 \u0005[יניח אותו]?!\u0006 שהרי הזילוף הוא לתוספת עידון, וכלי מאוס ודאי יקלקל את ריחו של היין הזה ויימאס בעיני מזלפו.","ומוסיפים: \u0003ותקלה עצמה\u0004 חשש זה אם דבר שמשאירים אותו זמן מרובה יביא לתקלה, במחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא\u0004 שנויה. \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חבית של יין של תרומה שנטמאת, בית שמאי אומרים: תשפך חבל\u0004 (כולה כאחת), \u0003ובית הלל אומרים:\u0004 ימתין לה שתתיישן ו\u0003תעשה זילוף.\u0004","\u0003אמר ר' ישמעאל בר' יוסי: אני אכריע\u0004 במחלוקת זו, ולפי החלוקה הזו: אם היתה החבית \u0003בשדה — תשפך חבל\u0004 (כולה כאחת), שמא עד שיקחו את החבית מן השדה לבית ישכחו שטמאה היא ויבואו לידי תקלה. ואם היה הדבר \u0003בבית\u0004 שאפשר להשתמש בה מיד — \u0003תעשה זילוף. איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכך רצה לחלק: \u0003ב\u0004יין \u0003חדש — תשפך חבל\u0004, \u0003בישן — תעשה זילוף. אמרו לו:\u0004"],["\u0003אין הכרעת שלישית מכרעת,\u0004 כלומר אי אפשר להוסיף דעה שלישית במחלוקת כדרך הכרעה כאשר החכמים הראשונים כלל לא הזכירו בדבריהם ענין חשש תקלה.","\u0003אמר ר' יוסי בר' חנינא: מחלוקת\u0004 ר' אליעזר ור' יהושע בענין חבית התרומה הנשפכת מהגת העליונה לגת התחתונה היא כ\u0003שנפלה\u0004 סאה אחת של תרומה \u0003לפחות ממאה סאה חולין טמאין\u0004 שהיו בגת התחתונה.","\u0003אבל נפלה למאה\u0004 סאין \u0003חולין טמאין — דברי הכל תרד ותטמא, ואל יטמאנה ביד.\u0004 וטעמו של דבר: שכאשר תיפול חבית אחת בתוך מאה הרי היא מתבטלת ברוב, וכיון שכך — הכל מותר לפחות לזר. שאף שהיא טמאה, הרי שוב אין דינה כתרומה אלא כחולין גמורים.","ומעירים: אכן, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003חבית שנשברה בגת העליונה ותחתיה\u0004 שיעור \u0003מאה\u0004 חביות של \u0003חולין טמאין — מודה ר' אליעזר לר' יהושע, שאם יכול להציל ממנה רביעית בטהרה — יציל, ואם לאו — תרד ותטמא ואל יטמאנה ביד.\u0004","אף שאת הראיה לדברי ר' יוסי בר' חנינא הצלחנו להביא מכאן, מכל מקום תוהים על לשון הברייתא: \u0003האי\u0004 \u0005[זה]\u0006 הביטוי \u0003\"מודה ר' אליעזר לר' יהושע\"\u0004 תמוה הוא, שהרי ר' אליעזר הוא שאמר שאין לטמא את החבית העליונה בכל מקרה, להיפך \u0003מודה ר' יהושע לר' אליעזר מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 שאף ר' יהושע מודה שלא יטמא את חבית התרומה שבגת העליונה! \u0003אמר רבא: איפוך\u0004 \u0005[הפוך]\u0006 את הגרסה, ושנה להיפך.","\u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר: לעולם לא תיפוך\u0004 \u0005[תהפוך],\u0006 \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 שאפשר לשאוב רק \u0003בכלי שתוכו טהור וגבו טמא,\u0004 שנטמא טומאה מדברי סופרים על ידי משקים טמאים, \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003ניגזור דילמא\u0004 \u0005[שמא]\u0006 \u0003נגע גבו בתרומה\u0004 ויטמאנה. ולכן אפילו את הרביעית לא יציל בטהרה בצורה זו, שמא באותה שעה הוא מטמא בידים את שאר התרומה שמחוץ לכלי, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שמודה ר' אליעזר לר' יהושע, שאף שיש חשש שהוא מטמא את שאר התרומה, מכל מקום מותר לו כיון שמציל רביעית בטהרה.","","\u0003כל שעה\u0004 שמותר עדיין \u0003לאכול\u0004 את החמץ, אף \u0003מאכיל\u0004 אותו \u0003לבהמה לחיה ולעופות\u0004 שלו, \u0003ומוכר\u0004 אותו \u0003לגוי, ומותר ב\u0004כל \u0003הנאתו. עבר זמנו — אסור בהנאתו,\u0004 ואף \u0003לא יסיק בו תנור וכירים.\u0004 ביחס לדרך ביעורו של החמץ נחלקו הדעות, \u0003ר' יהודה אומר: אין ביעור חמץ אלא\u0004 על ידי \u0003שריפה. וחכמים אומרים:\u0004 לאו דוקא, אלא \u0003אף מפרר וזורה לרוח או מטיל\u0004 אותו \u0003לים.\u0004 תחילה מדייקים מלשון המשנה: \u0003כל שעה שמותר לאכול — מאכיל, הא\u0004 \u0005[הרי]\u0006 מכאן יוצא ש\u0003כל שעה שאינו מותר לאכול — אינו מאכיל. לימא מתניתין\u0004 \u0005[האם לומר שמשנתנו]\u0006 \u0003לא כ\u0004שיטת \u0003ר' יהודה. דאי\u0004 \u0005[שאם]\u0006 כ\u0003ר' יהודה, הא איכא\u0004 \u0005[הרי יש]\u0006 שעה חמישית ש\u0003אינו אוכל, ו\u0004בכל זאת \u0003מאכיל. דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ר' מאיר אומר: אוכלין\u0004 חמץ ביום ארבעה עשר בניסן \u0003כל חמש, ושורפין\u0004 מיד \u0003בתחלת שש.\u0004 ו\u0003ר' יהודה אומר: אוכלין כל ארבע, ותולין כל חמש, ושורפין בתחלת שש!\u0004 נמצא שיש שעה אחת שאינו אוכל, ואף על פי כן מותר לו להאכיל לבהמה.","","ומקשים מצד שני: \u0003ואלא מאי\u0004 \u0005[מה\u0006 תאמר\u0005]\u0006 שמשנתנו כשיטת \u0003ר' מאיר היא, האי\u0004 \u0005[\u0006לשון \u0005זה]\u0006 \u0003\"כל שעה שמותר לאכול מאכיל\"\u0004 איננה לשון נכונה אלא \u0003\"כל שעה שאוכל מאכיל\" מיבעי ליה\u0004 \u0005[צריך לו\u0006 לומר\u0005].\u0006 שהביטוי \"מותר לאכול\" אינו מובן כאן, כי אינו אומר כיוצא בזה אף \"מותר להאכיל\", ומתוך הבדל הלשון נראה שמדובר בשני בני אדם.","\u0003אמר רבה בר עולא: מתניתין\u0004 \u0005[משנתנו]\u0006 כשיטת \u0003רבן גמליאל היא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003רבן גמליאל אומר: חולין נאכלין\u0004 ביום ארבעה עשר בניסן \u0003כל ארבע\u0004 שעות, \u0003תרומה\u0004 נאכלת אף \u0003כל חמש, ושורפין בתחלת שש. והכי קאמר\u0004 \u0005[וכך אמר]\u0006 וכך יש להבין את דברי משנתנו: \u0003כל שעה שמותר לאכול\u0004 ל\u0003כהן בתרומה,\u0004 אף שישראל כבר איננו אוכל בשעה זו, \u0003ישראל מאכיל חולין לבהמה לחיה ולעופות.\u0004","ועוד מדייקים בלשון המשנה. שנינו בה \"לבהמה לחיה ולעופות\". ושואלים: \u0003למה לי למיתנא\u0004 \u0005[לשנות]\u0006 \u0003בהמה, למה לי למיתנא\u0004 \u0005[לשנות]\u0006 \u0003חיה,\u0004 והרי לכאורה הוא הדין לשתיהן? ומשיבים: \u0003צריכא\u0004 \u0005[נצרכה]\u0006 הכפילות. \u0003דאי תנא\u0004 \u0005[שאם היה שונה]\u0006 \u0003בהמה\u0004 בלבד, היינו אומרים שמותר להאכילה, משום \u0003דאי משיירא, חזי לה\u0004 \u0005[ש\u0006בהמה \u0005אם משיירת\u0006 ואינה אוכלת הכל \u0005רואה אותה]\u0006 ששיירה, ויכול להשליך את הנותר. \u0003אבל חיה\u0004 כגון כלב וחתול, \u0003דאי משיירא, קמצנעא לה\u0004 \u0005[שאם משאירה\u0006 משהו, \u0005הרי היא מצניעה אותו]\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יתירו להאכיל קרוב לזמן איסור חמץ.","\u0003ואי תנא\u0004 \u0005[ואם היה שונה]\u0006 \u0003חיה\u0004 בלבד — \u0003משום דאי משיירא, מיהת מצנעא\u0004 \u0005[שאם\u0006 היא \u0005משיירת, הרי על כל פנים מצנעת]\u0006 ואינו עובר משום \"בל יראה\". \u0003אבל בהמה, זימנין דמשיירא, ולא מסיק אדעתיה\u0004 \u0005[פעמים ש\u0006היא \u0005משיירת, ולא מעלה על דעתו]\u0006 שהשאירה, \u0003וקאי עליה\u0004 \u0005[ומוטל עליו]\u0006 איסור \u0003\"בל יראה ובל ימצא\" — אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יותר לו להאכילה, על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 לשנות שני המקרים. ושואלים: \u0003עופות למה לי\u0004 לחזור ולפרט? ומשיבים: באמת אין צורך מיוחד בזה, אלא \u0003איידי דתנא\u0004 \u0005[על ידי ששנה\u0006 כבר\u0005]\u0006 \u0003בהמה וחיה, תנא נמי\u0004 \u0005[שנה גם כן]\u0006 \u0003עופות\u0004 משום הרגל הלשון. שנינו במשנה שכל שעה שמותר לאכול אף \u0003\"מוכרו לגוי\".\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 ברור הדבר\u0005]\u0006 שכן הוא, שהרי אמרנו שמותר בהנאה! ומשיבים: \u0003לאפוקי מהאי תנא\u0004 \u0005[להוציא מ\u0006שיטת \u0005תנא זה]\u0006 \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בית שמאי אומרים: לא ימכור אדם חמצו לגוי, אלא אם כן יודע בו שיכלה\u0004 החמץ \u0003קודם פסח.\u0004 כי לדעת בית שמאי יש לו לאדם אחריות מסויימת על חמצו, אפילו שאינו בבעלותו. \u0003ובית הלל אומרים: כל שעה שמותר לאכול — מותר\u0004 אף \u0003למכור,\u0004 שמשעה שמכר שוב אין לו כל אחריות על חמץ זה.","",""],["\u0003ר' יהודה בן בתירא\u0004 המסכים בעיקרו של דבר לשיטת בית שמאי \u0003אומר: כותח\u0004 (תבלין חריף העשוי מפירורי לחם) \u0003וכל מיני כותח\u0004 וכיוצא בו — \u0003אסור למכור שלשים יום קודם לפסח,\u0004 כי תבלין אינו נאכל בבת אחת, ויגיע זמן הפסח לפני שיכלה.","שנינו במשנה שחמץ בתוך זמן היתרו \u0003\"מותר בהנאה\".\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003שחרכו\u0004 את החמץ באש \u0003קודם זמנו,\u0004 שחל עליו האיסור ושוב אינו ראוי כלל למאכל. \u0003וקא משמע לן\u0004 \u0005[והשמיע לנו]\u0006 הלכה \u0003כ\u0004שיטת \u0003רבא,\u0004 ש\u0003אמר רבא: חרכו\u0004 את החמץ \u0003קודם זמנו — מותר בהנאה, אפילו לאחר זמנו\u0004 ששוב אינו קרוי חמץ.","במשנה שנינו: \u0003\"עבר זמנו אסור בהנאתו\",\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכן הוא! ומשיבים \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003לשעות דרבנן\u0004 \u0005[שמדברי סופרים].\u0006 כלומר, שאף בשעה השישית שאיסורו מדברי סופרים בלבד הריהו אסור בהנאה מדבריהם. ש\u0003אמר רב גידל אמר רב חייא בר יוסף אמר ר' יוחנן: המקדש\u0004 אשה בחמץ — בחיטין שיש בהן חשש חימוץ מתחילת \u0003שש שעות\u0004 שעדיין אינו אסור אלא מדברי סופרים \u0003ולמעלה\u0004 בערב פסח, \u0003אפילו בחיטי קורדניתא\u0004 שהן קשות מאד ויש רק ספק קלוש שהחמיצו; בכל זאת \u0003אין חוששין לקדושין\u0004 שהרי בקידושי כסף צריך הדבר הניתן כקידושין להיות שוה פרוטה לפחות, וחמץ האסור בהנאה אינו שוה מאומה.","שנינו במשנה: \u0003ולא יסיק בו תנור וכירים\u0004 לאחר שעת איסורו. ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שהרי אף זו הנאה היא! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לשיטת \u0003ר' יהודה\u0004 ש\u0003אמר אין ביעור חמץ אלא שריפה. סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כך: \u0003הואיל ואמר ר' יהודה מצותו\u0004 לבערו \u0003בשריפה, בהדי דקא שריף ליה ליתהני מיניה\u0004 \u0005[בתוך כדי שהוא שורף אותו\u0006 אף \u0005יהנה ממנו]\u0006 אגב ביעורו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הדבר כך, ואסור.","\u0003אמר חזקיה מנין\u0004 יודעים אנו \u0003לחמץ בפסח שאסור בהנאה?\u0004 משום \u0003שנאמר \"לא יאכל חמץ\"\u0004 (שמות יג, ג). ומתוך שנאמר האיסור בלשון נפעל, יש להבין: \u0003לא יהא בו היתר אכילה\u0004 כלל ולכך אסור בהנאה, שהרי כל הנאה בסופו של דבר אפשר להמירה בכסף, ובכסף זה אפשר לקנות דבר מאכל. מדבריו אלה של חזקיה מדייקים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דוקא\u0005]\u0006 משום ש\u0003כתב רחמנא\u0004 \u0005[המקרא]\u0006 \u0003\"לא יאכל חמץ\", הא\u0004 \u0005[הרי]\u0006 אם \u0003לא\u0004 היה כותב בסגנון זה \u0003\"לא יאכל\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שלשון \"לא תאכל\" וכיוצא בה \u0003איסור אכילה — משמע\u0004 הדבר, ואולם \u0003איסור הנאה — לא משמע.\u0004","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דעה זו על דברי \u0003ר' אבהו,\u0004 ש\u0003אמר ר' אבהו: כל מקום שנאמר \"לא יאכל\",\u0004 או \u0003\"לא תאכל\",\u0004 או \u0003\"לא תאכלו\" — אחד איסור אכילה ואחד איסור הנאה משמע, עד שיפרט לך הכתוב\u0004 שמותר בהנאה \u0003כדרך שפרט לך בנבילה,\u0004 שמותר למכרה או לתיתה במתנה לגוי.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"לא תאכלו כל נבלה לגר אשר בשעריך תתננה ואכלה או מכר לנכרי\u0004 כי עם קדוש אתה לה' אלוהיך\u0003\"\u0004 (דברים יד, כא). \u0003אין לי אלא\u0004 שהמצוה \u0003לגר בנתינה\u0004 (במתנה) דוקא \u0003ולגוי במכירה.\u0004 שמותרת הנבילה \u0003לגר\u0004 גם \u0003במכירה מנין? תלמוד לומר: \"לגר אשר בשעריך תתננה או מכר\"\u0004 כלומר, שיש כאן ברירה בין שתי האפשרויות הללו. שמותרת הנבילה \u0003לגוי\u0004 גם \u0003בנתינה\u0004 ולאו דוקא במכירה \u0003מנין? תלמוד לומר \"תתננה ואכלה או מכר לנכרי\". נמצאת אומר: אחד גר ואחד גוי, בין במכירה בין בנתינה\u0004 כרצונו, אלו \u0003דברי ר' מאיר\u0004 בפירוש הפסוק.","\u0003ר' יהודה אומר: דברים ככתבן,\u0004 ל\u0003גר בנתינה\u0004 בלבד \u0003ולגוי במכירה\u0004 בלבד. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה?\u0004 ומשיבים: טעמו הוא \u0003אי סלקא דעתך\u0004 \u0005[אם יעלה על דעתך]\u0006 \u0003כ\u0004מו ש\u0003אמר ר' מאיר\u0004, אם כן \u0003ליכתוב רחמנא\u0004 \u0005[שיכתוב המקרא]\u0006 \u0003\"לגר אשר בשעריך תתננה ואכלה ומכר\u0004 לנכרי \u0003\". \"או\"\u0004 שנמצאת בכתוב בין שתי האפשרויות \u0003למה לי? שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003לדברים ככתבם\u0004 בלא להוסיף ברירות או שינויים.","ושואלים: \u0003ור' מאיר\u0004 כיצד מסביר הוא את סגנון הכתוב? ומשיבים: \u0003\"או\"\u0004 זה בא ללמדנו לשיטתו שיש \u0003להקדים נתינה\u0004 (מתנה) של \u0003גר למכירה\u0004 של \u0003גוי.\u0004 ושואלים: \u0003ור' יהודה\u0004 כיצד למד הוא הלכה זו? \u0003הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 \u0003לא צריך קרא\u0004 \u0005[פסוק],\u0006 שכן יודעים אנו אותו ממקור אחר: \u0003כיון\u0004 ש\u0003גר אתה מצווה להחיותו,\u0004 שמצוה עלינו לדאוג לגר תושב שקיבל על עצמו שלא לעבוד עבודה זרה ולפרנסו, \u0003וגוי אי\u0004 (אין) \u0003אתה מצווה להחיותו,\u0004 לכן \u0003לא צריך קרא\u0004 \u0005[פסוק]\u0006 מפורש, \u0003סברא הוא\u0004 שיש להקדים מתנה לגר הנזקק לה ואנו מצווים לעזור לו, למכירה לגוי. ומכאן ממשיכים להעביר את הדיון גם לענין שאנו עוסקים בו.","\u0003בשלמא\u0004 \u0005[נניח]\u0006 לשיטת ר' אבהו \u0003ל\u0004פי \u0003ר' מאיר\u0004 ש\u0003אמר אחד גר ואחד גוי, בין במכירה בין בנתינה, מדאיצטריך קרא למישרא\u0004 \u0005[מ\u0006מה \u0005שהוצרך הכתוב להתיר]\u0006 \u0003נבילה בהנאה, הא\u0004 \u0005[הרי]\u0006 נלמד מכאן ש\u0003כל\u0004 שאר \u0003איסורין שבתורה\u0004 שכתוב בהם איסור אכילה, \u0003אסורין בין באכילה בין בהנאה,\u0004 וכשיטת ר' אבהו.","\u0003אלא ל\u0004שיטת \u0003ר' יהודה,\u0004 ש\u0003אמר: לדברים ככתבם הוא דאתא\u0004 \u0005[שבא]\u0006 הפסוק — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כל איסורים שבתורה מנא ליה\u0004 \u0005[מניין לו]\u0006 ש\u0003אסורין בהנאה,\u0004 ולא רק באכילה בלבד, כפי משמעות המלים? ומשיבים: דבר זה \u0003נפקא ליה\u0004 \u0005[יוצא לו,\u0006 נלמד\u0005]\u0006 מפסוק אחר, שנאמר בדיני טריפה \u0003\"\u0004ואנשי קודש תהיון לי ובשר בשדה טריפה לא תאכלו \u0003לכלב תשלכון אתו\"\u0004 (שמות כב, ל)."],["ומסיקים מלשון הכתוב: \u0003אותו אתה משליך לכלב, ואי\u0004 (ואין) \u0003אתה משליך לכלב כל איסורין שבתורה,\u0004 שכשם שאסורים הם באכילה כך הם אסורים בהנאה. ושואלים: \u0003ור' מאיר,\u0004 שלשיטתו לומדים מנבילה שכל איסורי תורה אסורים בהנאה, מה הוא מדייק מהכתוב? שהרי הוא אינו צריך ללימוד זה שהבאנו. ומשיבים שר' מאיר מדייק: \u0003אותו אתה משליך לכלב, ואי אתה משליך לכלב חולין שנשחטו בעזרה\u0004 שבמקדש. שאף שאסורים הם באכילה, מכל מקום אסור לבזות אותם ולהשליכם לכלב, ואסורים הם לכן בהנאה.","\u0003ואידך\u0004 \u0005[והאחר]\u0006 ר' יהודה, מהיכן לומד הוא הלכה זו בחולין שנשחטו בעזרה? ומשיבים: לדעתו כל איסור הנאה שב\u0003חולין שנשחטו בעזרה — לאו דאורייתא היא\u0004 \u0005[לא מן התורה הוא]\u0006 אלא חכמים גזרו בהן איסור, וכיון שאין הלכה זו מן התורה ממילא אין צריכים פסוק לכך.","על השיטה שכל מקום שנאמר בו \"לא יאכלו\" הוא איסור אכילה והנאה \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' יצחק נפחא: והרי איסור גיד הנשה, דרחמנא\u0004 \u0005[שהכתוב]\u0006 \u0003אמר \"על כן לא יאכלו בני ישראל את גיד הנשה\"\u0004 (בראשית לב, לב), \u0003ותנן\u0004 \u0005[ושנינו]:\u0006 \u0003שולח אדם\u0004 מתנה \u0003ירך\u0004 של בהמה \u0003לגוי, וגיד הנשה\u0004 עדיין \u0003בתוכו,\u0004 ואינו צריך לנקרו ולהוציאו, \u0003מפני שמקומו ניכר\u0004 ורואים שלא נוקר הגיד, ואין לחשוש במקרה זה שאדם אחר מישראל יסמוך על השולח הראשון ויבוא לאכול את הירך כמות שהוא. ולפי דרכנו למדנו שמותר לאדם ליהנות מגיד הנשה אף כי נאמר בו \"לא יאכלו\", וקשה לר' אבהו!","ודוחים: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003ר' אבהו: כשהותרה נבילה\u0004 בהנאה — \u0003היא וחלבה\u0004 (החלב שבה) \u0003וגידה\u0004 (גיד הנשה שבה) \u0003הותרה,\u0004 וגיד הנשה הוא איפוא מן היוצאים מן הכלל המותרים בהנאה. ומקשים: \u0003הניחא\u0004 \u0005[\u0006דבר \u0005זה נוח]\u0006 \u0003ל\u0004שיטת מי ש\u0003אמר יש בגידין\u0004 (כגון גיד הנשה) \u0003בנותן טעם,\u0004 כלומר שיש בהם טעם בשר, וכיון שהם כשאר הבשר הריהם בכלל נבילה, והותרו עם הנבילה. \u0003אלא ל\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר אין בגידין בנותן טעם\u0004 ואין הם קרוים וחשובים בשר כלל, אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 שאם אינם חלק מבשר הנבילה אף לא הותרו בכלל היתר הנבילה.","ומשיבים: את \u0003מאן\u0004 \u0005[מי]\u0006 \u0003שמעת ליה\u0004 \u0005[אותו]\u0006 ש\u0003אמר \"אין בגידין בנותן טעם\" — ר' שמעון\u0004 הוא, \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003האוכל מגיד הנשה של בהמה טמאה, ר' יהודה מחייב שתים\u0004 הן משום איסור אכילת גיד והן משום איסור אכילת בהמה טמאה. \u0003ור' שמעון פוטר\u0004 לגמרי, שלדעתו אין איסור גיד הנשה אלא בבהמה טהורה, ואף משום אכילת בהמה טמאה אין בו משום שאין בו טעם בשר, וכל שאין בו טעם בשר אינו בכלל איסור אכילת בשר בהמה טמאה.","ובאמת \u0003ר' שמעון הכי נמי\u0004 \u0005[כך גם כן]\u0006 ש\u0003אסר בהנאה\u0004 את הגיד, לפי הטעם שהסברנו, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003גיד הנשה מותר בהנאה,\u0004 אלו \u0003דברי ר' יהודה, ור' שמעון אוסר.\u0004","ומקשים עוד על שיטת ר' אבהו: \u0003והרי דם, דרחמנא\u0004 \u0005[שהכתוב]\u0006 \u0003אמר\u0004 \"על כן אמרתי לבני ישראל \u0003כל נפש מכם לא תאכל דם\u0004 והגר הגר בתוככם לא יאכל דם\" (ויקרא יז, יב). ולשיטת ר' אבהו למדים מכאן שהדם אסור אף בהנאה כשם שאסור באכילה, \u0003ותנן\u0004 \u0005[ו\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אלו ואלו,\u0004 שיירי דמי החטאות הפנימיות ושאר דמים הנזרקים על המזבח, לבסוף יורדים ממנו \u0003ומתערבין באמה\u0004 (בתעלה) של המים שממנה שוטפים את בית המקדש, \u0003ויוצאין\u0004 אחר כך עם המים \u0003לנחל קדרון, ונמכרין\u0004 במחיר מיוחד \u0003לגננין\u0004 (בעלי גינות), שכן המים המעורבים בדם יפים \u0003לזבל. ומועלין בו,\u0004 שאסור להשתמש בהם שלא על ידי קנייתם מבית המקדש. ואם כן, אף שנאמר בדם איסור אכילה, יש בו היתר הנאה!","ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003דם דאיתקש\u0004 \u0005[שהושווה]\u0006 הדם בפסוק \u0003למים, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בדם \u0003\"לא תאכלנו על הארץ תשפכנו כמים\"\u0004 (דברים יב, כד), מכאן נלמד: \u0003מה מים מותרין\u0004 בהנאה, \u0003אף דם מותר.\u0004","ומקשים: מנין יודע אתה שמדובר בפסוק במים המותרים? \u0003ואימא\u0004 \u0005[ואמור]\u0006 שהיקש זה למים אסורים, \u0003כמים המתנסכים על גבי המזבח,\u0004 שהם קודש ואסורים בהנאה! \u0003אמר ר' אבהו:\u0004 היקש למים המותרים נלמד מדיוק הכתוב \u0003\"כמים\" — רוב מים,\u0004 ורוב מים מותרים בהנאה. ומקשים עליו: \u0003מידי\u0004 \u0005[וכי]\u0006 \u0003\"רוב מים\" כתיב\u0004 \u0005[נאמר]?\u0006 הלוא נאמר \"כמים\" בלבד?! \u0003אלא אמר רב אשי,\u0004 כך יש לפרש: \u0003כמים הנשפכין,\u0004 שהם מותרים, \u0003ולא כמים הניסכין\u0004 שלגבי המים. שעל המזבח אין משתמשים בלשון שפיכה אלא בלשון ניסוך.","ועדיין מקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שכך הוא ההיקש שבין דם למים: \u0003כמים הנשפכים לפני עבודה זרה\u0004 שהם אסורים בהנאה! ודוחים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 אין זה נקרא שפיכה אלא \u0003ניסוך איקרי\u0004 \u0005[נקרא],\u0006 שנאמר \u0003\"\u0004אשר חלב זבחימו יאכלו \u0003ישתו יין נסיכם\"\u0004 (דברים לב, לח)."],["ושואלים: \u0003ולשיטת חזקיה\u0004 שלדעתו \"לא תאכל\" משמעו איסור אכילה בלבד ולא איסור הנאה, \u0003למאי הלכתא איתקש\u0004 \u0005[למה\u0006 לאיזו \u0005הלכה הושווה]\u0006 \u0003דם למים?\u0004 שהרי לשיטתו אינו זקוק להיקש זה לצורך היתר הנאתו! ומשיבים שהוא נצרך \u0003ל\u0004ענין זה, \u0003כ\u0004דברי \u0003ר' חייא בר אבא,\u0004 ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: מנין לדם קדשים שאינו מכשיר\u0004 דברי מאכל לקבל טומאה — \u0003שנאמר \"לא תאכלנו על הארץ תשפכנו כמים\"\u0004 (דברים יב, כד), נלמד מכאן \u0003דם\u0004 שחיטת בהמת חולין \u0003שנשפך כמים — מכשיר\u0004 לטומאה, דם קרבן \u0003שאינו נשפך כמים\u0004 אלא נזרק על המזבח — \u0003אינו מכשיר.\u0004","ועוד מקשים לשיטת ר' אבהו: \u0003והרי אבר מן החי,\u0004 אבר שנחתך מבעל חיים בעודנו חי, \u0003דכתיב\u0004 \u0005[שנאמר\u0006 בו\u0005]\u0006 \u0003\"\u0004רק חזק לבלתי אכול הדם כי הדם הוא הנפש \u0003ולא תאכל הנפש עם הבשר\"\u0004 (דברים יב, כג), \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' נתן אומר: מנין שלא יושיט אדם כוס יין לנזיר\u0004 האסור בשתיית יין, \u0003ו\u0004כן לא יושיט \u0003אבר מן החי לבני נח\u0004 שאף בני נח אסורים באכילת אבר מן החי — \u0003תלמוד לומר \"ולפני עור לא תתן מכשל\"\u0004 (ויקרא יט, יד). שהמסייע לאדם להיכשל באיסור הריהו כנותן מכשול לפני עיור. ונדייק מכאן: כיון שאיסור נתינת אבר מן החי לגוי הוא רק מפני \"ולפני עור\", אם כן נלמד כי \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לכלבים — שרי\u0004 \u0005[מותר],\u0006 ומשמע שאין בכך איסור הנאה. והרי נאמר \"לא תאכל\" ולשיטת ר' אבהו הרי זה בא לאסור אף בהנאה!","ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003אבר מן החי, דאיתקש\u0004 \u0005[שהושוה]\u0006 בפסוק \u0003לדם,\u0004 שהרי נאמר \u0003\"רק חזק לבלתי אכל הדם כי הדם הוא הנפש\"\u0004 (דברים יב, כג), וכשם שהדם מותר בהנאה — אף אבר מן החי מותר בהנאה.","ושואלים: \u0003ו\u0004אם כן, \u0003לחזקיה\u0004 שאינו סבור ש\"לא תאכל\" הוא איסור הנאה, \u0003למאי הלכתא איתקש\u0004 \u0005[למה\u0006 לאיזו \u0005הלכה הושווה]\u0006 \u0003אבר מן החי לדם?\u0004 ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול \u0005היה לומר לך]\u0006 חזקיה להיפך, \u0003דם הוא דאיתקש\u0004 \u0005[שהושוה]\u0006 \u0003לאבר מן החי,\u0004 ללמדנו: \u0003מה אבר מן החי — אסור, אף דם מן החי אסור. ואי זה — זה דם הקזה, שהנפש יוצאה בו,\u0004 שדם כזה נקרא דם היוצא מן החי ואסור אף לבני נח (ר\"ח).","ועוד שואלים: \u0003והרי שור הנסקל דרחמנא\u0004 \u0005[שהכתוב]\u0006 \u0003אמר\u0004 \"וכי יגח שור את איש או את אשה ומת, סקול יסקל השור \u0003ולא יאכל את בשרו\u0004 ובעל השור נקי\" (שמות כא, כח), \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003ממשמע שנאמר \"סקול יסקל השור\" איני יודע שהיא נבלה?\u0004 שהרי לא נשחט אלא נסקל, \u0003ו\u0004הרי \u0003נבלה אסורה באכילה! ו\u0004אם כן \u0003מה תלמוד לומר \"לא יאכל\"\u0004 שנאמר בו? אלא \u0003מגיד לך הכתוב\u0004 שאף \u0003אם שחטו לאחר שנגמר\u0004 (נפסק) \u0003את דינו\u0004 לסקילה — \u0003אסור,\u0004 גם אם לא הספיקו לסקלו ועדיין אינו בכלל נבילה.","\u0003אין לי אלא\u0004 שאסור אותו השור \u0003באכילה,\u0004 איסור \u0003הנאה מניין? תלמוד לומר \"ובעל השור נקי\".\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 כיצד\u0005]\u0006 \u0003משמע\u0004 \u0005(\u0006מובן) ממילים אלה איסור הנאה? \u0003שמעון בן זומא אומר:\u0004 הרי זה \u0003כאדם שאומר לחבירו \"יצא פלוני נקי מנכסיו\"\u0004 ומשמע דבריו: \u0003אין לו בהם הנאה של כלום,\u0004 וכן \"ובעל השור נקי\" משמעו: אין לו בשורו כל הנאה.","ולענייננו נדייק: \u0003טעמא\u0004 \u0005[הטעם\u0006 דוקא\u0005]\u0006 ש\u0003כתב \"ובעל השור נקי\"\u0004 יודעים שיש בכך איסור הנאה, \u0003דאי\u0004 \u0005[שאם]\u0006 היינו צריכים ללמוד רק \u0003מ\"לא יאכל\", איסור אכילה — משמע\u0004 מכאן, \u0003איסור הנאה — לא משמע,\u0004 וקשה אף לשיטת חזקיה המסכים ש\"לא יאכל\" משמעו גם איסור הנאה!","ומשיבים: \u0003לעולם \"לא יאכל\" — איסור אכילה ואיסור הנאה משמע, \"ובעל השור נקי\" — להנאת עורו הוא דאתא\u0004 \u0005[שבא],\u0006 ללמדנו שאף עור השור הנסקל אסור בהנאה. \u0003ואיצטריך\u0004 \u0005[והיה צריך]\u0006 לפרש דבר זה, כי \u0003סלקא דעתך אמינא\u0004 \u0005[עולה על דעתך לומר]:\u0006 \u0003\"לא יאכל את בשרו\" כתיב\u0004 \u0005[נאמר],\u0006 והיינו מדייקים: \u0003בשרו — אין\u0004 \u0005[כן]\u0006 יש בו איסור הנאה, \u0003עורו — לא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף עורו אסור בהנאה.","ושואלים: \u0003ולהנך תנאי דמפקי ליה להאי קרא\u0004 \u0005[ולאותם תנאים המוציאים אותו את הפסוק\u0006 הזה\u0005]\u0006 \"בעל השור נקי\" \u0003לדרשה אחרינא\u0004 \u0005[אחרת]\u0006 כגון לענין הלימוד ששור תם פטורים בעליו מתשלום \u0003חצי כופר\u0004 אם הרג השור איש, \u0003ולדמי וולדות\u0004 אם נגח אשה הרה וכתוצאה מכך הפילה את עוברה, אם כן איסור \u0003הנאת עורו מנא להו\u0004 \u0005[מנין להם]?\u0006 ומשיבים: \u0003נפקא להו\u0004 \u0005[יוצא להם]\u0006 ענין זה \u0003מ\u0004לשון \u0003\"\u0004ולא יאכל \u0003את בשרו\",\u0004 ומייתור הלשון \"את\" למדים ריבוי ותוספת לאיסור זה, ומשמעו: \u0003את הטפל לבשרו,\u0004 והוא העור. וכשם שאסור הבשר, כך אסור העור הטפל לו.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 הלומד איסור הנאה בעור מ\"בעל השור נקי\", כיצד דורש הוא את התוספת \"את\"? ומשיבים: שיטת חכם זה היא ש\u0003\"את\"\u0004 כמלה המלמדת על תוספת וריבוי הוא \u0003לא דריש\u0004 \u0005[דורש],\u0006 וסבור הוא שמלה זו היא חלק טבעי ממבנה המשפט ואין ללמוד ממנה דבר.","\u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003שמעון העמסוני, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003נחמיה העמסוני, היה דורש כל 'אתים' שבתורה\u0004 במשמעות של תוספת וריבוי, \u0003כיון שהגיע ל\"את ה' אלהיך תירא\u0004 אותו תעבוד ובשמו תשבע\u0003\"\u0004 (דברים י, כ) \u0003פירש\u0004 ואמר שהוא חוזר בו מדרך דרש זו, שהרי אינו יכול לדרוש ריבוי ותוספת בפסוק זה ולומר שקיים דבר נוסף על ה' עצמו. \u0003אמרו לו תלמידיו: רבי, כל 'אתים' שדרשת מה תהא עליהן?\u0004 והרי כל הזמן דרשת \"את\" כתוספת ועכשיו חוזר אתה בך מכל אלה? \u0003אמר להם: כשם שקבלתי שכר על הדרישה, כך אני מקבל שכר על הפרישה\u0004 מלדרוש דרשות אלה. \u0003עד שבא ר' עקיבא ודרש: \"את ה' אלהיך תירא\"\u0004 אפשר לראות אף בכך לשון ריבוי: \u0003לרבות תלמידי חכמים,\u0004 שאדם מצווה לירא אותם כמורא שמים. ומכל מקום למדנו מכאן ששמעון העמסוני לפחות חזר בו ואיננו דורש עוד \"את\" כלשון ריבוי.","ועוד מקשים, \u0003והרי ערלה דרחמנא\u0004 \u0005[שהכתוב]\u0006 \u0003אמר \"\u0004וכי תבואו אל הארץ ונטעתם כל עץ מאכל וערלתם ערלתו את פריו שלוש שנים יהיה לכם \u0003ערלים לא יאכל\"\u0004 (ויקרא יט, כג), \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006 \u0003\"ערלים לא יאכל\" — אין לי אלא איסור אכילה, מנין ש\u0004אף \u0003לא יהנה ממנו\u0004 הנאה אחרת, כגון \u0003שלא יצבע בו\u0004 בצבע היוצא מן הפירות, \u0003ולא ידליק בו\u0004 בשמנו \u0003את הנר? תלמוד לומר \"וערלתם ערלתו... ערלים לא יאכל\" — לרבות את\u0004 כל ההנאות \u0003כולם\u0004 לאיסור.","ונדייק: \u0003טעמא\u0004 \u0005[הטעם\u0006 דוקא\u0005]\u0006 כיון ש\u0003כתב רחמנא\u0004 \u0005[הכתוב]\u0006 \u0003\"וערלתם ערלתו... ערלים\"\u0004 שהוא לשון הרחקה כפולה, \u0003הא לאו הכי, הוה אמינא\u0004 \u0005[הרי אם לא כך, הייתי אומר]:\u0006 \u0003איסור אכילה — משמע\u0004 מכאן, \u0003איסור הנאה — לא משמע,\u0004 אף שנכתב הלשון \"לא יאכל\", וקשה אפילו לחזקיה!","ודוחים: \u0003לעולם \"לא יאכל\" משמע בין איסור אכילה בין איסור הנאה, ושאני התם\u0004 \u0005[ושונה שם]\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \"יהיה \u0003לכם\u0004 ערלים\", ללמוד מכאן היתר הנאה. \u0003ואיצטריך\u0004 \u0005[והוצרך]\u0006 הכתוב לכתוב \"וערלתם ערלתו\", \u0003סלקא דעתך אמינא\u0004 \u0005[\u0006שאם \u0005יעלה על דעתך לומר]\u0006 \u0003הואיל וכתב \"לכם\"\u0004 כפי שדורשים \"לכם\" בכל מקום — \u0003שלכם יהא,\u0004 ומשמעו: מותר בהנאה. על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שהוא אסור בהנאה.","ושואלים: \u0003ואלא השתא דכתיבי הנך קראי\u0004 \u0005[עכשיו שכתובים מקראות אלה]\u0006 אם כן \u0003\"לכם\" למה לי?\u0004 והרי אין למדים מכאן דבר! ומשיבים שדרוש ביטוי זה \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"לכם\" — לרבות את הנטוע\u0004"],["\u0003לרבים,\u0004 שגם הנטוע לצורך הרבים חל עליו איסור ערלה לכל פרטיו. \u0003ר' יהודה אומר: להוציא את הנטוע לרבים,\u0004 שהוא מותר.","ומבארים: \u0003מאי טעמא דתנא קמא\u0004 \u0005[מה הטעם של התנא הראשון]\u0006 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ונטעתם\",\u0004 וכתוב זה \u0003ליחיד משמע,\u0004 שלכל יחיד ויחיד מדבר הכתוב, שכן נטיעה נעשית כרגיל על ידי יחיד, ואילו \u0003לרבים לא משמע.\u0004 לכן \u0003כתב רחמנא\u0004 \u0005[הכתוב]\u0006 \u0003\"לכם\"\u0004 בלשון רבים ברורה — \u0003להביא\u0004 בכלל איסור זה אף \u0003את הנטוע לרבים. ור' יהודה\u0004 המתיר בנטוע לרבים סבור כי \u0003\"ונטעתם\" משמע בין לרבים בין ליחיד, ו\u0004אף \u0003\"לכם\" בין יחיד בין רבים משמע,\u0004 אם כן \u0003הוי\u0004 \u0005[הרי זה]\u0006 \u0003רבוי אחר רבוי,\u0004 וכלל הוא בידינו: \u0003אין רבוי אחר רבוי\u0004 בא \u0003אלא למעט,\u0004 ומשמעו בפעם השניה \"לכם\" — למעט את של הרבים מכלל איסור זה, וזו כשיטת ר' יהודה.","ועוד מקשים על הלימוד העיקרי: \u0003והרי תרומה דרחמנא\u0004 \u0005[שהכתוב]\u0006 \u0003אמר \"וכל זר לא יאכל קדש\u0004 תושב כהן ושכיר לא יאכל קודש\u0003\"\u0004 (ויקרא כב, י), \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003מערבין\u0004 בעירובי תחומין וכיוצא בהם \u0003לנזיר ביין,\u0004 אף על פי שאסור בשתייתו. \u0003ולישראל בתרומה,\u0004 אף על פי שאסור באכילתה. הרי שמותר ליהנות מן התרומה, אף על פי שנאמר בה \"לא יאכל\", וקשה לר' אבהו שלדעתו יש בה גם כן איסור הנאה!","\u0003אמר רב פפא: שאני התם\u0004 \u0005[שונה שם]\u0006 שכן \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 \"ונחשב לכם \u0003תרומתכם\u0004 כדגן מן הגורן וכמלאה מן היקב\" (במדבר יח, כז), ולמדו מכאן: כי תרומתכם \u0003שלכם תהא,\u0004 שמותר לישראל ליהנות מן התרומה. ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 חזקיה, שלדעתו \"לא יאכל\" משמעו רק איסור אכילה, לשם מה זקוק הוא לתוספת של ההדגשה \"תרומתכם\"? ומשיבים: שלדעתו באמת אין ללמוד מכאן אלא \u0003\"תרומתכם\"\u0004 — תרומת \u0003כל ישראל\u0004 משמע, שהוא שימוש לשון במקרא ואין להוציא ממנו מסקנות.","ועוד מקשים על שיטת ר' אבהו: \u0003והרי נזיר, דרחמנא\u0004 \u0005[שהכתוב]\u0006 \u0003אמר \"\u0004כל ימי נזרו מכל אשר יעשה מגפן היין \u0003מחרצנים ועד זג לא יאכל\"\u0004 (במדבר ו, ד), \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]\u0006 \u0003מערבין לנזיר ביין\u0004 אף על פי שאסור בשתייתו, משמע שמותר לנזיר ליהנות מן היין אף שנאמר \"לא יאכל\"! \u0003אמר מר זוטרא: שאני התם\u0004 \u0005[שונה שם]\u0006 ש\u0003אמר קרא\u0004 \u0005[המקרא]\u0006 \u0003\"נזרו\"\u0004 שמשמעו — \u0003שלו יהא,\u0004 כלומר, עדיין היין קניינו וברשותו הוא.","\u0003רב אשי אמר:\u0004 ממקום אחר למדים זאת, שנאמר \u0003\"קדש יהיה גדל פרע שער ראשו\"\u0004 (במדבר ו, ה), ונדייק: \u0003גידולו\u0004 של השיער \u0003קדוש,\u0004 שאסור בהנאה ודינו בשריפה, \u0003ואין דבר אחר\u0004 שבנזירות \u0003קדוש\u0004 ואסור בהנאה. ומקשים: \u0003מידי\u0004 \u0005[וכי]\u0006 \u0003ואין דבר אחר כתיב\u0004 \u0005[נאמר]?!\u0006 הרי לא נאמר בכתוב אפילו רמז שהדברים באים לצמצם את חלות הקדושה ואיסור ההנאה לענין אחד בלבד! \u0003אלא מחוורתא\u0004 \u0005[מחוור,\u0006 ברור\u0005]\u0006 \u0003כ\u0004שיטת \u0003מר זוטרא\u0004 וכתירוצו.","ועוד מקשים על ר' אבהו: \u0003והרי חדש,\u0004 כלומר תבואה לפני זמן הקרבת העומר, \u0003דרחמנא\u0004 \u0005[שהכתוב]\u0006 \u0003אמר: \"ולחם וקלי וכרמל לא תאכלו עד עצם היום הזה\u0004 עד הביאכם את קרבן אלהיכם חוקת עולם לדורותיכם בכל מושבותיכם\u0003\"\u0004 (ויקרא כג, יד), \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003קוצר\u0004 את התבואה לפני העומר \u0003ל\u0004צורך \u0003שחת,\u0004 וכן קוטף בידו אפילו חיטים גמורות \u0003ומאכיל לבהמה,\u0004 הרי שמותר ליהנות ממנה למרות שנאמר \"לא תאכלו\"!","\u0003אמר רב שמעיה: שאני התם\u0004 \u0005[שונה שם]\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"קצירכם\",\u0004 ולמדים מכאן: \u0003קצירכם — שלכם יהא\u0004 כלומר, ברשותכם ולהנאתכם. ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 הוא חזקיה, שאיננו אוסר בהנאה, וממילא אינו צריך להדגשה יתירה זו, מה הוא למד מביטוי זה? ומשיבים: הוא סבור שאין כאן מקום לדיוק זה, אלא \u0003\"קצירכם\" — של כל ישראל משמע,\u0004 שנאמר הדבר בלשון רבים כמצוות רבות אחרות שנאמרו לכל ישראל.","ועוד מקשים על שתי השיטות: \u0003והרי שרצים, דרחמנא\u0004 \u0005[שהכתוב]\u0006 \u0003אמר \"\u0004וכל השרץ השורץ על הארץ \u0003שקץ הוא לא יאכל\"\u0004 (ויקרא יא, מא), ובכל זאת \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003ציידי חיה ועופות ודגים שנזדמנו להם מינין טמאין\u0004 שלא התכוונו תחילה לצודם — \u0003מותרין למוכרן לגוים.\u0004 הרי שאף שכתוב \"לא יאכל\" אין הדבר כולל איסור הנאה! ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 ש\u0003אמר קרא\u0004 \u0005[המקרא]\u0006 \u0003\"לכם\"\u0004 שמשמעו — \u0003שלכם יהא,\u0004 ומותרים אתם בהנאתו.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שהשרצים מותרים בהנאה לגמרי, \u0003אפילו לכתחלה נמי\u0004 \u0005[גם כן]\u0006 יהא מותר לחזר אחריהם לצודם כדי למוכרם לגוים, והלוא ההלכה אוסרת זאת! אלא \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"יהיו\"\u0004 משמעו — \u0003בהוייתן יהו,\u0004 כלומר ישארו בריחוקם ובשיקוצם.","ושואלים: \u0003ולחזקיה, למה לי למיכתב\u0004 \u0005[לכתוב]\u0006 קודם \u0003\"לא יאכל\"\u0004 שהוא איסור הנאה, \u0003ומייתי\u0004 \u0005[ולהביא]\u0006 אחר כך \u0003\"לכם\" למישרייה\u0004 \u0005[\u0006כדי \u0005להתירו].\u0006 ש\u0003לא לכתוב רחמנא\u0004 \u0005[יכתוב הכתוב]\u0006 \u0003\"לא יאכל\", ולא בעי\u0004 \u0005[יצטרך]\u0006 \u0003\"לכם\", אמר לך חזקיה\u0004 \u0005[\u0006יכול היה \u0005חזקיה\u0006 להשיב \u0005לך]\u0006 \u0003טעמא דידי נמי מהכא\u0004 \u0005[טעמי,\u0006 נימוקי \u0005שלי גם כן מכאן\u0006 הוא\u0005],\u0006 שממקור זה עצמו הוא למד את סברתו. שכן מן הצורך לכתוב במפורש \"לכם\", הרינו מבינים ש\"לא יאכל\" הריהו אף איסור הנאה, וצריך היה הכתוב ללמדנו זאת, וכאן אחד המקורות להלכה הכללית במשמעות \"לא יאכל\".","ועוד מקשים: \u0003והרי חמץ דרחמנא\u0004 \u0005[שהמקרא]\u0006 \u0003אמר \"לא יאכל חמץ\",\u0004 ובכל זאת, \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 : \u0003ר' יוסי הגלילי אומר: תמה על עצמך היאך\u0004 סבור אתה ש\u0003חמץ אסור בהנאה כל שבעה?\u0004 שלדעתו חמץ מותר בהנאה כל שבעת ימי הפסח וכל שכן לאחריו. ומכאן נבין שיש חכם הסבור שאפילו \"לא יאכל\" משמעו איסור אכילה בלבד! ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \"מצות יאכל את שבעת הימים ולא יראה לך חמץ \u0003ולא יראה לך שאר\u0004 בכל גבולך\" (שמות יג, ז), \"לך\" משמעו — \u0003שלך יהא,\u0004 ברשותך ולהנאתך.","ושואלים \u0003ורבנן\u0004 \u0005[ו\u0006שאר \u0005חכמים]\u0006 הסבורים כי חמץ יש בו איסור הנאה, מה לומדים הם מהדגשה זו? ומשיבים: שמן ההדגשה \"לך\" הם למדים: \u0003שלך אי אתה רואה,\u0004 כלומר חמץ השייך לך הוא שאסור, \u0003אבל אתה רואה של אחרים ושל גבוה\u0004 (הקדש). ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' יוסי\u0005]\u0006 כיצד לומד הוא הלכה זו? ומשיבים: \u0003תרי\u0004 \u0005[שני]\u0006 \u0003\"לך\" כתיבי\u0004 \u0005[כתובים]\u0006 בענין; אחד ללמד היתר ראיית חמץ של גוי הנמצא ברשותך, ואחד ללמד היתר הנאה.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 חכמים\u0005]\u0006 כיצד מבינים הם את הכפלת \"לך\"? הם מפרשים: \u0003חד\u0004 \u0005[אחד]\u0006 — \u0003בגוי שכיבשתו\u0004 והוא כפוף לישראל ונשמע לו, \u0003וחד\u0004 \u0005[ואחד]\u0006 — \u0003בגוי שלא כיבשתו,\u0004 ללמדנו שגם גוי המסור בידי ישראל וכפוף לו, אין חמצו הנמצא ברשותך אסור לך בראיה. \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' יוסי\u0005]\u0006, מהיכן לומד הוא הלכה זו? לדעתו \u0003תלתא\u0004 \u0005[שלושה]\u0006 \u0003\"לך\" כתיבי\u0004 \u0005[נאמרו]\u0006 בפרשה זו. \u0003ואידך\u0004 \u0005[והאחר,\u0006 חכמים\u0005]\u0006 אומרים כי \"לך\" אלה שבכתוב \u0003חד\u0004 \u0005[אחד]\u0006 — \u0003ב\u0004ענין \u0003שאור, וחד\u0004 \u0005[ואחד]\u0006 — \u0003ב\u0004ענין \u0003חמץ. וצריכי\u0004 \u0005[וצריכים]\u0006 שיכתוב במפורש בשניהם כפי שנתבאר במסכת ביצה (ז,ב) שאין ללמוד חמץ משאור, ולהיפך.","מנסים להציע: \u0003לימא כתנאי\u0004 \u0005[האם לומר כ\u0006מחלוקת \u0005תנאים]\u0006 שנחלקו בבעיה זו, היא מחלוקתם של חזקיה ור' אבהו בענין משמעות \"לא תאכל\". כי על הכתוב \"וחלב נבלה וחלב טרפה \u0003יעשה לכל מלאכה\u0004 ואכול לא תאכלהו\" (ויקרא ז, כד) שנינו: \u0003מה תלמוד לומר: \"לכל מלאכה\", שיכול למלאכת גבוה\u0004 (כלומר, לצרכי המקדש) \u0003יהא מותר\u0004 החלב, אבל \u0003למלאכת הדיוט יהא אסור, תלמוד לומר: \"לכל מלאכה\"\u0004 — אלו \u0003דברי ר' יוסי הגלילי.\u0004","\u0003ר' עקיבא אומר\u0004 להיפך: \u0003שיכול למלאכת הדיוט יהא\u0004 חלב נבילה \u0003טהור\u0004 וראוי לשימוש, ו\u0003למלאכת גבוה יהא טמא — תלמוד לומר: \"לכל מלאכה\".\u0004","ואם נמשיך ונפרש את מחלוקתם, יש לומר כי \u0003ר' יוסי הגלילי לטומאה ולטהרה לא איצטריך קרא\u0004 \u0005[הוצרך מקרא]\u0006 שאין מקום להניח טומאה בחלב. \u0003כי איצטריך קרא\u0004 \u0005[כאשר הוצרך המקרא]\u0006 להדגיש \"לכל מלאכה\" הרי זה \u0003לאיסור ולהיתר. ור' עקיבא,\u0004 לדעתו \u0003איסור והיתר לא צריך קרא\u0004 \u0005[מקרא]\u0006 מיוחד, \u0003כי איצטריך קרא\u0004 \u0005[כאשר הוצרך המקרא]\u0006 הרי זה \u0003לטומאה ולטהרה.\u0004"],["\u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006דבר \u0005זה נחלקו],\u0006 ש\u0003ר' יוסי הגלילי סבר: \"לא תאכלו\" משמע בין איסור אכילה בין איסור הנאה\u0004 הרי שנבילה אסורה בהנאה, \u0003וכי אתא קרא\u0004 \u0005[וכאשר בא המקרא]\u0006 \"יעשה לכל מלאכה\" \u0003למישרייה\u0004 \u0005[להתירה]\u0006 \u0003לנבילה\u0004 — \u0003בהנאה הוא דאתא\u0004 \u0005[שבא].\u0006 \u0003ור' עקיבא סבר:\u0004 \"לא תאכלו\" — \u0003איסור אכילה\u0004 בלבד \u0003משמע, ואיסור הנאה לא משמע.\u0004 ולכן אין צורך בכתוב מיוחד להתיר נבילה בהנאה, ולכן \u0003כי אתא קרא\u0004 \u0005[כאשר בא המקרא]\u0006 \"יעשה לכל מלאכה\" כוונתו \u0003ל\u0004ענין דיני \u0003טומאה וטהרה,\u0004 ונמצא שכבר נחלקו התנאים בשאלת משמעות האיסור \"לא תאכל\".","את ההנחה הזו דוחים: \u0003לא,\u0004 אפשר לומר כי לדעת \u0003כולי עלמא\u0004 \u0005[הכל]\u0006 \u0003\"לא תאכלו\" משמע בין איסור אכילה בין איסור הנאה.\u0004 ואילו \u0003הכא, בהא קמיפלגי\u0004 \u0005[כאן, ב\u0006דבר \u0005זה נחלקו],\u0006 \u0003ר' יוסי הגלילי סבר: כשהותרה נבילה\u0004 בהנאה, \u0003היא\u0004 עצמה \u0003הותרה\u0004 ואולם \u0003חלבה וגידה לא הותרו\u0004 יחד עמה. \u0003וכי איצטריך קרא\u0004 \u0005[וכאשר הוצרך המקרא]\u0006 \"יעשה לכל מלאכה\" הרי \u0003להיתר הנאה הוא דאתא\u0004 \u0005[שבא],\u0006 שהרי לא ידענו קודם שהחלב מותר בהנאה. \u0003ו\u0004אילו \u0003ר' עקיבא סבר: כשהותרה נבילה\u0004 בהנאה — \u0003חלבה וגידה נמי\u0004 \u0005[גם כן]\u0006 \u0003הותרו\u0004 בהנאה. \u0003ו\u0004לכן \u0003כי איצטריך קרא\u0004 \u0005[וכאשר הוצרך המקרא]\u0006 הרי זה \u0003לטומאה וטהרה.\u0004","ושואלים: \u0003ו\u0004לשיטת \u0003ר' יוסי הגלילי, אשכחן\u0004 \u0005[מצאנו\u0006 במפורש\u0005]\u0006 ב\u0003חלב דשרייה רחמנא\u0004 \u0005[שהתירו הכתוב]\u0006 \u0003בהנאה, אלא גיד\u0004 הנשה \u0003נימא\u0004 \u0005[נאמר]\u0006 ש\u0003אסור,\u0004 שהרי לשיטה זו לא הותרה הנאתו! ומתרצים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 ש\u0003אסור,\u0004 שבאמת לשיטה זו גיד הנשה אסור בהנאה. \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שגיד הנשה אכן מותר בהנאה, ו\u0003מייתי לה\u0004 \u0005[מביא,\u0006 לומד הוא, דבר \u0005זה]\u0006 היתר הנאת גיד הנשה \u0003בקל וחומר\u0004 זה: \u0003ומה חלב שענוש כרת\u0004 על אכילתו במזיד — \u0003מותר בהנאה, גיד\u0004 הנשה \u0003שאינו ענוש כרת\u0004 על אכילתו במזיד — \u0003לא כל שכן\u0004 שמותר בהנאה.","ושואלים: \u0003ור' שמעון\u0004 ש\u0003אסר\u0004 כל גיד הנשה בהנאה, מדוע אינו מקבל קל וחומר זה שעל פיו יש להתיר בהנאה כל גיד הנשה? ומשיבים: לדעתו \u0003איכא\u0004 \u0005[יש]\u0006 מקום \u0003למיפרך\u0004 \u0005[לפרוך,\u0006 לשבור\u0005]\u0006 קל וחומר זה, כיון שאין ללמוד מאיסור חלב לענין איסור גיד הנשה מתוך הנחה שאיסור חלב חמור יותר, שכן \u0003מה לחלב שכן הותר מכללו אצל חיה,\u0004 שהרי איסור זה חל רק על בהמה טהורה, אבל חלב חיות טהורות מותר באכילה, \u0003תאמר בגיד שלא הותר מכללו אצל חיה.\u0004 ונמצא שיש חומרה באיסור גיד הנשה שאינה באיסור חלב, ואין איפוא ללמוד קל וחומר.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' יוסי\u0005]\u0006 המתיר את הגיד על ידי קל וחומר זה, מה משיב הוא לפירכה זו? ואומרים: \u0003בבהמה קאמרינן\u0004 \u0005[אומרים אנו]\u0006 שהרי קל וחומר זה \u0003בבהמה מיהת\u0004 \u0005[על כל פנים]\u0006 \u0003לא אישתרי\u0004 \u0005[הותר]\u0006 חלב, ובבהמה יש בו איסור חמור יותר מאשר בגיד, ולכן אפשר ללמוד מכאן קל וחומר.","לאחר שביררו ודנו בענינים מרובים בדיני איסורי אכילה והנאה, שואלים: \u0003מכדי אותבינהו כל הני קראי ושנינהו\u0004 \u0005[הרי הקשינו כל המקראות הללו ותירצנום],\u0006 ומצאנו שבכל המקרים אין שום הבדל לבסוף, מצד הענין, ובכל מקום שנאמר \"לא תאכל\" אין בו איסור הנאה. ואם כן, \u0003חזקיה ור' אבהו במאי פליגי\u0004 \u0005[במה\u0006 באיזו נושא\u0005, נחלקו]\u0006 שהרי לכאורה אין כל הבדל ביניהם! ומשיבים: נחלקו \u0003בחמץ בפסח ואליבא רבנן\u0004 \u0005[ועל פי\u0006 שיטת \u0005חכמים]\u0006 האוסרים אותו בהנאה, וכן \u0003בשור הנסקל ואליבא\u0004 \u0005[ולפי\u0006 שיטת\u0005]\u0006 \u0003דברי הכל.\u0004 ומפרשים: \u0003חזקיה נפיק ליה\u0004 \u0005[יוצא לו]\u0006 ענין איסור זה \u0003מ\"לא יאכל\", ור' אבהו נפיק\u0004 \u0005[יוצא לו]\u0006 ענין זה \u0003מ\u0004תוך שהתירה התורה הנאת \u0003נבילה,\u0004 ובפירושי פסוקים אלה נחלקו שני האמוראים.","ושואלים: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003בין למר\u0004 \u0005[לחכם זה]\u0006 \u0003ובין למר\u0004 \u0005[לחכם זה]\u0006 \u0003אסורין\u0004 הן \u0003בהנאה\u0004 אף שאינם מסכימים לאותו מקור בפסוק, ואם כן \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל המעשי \u0005ביניהם]\u0006 ומתרצים: \u0003איכא בינייהו\u0004 \u0005[יש\u0006 הבדל מעשי \u0005ביניהם]\u0006 לענין \u0003חולין שנשחטו בעזרה. חזקיה סבר: \"לא יאכל\" — למעוטי הני\u0004 \u0005[למעט\u0006 את \u0005אלה]\u0006 שיש בהם איסור אכילה בלבד, \u0003\"אתו\" — למעוטי\u0004 \u0005[למעט]\u0006 \u0003חולין שנשחטו בעזרה.\u0004","ואילו \u0003ר' אבהו סבר: \"אתו\" — למעוטי הני\u0004 \u0005[למעט\u0006 את \u0005אלה],\u0006 ואילו \u0003חולין שנשחטו בעזרה — לאו דאורייתא נינהו\u0004 \u0005[לא מן התורה הם]\u0006 אלא מגזירת חכמים. נמצא שחולקים הם ביחס לדין חולין שנשחטו בעזרה אם הוא מן התורה, ובכך יש גם הבדל הלכה למעשה.","מסופר: \u0003יתיב ההוא מרבנן קמיה\u0004 \u0005[ישב אחד החכמים לפני]\u0006 \u0003ר' שמואל בר נחמני, ויתיב וקאמר משמיה\u0004 \u0005[וישב ואמר משמו]\u0006 של \u0003ר' יהושע בן לוי: מנין לכל איסורין שבתורה דכי היכי\u0004 \u0005[שכמו]\u0006 ש\u0003אסורין באכילה הכי נמי\u0004 \u0005[כך גם כן]\u0006 \u0003אסורין בהנאה? ומאי ניהו\u0004 \u0005[ומה הם]\u0006 אותם איסורים שאנו רוצים להוכיח עליהם — \u0003חמץ בפסח ושור הנסקל?\u0004 ותוהים מיד: מה משמעה של השאלה \u0003מנין?! תיפוק ליה\u0004 \u0005[יצא\u0006 ילמד \u0005לו]\u0006 אותו האיסור \u0003מ\u0004הכתוב \u0003\"לא יאכל\"!\u0004 ומשיבים: \u0003\"לא יאכל\"\u0004 רק \u0003איסור אכילה משמע ליה\u0004 \u0005[נשמע\u0006 מובן \u0005לו]\u0006 מכאן, ואילו \u0003איסור הנאה לא משמע ליה\u0004 \u0005[נשמע\u0006 מובן \u0005לו]\u0006 מכאן.","ומקשים: \u0003תיפוק ליה\u0004 \u0005[יצא\u0006 ילמד \u0005לו]\u0006 אותו האיסור \u0003מ\u0004תוך שהותרה הנאת \u0003נבילה\u0004 במפורש?! ומשיבים: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כר' יהודה\u0004 ש\u0003אמר\u0004 בענין נבילה: הרי זה \u0003דברים ככתבן\u0004 ואינו בא ללמד דבר.","ומקשים: \u0003אי סבר לה\u0004 \u0005[אם סבור הוא]\u0006 \u0003כר' יהודה,\u0004 אם כן \u0003תיפוק ליה מהיכא דנפקא ליה\u0004 \u0005[תצא לו\u0006 הלכה זו \u0005מהיכן שיצאה לו]\u0006 \u0003לר' יהודה,\u0004 מן הכתוב \u0003\"\u0004ובשר בשדה טרפה לא תאכלו \u0003לכלב תשלכון אתו\"\u0004 (שמות כב, ל) שדרש: אותו משליכים לכלב, אבל אין משליכים לכלב שאר איסורים שבתורה, ולמדנו מכאן איסור הנאה לחמץ בפסח וכיוצא בו!","ודוחים: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 חכם זה כי \u0003חולין שנשחטו בעזרה\u0004 אסורים בהנאה \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 ו\"אותו\" שנאמר בכתוב בא ללמד לענין איסור הנאתם. ו\u0003מנין\u0004 למד הוא איסור הנאה בשאר דברים, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"וכל חטאת אשר יובא מדמה\u0004 אל אוהל מועד לכפר בקודש לא תאכל באש תשרף\u0003\"\u0004 (ויקרא ו, כג),","\u0003שאין תלמוד לומר \"באש תשרף\",\u0004 כאשר יבואר, \u0003ו\u0004אלא \u0003מה תלמוד לומר \"באש תשרף\"? אם אינו ענין לגופו,\u0004 שדבר זה יודעים אנו כבר ממה \u0003דכתיב\u0004 \u0005[ש\u0006הרי כבר \u0005נאמר]\u0006 \u0003\"\u0004ואת שעיר החטאת דרוש דרש משה \u0003והנה שרף\"\u0004 (ויקרא י, טז), ולמדנו שאילו הובא היה נשרף, ואין צורך בחזרה על הלכה זו, לכן \u0003תנהו ענין לכל איסורין שבתורה\u0004 שנאסרו באכילה,"],["\u0003ואם אינו ענין לאכילה\u0004 שהרי כבר נאמר איסור אכילה בכל אחד מאלה, \u0003תנהו ענין לאיסור הנאה.\u0004","ומוסיפים לדון \u0003אי\u0004 \u0005[או]\u0006 שמא תאמר: \u0003מה כאן\u0004 בחטאת דינה \u0003בשריפה — אף כל איסורין שבתורה\u0004 חייבים \u0003בשריפה!\u0004 ודוחים: \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 \u0003\"בקדש... באש תשרף\"\u0004 (ויקרא ו, כג), דבר ש\u0003בקדש\u0004 שנפסל — נידון \u0003בשריפה, ואין כל\u0004 שאר ה\u0003איסורין שבתורה בשריפה.\u0004","ושאל ר' שמואל בר נחמני: \u0003והאי\u0004 \u0005[ו\u0006פסוק \u0005זה]\u0006 \u0003\"בקדש... באש תשרף\" להכי\u0004 \u0005[לכך]\u0006 ללמד דבר זה \u0003הוא דאתא\u0004 \u0005[שבא]?!\u0006 \u0003האי מיבעי ליה\u0004 \u0005[\u0006דבר \u0005זה נצרך לו\u0006 ללמד\u0005]\u0006 לשיטתו של \u0003ר' שמעון, דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' שמעון אומר: \"בקדש... באש תשרף\" — לימד על חטאת\u0004 פסולה \u0003ששורפין אותה בקדש,\u0004 ואין מוציאים אותה לשריפה מחוץ למקדש. \u0003ואין לי אלא זו בלבד, פסולי קדשי קדשים, ואימורי\u0004 (החלב ושאר חלקי הבהמה המועלים למזבח) \u0003קדשים קלים\u0004 שנטמאו \u0003מנין\u0004 שנשרפים בקודש? \u0003תלמוד לומר: \"בקדש... באש תשרף\"\u0004 שכל שנפסל שריפתו תהיה בקודש.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו חכם ששנה הלכה זו לר' שמואל בר נחמני: \u0003ר' יונתן רבך מהאי קרא קאמר\u0004 \u0005[ממקרא זה אמר]\u0006 \u0003לה\u0004 אותה הלכה עצמה, נאמר \u0003\"ואם יותר מבשר המלאים ומן הלחם עד הבקר\u0004 ושרפת את הנותר באש לא יאכל כי קודש הוא\" (שמות כט, לד), \u0003שאין תלמוד לומר \"לא יאכל\"\u0004 כאשר יבואר, \u0003ומה תלמוד לומר \"לא יאכל\" — אם אינו ענין לגופיה\u0004 \u0005[לגופו],\u0006 \u0003דהא כתיב\u0004 \u0005[שהרי נאמר]\u0006 במפורש \u0003\"ושרפת את הנותר באש\"\u0004 משמע שאסור לאוכלו, \u0003תנהו ענין לשאר איסורין שבתורה\u0004 שנזכר בהם איסור אכילה, \u0003ואם אינו ענין לאכילה\u0004 שהרי נאסרה אכילה בכל אלה במפורש, \u0003תנהו ענין לאיסור הנאה,\u0004 ששאר איסורי אכילה שבתורה הם אף איסורי הנאה.","ודנים עוד: \u0003אי\u0004 \u0005[או]\u0006 אולי נאמר: \u0003מה כאן בשריפה, אף\u0004 נאמר ש\u0003כל איסורין שבתורה\u0004 שהנאתם נאסרה אף הם \u0003בשריפה\u0004 — על כן \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 \u0003\"ושרפת את הנותר\"\u0004 למעט: \u0003נותר\u0004 דינו \u0003בשריפה, ואין כל איסורין שבתורה בשריפה\u0004 אף שאסורים בהנאה.","ומקשים: \u0003והאי\u0004 \u0005[ו\u0006פסוק \u0005זה]\u0006 \u0003\"לא יאכל\" להכי\u0004 \u0005[לכך]\u0006 לדבר זה \u0003הוא דאתא\u0004 \u0005[שבא]\u0006 ללמד? \u0003האי\u0004 \u0005[\u0006דבר \u0005זה]\u0006 \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 \u0003לכדר' אלעזר,\u0004 ש\u0003אמר ר' אלעזר: \"לא יאכל כי קדש הוא\"\u0004 — משמע \u0003כל שבקדש פסול,\u0004 כל דבר שנפסל בתוך הקודש \u0003בא הכתוב ליתן לא תעשה על אכילתו.\u0004 שאנו לומדים ממנו הלכה כללית, שכל דבר של קודש שחל בו פסול, האוכלו עובר בלאו ולוקה,","\u0003אמר אביי: לעולם\u0004 תלמד הלכה זו \u0003מקרא קמא\u0004 \u0005[מהמקרא הראשון]\u0006 שדרש ר' יהושע בן לוי \"כל חטאת אשר יובא מדמה לכפר בקדש לא תאכל באש תשרף\", \u0003ואיפוך\u0004 \u0005[והפוך]\u0006 את מבנה הדרשה, וכך צריך להבינה כעת: \u0003דליכתוב\u0004 \u0005[שיכתוב]\u0006 המקרא \u0003\"באש תשרף\", ולא בעי\u0004 \u0005[יצטרכו]\u0006 לכתוב \u0003\"לא תאכל\", מה תלמוד לומר \"לא תאכל\" — אם אינו ענין לגופו, דנפקא ליה\u0004 \u0005[שיוצא לו,\u0006 שלמד\u0005]\u0006 \u0003מ\u0004דברי \u0003ר' אלעזר\u0004 שכל דבר שנפסל בקדש ממילא אסור באכילה, \u0003תנהו ענין לכל איסורין שבתורה. ואם אינו ענין לאכילה\u0004 שנאסרה במפורש \u0003תנהו ענין לאיסור הנאה.\u0004","והרי אפשר להקשות: \u0003אי\u0004 \u0005[או]\u0006 אולי נאמר \u0003מה כאן בשריפה, אף כל איסורין שבתורה בשריפה. אמר קרא\u0004 \u0005[המקרא]\u0006 \u0003\"הנותר\" — הנותר בשריפה, ואין כל\u0004 שאר \u0003איסורין שבתורה בשריפה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי:\u0004 מדוע סבור אתה ש\"לא תאכל\" האמור בחטאת חיצונה שהוכנסה לפנים אינו נחוץ לענינו? \u0003ואימא ליחודי ליה לאו לגופיה הוא דאתא\u0004 \u0005[ואמור\u0006 שביטוי זה כדי \u0005לייחד\u0006 לאיסור \u0005זה לאו\u0006 מיוחד \u0005ל\u0006צורך \u0005עצמו הוא שבא],\u0006 שהרי לא למדנו קודם איסור מפורש ומיוחד באכילת חטאת זו, ודבר זה בא הכתוב ללמדנו. \u0003דאי\u0004 \u0005[שאם]\u0006 ללמוד איסור זה רק \u0003מ\u0004דברי \u0003ר' אלעזר,\u0004 הרי איסור אכילת בשר חטאת שנכנס דמה לקודש אף שיש בו מצוות לא תעשה — אין לוקים עליו, כי הכלל הוא ש\u0003\"אין לוקין על לאו שבכללות\",\u0004 שכל איסור לאו הכולל דינים רבים כגון זה שנכללו בו כל הפסולים — אין לוקים כאשר עוברים עליו, שאין האיסור מפורש די צורכו. ולכן אפשר לומר ש\"לא תאכל\" שנאמר לענין זה בא לומר שיש כאן איסור מיוחד ולוקים עליו, ואם כן — אין כאן יתור.","\u0003אלא\u0004 יש לדחות מה שאמרנו, ו\u0003רב פפא\u0004 לומד דבר זה \u0003מהכא\u0004 \u0005[מכאן]:\u0006 שנאמר \u0003\"והבשר אשר יגע בכל טמא לא יאכל באש ישרף\u0004 והבשר כל טהור יאכל בשר\u0003\"\u0004 (ויקרא ז, יט), \u0003שאין תלמוד לומר \"לא יאכל\"\u0004 כפי שיבואר, \u0003ומה תלמוד לומר \"לא יאכל\"?\u0004","\u0003אם אינו ענין לגופו, דהא נפקא ליה\u0004 \u0005[שהרי יוצא לו\u0006 נלמד\u0005]\u0006 \u0003מקל וחומר ממעשר הקל.\u0004 שכן אפשר לומר: \u0003מה מעשר הקל\u0004 בדיניו, שאינו נחשב מן הקודשים, \u0003אמרה תורה\u0004 שבשעת וידוי המעשר, בשעה שמבערים מן הבית את המעשר שלא ניתן, יש לומר \u0003\"\u0004לא אכלתי באוני ממנו \u0003ולא בערתי ממנו בטמא\"\u0004 (דברים כו, יד), משמע שאף מעשר אסור לבערו בטומאה. \u0003בשר קדש\u0004 שהוא \u0003חמור, לא כל שכן\u0004 שאין לאוכלו בטומאה?!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 הלוא קיים הכלל ש\u0003\"אין מזהירין מן הדין\"\u0004 כלומר אין ללמוד אזהרת לא תעשה בדרך קל וחומר בלבד. ואולם דבר זה אינו רק קל וחומר אלא \u0003הקישא\u0004 \u0005[היקש\u0006 השוואה\u0005]\u0006 \u0003הוא\u0004 שהושווה במפורש, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא תוכל לאכל בשעריך מעשר דגנך ותירשך ויצהרך ובכרת בקרך\u0004 וצאנך וכל נדריך אשר תדור ונדבותיך ותרומת ידך\u0003\"\u0004 (דברים יב, יז), הרי שהכתוב עצמו משווה את המעשר עם כמה מיני קרבנות (\"נדריך ונדבותיך\"), וכיון שכך, יכולים היטב ללמוד אזהרת לאו מדין המעשר.","ואם כן \u0003מה תלמוד לומר \"לא יאכל\"\u0004 הכתוב לענין טומאת בשר קודש? \u0003אם אינו ענין לגופו\u0004 שהרי כבר למדנו דבר זה ממעשר, \u0003תנהו ענין לכל איסורין שבתורה. ואם אינו ענין לאכילה\u0004 שאנו יודעים איסורה בכל מקרה, \u0003תנהו ענין ל\u0004איסור \u0003הנאה.\u0004","ואם תאמר: \u0003אי\u0004 \u0005[או]\u0006 אולי נאמר \u0003מה כאן\u0004 בבשר שנפסל במקדש דינו \u0003בשריפה, אף כל איסורין שבתורה\u0004 יהא דינם \u0003בשריפה,\u0004 על כן \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 \u0003\"הנותר\"\u0004 — משמעו בהדגשה ללמד: \u0003הנותר\u0004 נידון \u0003בשריפה, ואין כל\u0004 שאר \u0003איסורין שבתורה בשריפה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: ואימא\u0004 \u0005[ואמור]\u0006 שביטוי זה \"לא יאכל\" שאינו צריך לגופו, לא בא ללמדנו לדבר אחר אלא \u0003לעבור עליו בשני לאוין,\u0004 כלומר ללמדנו שבאיסור זה עצמו יש לא רק מצות לא תעשה אחת, אלא שתים הן. ויש לנו ראיה שיש הבדל אם נאמר רק לאו אחד או שני לאוין בנושא כלשהו. \u0003לאו מי\u0004 \u0005[האם לא]\u0006 \u0003אמר אביי\u0004 כגון זה: \u0003אכל פוטיתא\u0004 (שרץ מים קטן) — \u0003לוקה ארבע\u0004 פעמים. משום שיש ארבעה איסורי לאו החלים על שרץ המים, שניים מהם בפסוק \"אל תשקצו את נפשותיכם בכל השרץ השורץ ולא תטמאו בהם ונטמתם בם\" (ויקרא יא, מג) האמורים בכל מיני שרצים. וכן האמור בשרץ המים \"וכל אשר אין לו סנפיר וקשקשת... ושקץ יהיו לכם מבשרם לא תאכלו\" (ויקרא יא, י—יא), וכן \"וכל אשר אין לו סנפיר וקשקשת לא תאכלו טמא הוא לכם\" (דברים יד, י).","אכל \u0003נמלה — לוקה חמש,\u0004 שני הלאוין האמורים בכל שרץ, ועוד \"וכל השרץ השורץ על הארץ שקץ הוא לא יאכל\" (ויקרא יא, מא), וכן \"לכל השרץ השורץ על הארץ לא תאכלום כי שקץ הם\" (ויקרא יא, מב), וכן \"ולא תטמאו את נפשותיכם בכל השרץ הרמש על הארץ (ויקרא יא, מד)."],["אכל \u0003צירעה — לוקה שש\u0004 מלקויות. שכן הצירעה רומשת גם על הארץ, וממילא חלים עליה כל הלאוין של שרץ הארץ, ועוד לאו נוסף \"וכל שרץ העוף טמא הוא לכם לא יאכלו\" (דברים יד, יט). ולפי עקרון זה נוכל לומר כי אותו \"לא יאכל\" שנאמר בטומאת בשר בא רק להוסיף איסור לאו נוסף, להעניש עליו! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003כל היכא דאיכא למדרש\u0004 \u0005[מקום שיש לדרוש]\u0006 וללמוד ממנו דבר חדש — \u0003דרשינן\u0004 \u0005[דורשים אנו],\u0006 \u0003ולא מוקמינן בלאוי יתירי\u0004 \u0005[ואיננו מעמידים\u0006 מסבירים\u0005, בלאוים יתירים]\u0006 על אותו איסור עצמו.","ושואלים: ואותו כתוב שנאמר שם \u0003\"והבשר אשר יגע בכל טמא לא יאכל\"\u0004 (ויקרא ז, יט) \u0003דרישיה\u0004 \u0005[שבתחילת\u0006 הפסוק\u0005]\u0006 \u0003למה לי?\u0004 ומסבירים: \u0003לרבות עצים ולבונה\u0004 שהם נטמאים. שאף שאינם דבר מאכל, מכל מקום למדים מפסוק זה הלכה כוללת לגבי כל הדברים הנטמאים. ושואלים: ומה שנאמר \u0003\"והבשר כל טהור יאכל בשר\"\u0004 (ויקרא ז, יט) \u0003דסיפיה\u0004 \u0005[שבסוף\u0006 הפסוק\u0005]\u0006 \u0003למה לי?\u0004 ומשיבים: \u0003לרבות אימורין\u0004 החלב ושאר חלקי הבהמה המועלים למזבח, שאף הם בכלל בשר לענין טומאה, שאימורים שנטמאו ואכלם אפילו טהור — לוקה.","ומקשים: \u0003אימורין\u0004 שמקבלין טומאה, \u0003מהתם נפקא\u0004 \u0005[משם\u0006 ממקור אחר \u0005יוצא\u0006 הלימוד\u0005],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"והנפש אשר תאכל בשר מזבח השלמים אשר לה'\u0004 וטומאתו עליו ונכרתה הנפש ההיא מעמיה\u0003\"\u0004 (ויקרא ז, כ), ומן התוספת \"אשר לה'\" למדנו \u0003לרבות את האימורין\u0004 שהם חלק הזבח הניתן לה', ואין בני אדם אוכלים אותו, שאף בו יש איסור טומאה!","ודוחים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר ב\u0003טומאת הגוף,\u0004 באיסור החל על אדם טמא לאכול מן הקודשים — שעונשו הוא \u0003בכרת, הכא\u0004 \u0005[כאן]\u0006 מדובר ב\u0003טומאת בשר,\u0004 כאשר הבשר טמא אף שהאוכלו טהור — שעונשו הוא \u0003בלאו\u0004 בלבד.","כיון שעסקנו בבעיות איסורי אכילה ואיסורי הנאה, מביאים מה ש\u0003אמר ר' אבהו אמר ר' יוחנן: כל איסורין\u0004 (של אכילה) \u0003שבתורה — אין לוקין עליהם אלא דרך אכילתם\u0004 הרגילה, ואם אכל דבר שלא כדרך שרגילים לאוכלו אין לוקין עליו. ושואלים: \u0003למעוטי מאי\u0004 \u0005[למעט,\u0006 להוציא, את \u0005מה]?\u0006 \u0003אמר רב שימי בר אשי: למעוטי\u0004 \u0005[למעט]\u0006 \u0003שאם אכל חלב חי\u0004 (בלתי מבושל), \u0003שפטור,\u0004 שאין זו דרך אכילת חלב.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכך \u0003אמר ר' אבהו אמר ר' יוחנן: כל איסורין\u0004 (של הנאה) \u0003שבתורה אין לוקין עליהם אלא\u0004 אם נהנה מהם \u0003דרך הנאתן\u0004 הרגילה. ושאלו: \u0003למעוטי מאי\u0004 \u0005[למעט,\u0006 להוציא \u0005מה]?\u0006 \u0003אמר רב שימי בר אשי: למעוטי\u0004 \u0005[למעט]\u0006 \u0003שאם הניח חלב של שור הנסקל\u0004 (שאסור בהנאה) \u0003על גבי מכתו\u0004 (פצעו) להתרפא בכך, \u0003שהוא פטור.\u0004 שכן אין משתמשים בחלב לרפואה, ולכן אין זו דרך ההנאה הרגילה מחלב. \u0003וכל שכן\u0004 ה\u0003אוכל חלב חי, שהוא פטור,\u0004 שאין אדם נהנה בכך, ובודאי אין זו דרך הנאתו.","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 אותו ענין משמם של אמוראים אחרים ש\u0003אמר רב אחא בר עויה אמר רב אסי אמר ר' יוחנן: הניח חלב של שור הנסקל על גבי מכתו\u0004 לרפואה — \u0003פטור, לפי שכל איסורין שבתורה אין לוקין עליהם אלא דרך הנאתן.\u0004","\u0003אמר ר' זירא: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 כעין זה במשנה. שאמרו חכמים: \u0003אין סופגין\u0004 (לוקים) \u0003את הארבעים\u0004 מלקות \u0003משום\u0004 איסור שתיית משקה הנסחט מפרי עץ \u0003ערלה, אלא על\u0004 המשקה \u0003היוצא מן הזיתים ומן הענבים בלבד.\u0004 ומכאן נדייק: \u0003ואילו\u0004 המשקה היוצא \u0003מתותים תאנים ורמונים — לא,\u0004 אינו לוקה עליהם מן התורה, אף שפירות אלה אסורים באכילה. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 ש\u0003לא קאכיל להו\u0004 \u0005[אוכל אותם]\u0006 ב\u0003דרך הנאתן\u0004 הרגילה, שפירות אלה דרך בני אדם לאוכלם ולא לסחוט מהם משקה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 אפשר לדחות ראיה זו, \u0003בשלמא אי אשמעינן\u0004 \u0005[נניח אם היה משמיע לנו]\u0006 בענין ה\u0003פרי גופא\u0004 \u0005[עצמו]\u0006 כש\u0003לא קאכיל ליה\u0004 \u0005[אוכל אותו]\u0006 ב\u0003דרך הנאתו הרגילה — שפיר\u0004 \u0005[יפה]\u0006 אז אפשר היה ללמוד מכאן הלכה זו, \u0003אלא הכא\u0004 \u0005[כאן]\u0006 שלא אסר במשקי תותים ותאנים, הטעם הוא \u0003משום\u0004 ש\u0003זיעה בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא\u0004 ואינו נידון כחלק מהותי מן הפרי.","\u0003אמר אביי: הכל מודים בכלאי הכרם שלוקין עליהן אפילו\u0004 אם נהנה מהם \u0003שלא כדרך הנאתן, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — \u0003משום\u0004 ש\u0003לא כתיב בהו\u0004 \u0005[נאמר בהם]\u0006 איסור \u0003אכילה\u0004 במפורש, ומלשון הכתוב נראה שאין ליהנות ממנו כלל אלא לשורפו בלבד.","\u0003מיתיבי\u0004 \u0005[מקשים],\u0006 \u0003איסי בן יהודה אומר: מנין לבשר בחלב שהוא אסור\u0004 באכילה? \u0003נאמר כאן \"כי עם קדוש אתה\u0004 לה' אלהיך לא תבשל גדי בחלב אמו\u0003\"\u0004 (דברים יד, כא), \u0003ונאמר להלן \"ואנשי קדש תהיון לי\u0004 ובשר בשדה טרפה לא תאכלו לכלב תשליכון אותו\u0003\"\u0004 (שמות כב, ל). \u0003מה להלן\u0004 בענין טריפה \u0003אסור\u0004 באכילה, \u0003אף כאן אסור\u0004 בשר בחלב באכילה.","\u0003ואין לי אלא\u0004 באיסור \u0003אכילה\u0004 כטריפה, אסור \u0003בהנאה מנין? אמרת, קל וחומר: ומה ערלה שלא נעבדה בה עבירה\u0004 שהרי העץ גדל כדרכו, ובשלוש שנותיו הראשונות הינו ממילא ערלה, ובכל זאת \u0003אסורה בהנאה. בשר בחלב שנעבדה בו עבירה\u0004 כשבישלו אף שאסור לבשלו, \u0003אינו דין שיהא אסור בהנאה?\u0004"],["את הקל וחומר הזה דוחים: \u0003מה לערלה שכן לא היתה לה שעת הכושר,\u0004 שהרי הערלה חמורה לפי שלא היתה לה כלל שעה שהיתה כשרה בה, שמשעה שגדל העץ עד זמן היתרו הריהו אסור — \u0003תאמר בבשר בחלב, שהיתה לו שעת הכושר!\u0004 שהרי הבשר והחלב היו מותרים כל אחד בפני עצמו לפני שבישלום יחד. ולכן מביאים ראיה אחרת: \u0003חמץ בפסח יוכיח — שהיה לו שעת הכושר\u0004 לפני חג הפסח, \u0003ו\u0004בכל זאת \u0003אסור בהנאה.\u0004","ודוחים: \u0003מה לחמץ בפסח\u0004 שהוא חמור — \u0003שכן\u0004 האוכלו \u0003ענוש כרת, תאמר בבשר בחלב ש\u0004האוכלו \u0003אינו ענוש כרת!\u0004 ומשיבים: \u0003כלאי הכרם יוכיחו, שאין ענוש כרת — ואסור בהנאה.\u0004","עד כאן הדיון שהיה, ולעניננו שואלים: \u0003ואם\u0004 אמנם \u0003איתא\u0004 \u0005[יש]\u0006 לקבל את ההלכה שכלאי הכרם לוקים עליהם אף שלא כדרך הנאתם, \u0003ניפרוך\u0004 \u0005[שיקשה]\u0006 קושיה אחרת על ההוכחה האחרונה: \u0003מה לכלאי הכרם — שכן לוקין עליהן אפילו שלא כדרך הנאתן.\u0004","\u0003ואביי\u0004 כיצד מתרץ הוא קושי זה? הוא משיב: כשאתה אומר \u0003\"תאמר\"\u0004 בדבר זה, \u0003במאי\u0004 \u0005[במה]\u0006 \u0003תאמר\u0004 כלומר, מה יכול אתה להמשיך בשאלה זו אם תאמר \u0003בבשר וחלב שאין לוקין עליו אלא דרך הנאתו — אטו\u0004 \u0005[וכי]\u0006 \u0003בבשר בחלב\u0004 לשון \u0003אכילה כתיב ביה\u0004 \u0005[כתובה בו]?!\u0006 והלוא לא נאמרה בו אכילה, ולכן לוקים עליו אף שלא כדרך הנאתו, ואין כאן איפוא כל מקום לסתירה.","ושואלים: ובאמת, \u0003ואידך דקא מותיב לה\u0004 \u0005[והאחר, שהוא מקשה אותה\u0006 קושיה\u0005]\u0006 כיצד הגיע להקשותה, הרי אין כתובה שם אכילה! ומשיבים: \u0003סבר, להכי קא גמר\u0004 \u0005[לכך\u0006 לצורך זה \u0005למד]\u0006 \u0003מנבילה. מה נבילה\u0004 לוקים עליה רק \u0003דרך הנאתה, שכן נאמרה בה לשון אכילה — אף בשר בחלב\u0004 אין לוקים עליו אלא \u0003דרך הנאתו\u0004 בלבד.","\u0003ואביי\u0004 סבור: כי \u0003להכי\u0004 \u0005[ל\u0006שם \u0005כך]\u0006 \u0003לא כתב אכילה בגופו\u0004 של איסור בשר בחלב \u0003לומר שלוקין עליו אפילו שלא כדרך הנאתו.\u0004","ושואלים: \u0003וליפרוך\u0004 \u0005[ושיקשה\u0006 שם\u0005]:\u0006 \u0003מה לכלאי הכרם — שכן לא היתה לו שעת הכושר,\u0004 שהרי משעה שהחלו הכלאים לצמוח בכרם נאסרו! \u0003אמר ר' אדא בר אהבה: זאת אומרת כלאי הכרם עיקרן נאסרין\u0004 כלומר, לא רק החלק שגדל כתוצאה מזריעת הכלאים, אלא גם הגרעין והשתיל עצמו שממנו צמח, \u0003הואיל והיתה להן\u0004 לגרעין \u0003שעת הכושר\u0004 (שעה שהיה כשר בה) \u0003קודם השרשה,\u0004 ונמצא שגם בכלאי הכרם יש שעת הכושר.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב שמעיה\u0004 ממה ששנינו במשנה: \u0003המעביר עציץ נקוב\u0004 שזרעים בתוכו \u0003בכרם, אם הוסיף\u0004 העציץ במשך הזמן \u0003מאתים\u0004 כלומר, אחד ממאתים על גידולו הקודם ואין בחלק המותר כדי מאתים על חלק האיסור, שחלק זה שוב אינו בטל בכמות ההיתר שיש בכל הצמח — \u0003אסור\u0004 משום כלאים. ונדייק: \u0003הוסיף — אין\u0004 \u0005[כן,\u0006 נאסר\u0005],\u0006 \u0003לא הוסיף — לא!\u0004 משמע שבכלאי הכרם אין עיקרם נאסר אלא בתוספת הגדילה בלבד!","\u0003אמר רבא: תרי קראי כתיבי\u0004 \u0005[שני מקראות כתובים]\u0006 בדין כלאי הכרם, ושני מיני איסורים הם \"לא תזרע כרמך כלאים פן תקדש המלאה הזרע אשר תזרע ותבואת הכרם\" (דברים כב, ט), אם כן \u0003כתיב\u0004 \u0005[כתוב]\u0006 שם \u0003\"הזרע\" וכתיב\u0004 \u0005[וכתוב]\u0006 \u0003\"המלאה\"\u0004 (הגידולים), \u0003הא כיצד?\u0004 שהיה \u0003זרוע מעיקרו\u0004 בכרם — נאסר מיד \u0003בהשרשה.\u0004 ואילו צמח שהיה \u0003זרוע ובא\u0004 קודם לכן, ורק מכניסים אותו לכרם (בעציץ נקוב וכדומה), אם \u0003הוסיף\u0004 וגדל בכרם — \u0003אין\u0004 \u0005[כן]\u0006 נאסר, \u0003לא הוסיף — לא.\u0004","ועוד בעניני איסורי הנאה. \u0003אמר ר' יעקב אמר ר' יוחנן: בכל\u0004 איסורי הנאה \u0003מתרפאין, חוץ מעצי אשירה\u0004 (עצים המשמשים לעבודה זרה). ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היה הדבר],\u0006 \u0003אי נימא דאיכא\u0004 \u0005[אם תאמר שיש]\u0006 \u0003סכנה\u0004 נפשות בדבר — \u0003אפילו עצי אשירה נמי\u0004 \u0005[גם כן]\u0006 מותר להתרפא בהם! \u0003ואי\u0004 \u0005[ואם]\u0006 במקום \u0003דליכא\u0004 \u0005[שאין]\u0006 בו \u0003סכנה\u0004 — \u0003אפילו כל איסורין שבתורה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יהנה מהאיסור?!","ומשיבים: \u0003לעולם\u0004 מדובר כאן \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003סכנת\u0004 נפשות, \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003עצי אשירה לא\u0004 יהנה מהם. \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: אם נאמר\u0004 \"ואהבת את ה' אלהיך בכל לבבך ו\u0003בכל נפשך\u0004 ובכל מאודך\" (דברים ו, ה), \u0003למה נאמר \"בכל מאדך\". ואם נאמר \"בכל מאדך\", למה נאמר \"בכל נפשך\"?\u0004 שיש כאן לכאורה כפל לשון או יתור.","\u0003אלא לומר לך: אם יש אדם שגופו חביב עליו מממונו — לכך נאמר \"בכל נפשך\",\u0004 שצריך למסור את נפשו. \u0003ויש אדם שממונו חביב עליו מגופו — לכך נאמר \"בכל מאדך\",\u0004 שמתפרש: בכל ממונך. ומכל מקום, למדנו שלעניינים מסויימים חייב אדם למסור נפשו ולא יתרפא מאיסור.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל \u0003אמר\u0004 בשם \u0003ר' יוחנן: — בכל\u0004 איסורי הנאה \u0003מתרפאין, חוץ מעבודה זרה וגילוי עריות\u0004"],["\u0003ושפיכות דמים.\u0004","\u0003עבודה זרה — הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 ולמדנו מ\"בכל נפשך ובכל מאודך\", שאסור ליהנות מעבודה זרה אפילו ימות. \u0003גילוי עריות ושפיכות דמים\u0004 מנין לנו? \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבי אומר:\u0004 בענין אונס נערה ארוסה נאמר \u0003\"\u0004ולנערה לא תעשה דבר אין לנערה חטא מות \u0003כי כאשר יקום איש על רעהו ורצחו נפש כן הדבר הזה\"\u0004 (דברים כב, כו). \u0003וכי מה ענין רוצח אצל נערה המאורסה\u0004 שהרי כבר שמענו את ההלכה, ומה טעם במשל זה?","אלא \u0003הרי זה בא\u0004 לכאורה \u0003ללמד\u0004 על נערה המאורסה, \u0003ונמצא למד\u0004 ממנה: \u0003מקיש רוצח לנערה המאורסה. מה נערה המאורסה ניתן להצילה בנפשו\u0004 של האונס, שמותר להציל את הנאנסת אף אם צריך להרוג את האונס, כפי הנרמז בענין זה בתורה, \u0003אף רוצח ניתן להצילו\u0004 את הנרדף \u0003בנפשו\u0004 של הרוצח. \u0003ו\u0004מצד שני לומדים דין השייך ב\u0003נערה המאורסה מרוצח, מה\u0004 ל\u0003רוצח\u0004 כלומר, אם כופים אדם לרצוח — \u0003יהרג ואל יעבור, אף נערה המאורסה תהרג ואל תעבור.\u0004","ושואלים: \u0003ושפיכות דמים גופיה\u0004 \u0005[עצמה]\u0006 \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שיש למסור נפשו ולא לשפוך דם? ומשיבים: \u0003סברא הוא\u0004 שאין יתרון לנפש על נפש. כפי שמסופר: \u0003כי ההוא דאתא לקמיה\u0004 \u0005[כמו\u0006 שהיה ב\u0005אותו\u0006 אדם \u0005שבא לפני]\u0006 \u0003רבא, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מרי דוראי\u0004 \u0005[מושל כפרי]\u0006 \u0003אמר לי: זיל קטליה לפלניא\u0004 \u0005[לך הרוג את פלוני],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא — קטלינא לך\u0004 \u0005[אהרוג אותך]\u0006\u0003. אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003ליקטלוך\u0004 \u0005[שיהרגוך]\u0006 \u0003ולא תיקטול\u0004 \u0005[תהרוג],\u0006 \u0003מאי חזית דדמא דידך סומק טפי\u0004 \u0005[מה ראית שדמך שלך אדום,\u0006 חשוב, \u0005יותר]?\u0006 \u0003דילמא דמא דההוא גברא סומק טפי\u0004 \u0005[שמא דמו של אותו אדם אדום יותר],\u0006 שאין הפקעה והיתר של פיקוח נפש חל כאשר על ידי כך הוא מאבד נפש אחרת.","מסופר: \u0003מר בר רב אשי אשכחיה\u0004 \u0005[מצא]\u0006 את \u0003רבינא דשייף לה לברתיה\u0004 \u0005[שהוא משפשף אותה את בתו]\u0006 \u0003ב\u0004פירות \u0003גוהרקי\u0004 של זיתי \u0003ערלה\u0004 לשם רפואה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 מר בר רב אשי: \u0003אימור דאמור רבנן\u0004 \u0005[אמור שאמרו חכמים]\u0006 והתירו איסורי הנאה \u0003בשעת הסכנה, שלא בשעת הסכנה מי אמור\u0004 \u0005[האם אמרו]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא: \u0003האי אישתא צמירתא נמי\u0004 \u0005[קדחת\u0006 ודלקת \u0005זו גם כן]\u0006 \u0003כשעת הסכנה\u0004 היא \u0003דמיא\u0004 \u0005[נחשבת],\u0006 ומותר להתרפא באיסור לצורך זה. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא: \u0003מידי\u0004 \u0005[וכי]\u0006 \u0003דרך הנאה קא עבידנא\u0004 \u0005[עושה אני]?\u0006 שהרי אין דרך הנאתו אלא לאחר שנתבשלו הזיתים ומיצוי שמנם, וכיון שנהנה מן האיסור שלא כדרך הנאתו — מותר אף שלא בשעת הסכנה.","ועוד דנים בכמה הלכות הנוגעות בעניני איסורים שונים, \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו חכמים בדבר \u0003הנאה\u0004 של איסור \u0003הבאה לו לאדם בעל כרחו\u0004 שלא ברצונו, \u0003אביי אמר:\u0004 הנאה כגון זו \u0003מותרת, ורבא אמר: אסורה.\u0004","ומפרטים: כאשר \u0003אפשר\u0004 לו להימנע מכך \u0003וקא מיכוין\u0004 \u0005[והוא מתכוון]\u0006 ליהנות מן האיסור, או אפילו כש\u0003לא אפשר\u0004 לו להימנע מהאיסור \u0003וקא מכוין\u0004 \u0005[והוא מתכוון]\u0006 ליהנות ממנו — \u0003כולי עלמא\u0004 \u0005[הכל]\u0006 \u0003לא פליגי\u0004 \u0005[חלוקים]\u0006 ש\u0003אסור,\u0004 שהרי אסור לו לאדם ליהנות מדבר האסור. וכאשר \u0003לא אפשר\u0004 להימנע מכך \u0003ולא מיכוין\u0004 \u0005[מתכוון] —\u0006 \u0003כולי עלמא\u0004 \u0005[הכל]\u0006 \u0003לא פליגי דשרי\u0004 \u0005[חלוקים שמותר]\u0006 וכי מה יעשה? \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה כאשר \u0003אפשר\u0004 להימנע מהאיסור \u0003ו\u0004אולם הוא \u0003לא מיכוין\u0004 \u0005[מתכוון]\u0006 ליהנות ממנו.","\u0003ו\u0004עוד מסייגים את המחלוקת \u0003אליבא\u0004 \u0005[ולפי\u0006 שיטת\u0005]\u0006 \u0003ר' יהודה\u0004 ש\u0003אמר\u0004 בכלל: \u0003\"דבר\u0004 איסור \u0003שאין מתכוין\u0004 לעשותו — \u0003אסור\", כולי עלמא\u0004 \u0005[הכל]\u0006 \u0003לא פליגי\u0004 \u0005[חלוקים]\u0006 ש\u0003אסור,\u0004 שהרי אומרים כי ר' יהודה מתחשב רק במעשה ולא בכוונת הדבר. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003אליבא\u0004 \u0005[לפי\u0006 שיטת\u0005]\u0006 \u0003ר' שמעון\u0004 ש\u0003אמר\u0004 בכלל \u0003\"דבר שאין מתכוין — מותר\".\u0004 דעת \u0003אביי\u0004 היא בפשטות \u0003כר' שמעון, ורבא אמר: עד כאן לא\u0004 שמענו ש\u0003אמר ר' שמעון — אלא היכא\u0004 \u0005[במקום]\u0006 ש\u0003לא אפשר\u0004 בדרך אחרת המותרת, \u0003אבל היכא\u0004 \u0005[במקום]\u0006 ש\u0003אפשר — לא\u0004 התיר. זו היתה גרסה אחת במחלוקת זו.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכך נחלקו: כש\u0003אפשר\u0004 בדרך אחרת \u0003ולא מיכוין\u0004 \u0005[מתכוון]\u0006 ליהנות \u0005—\u0006 \u0003היינו פלוגתייהו\u0004 \u0005[זוהי מחלוקתם]\u0006 של \u0003ר' יהודה ור' שמעון.\u0004 כש\u0003לא אפשר\u0004 להימנע מכך \u0003ולא קא מיכוין\u0004 \u0005[ואינו מתכוון]\u0006 ליהנות — \u0003כולי עלמא\u0004 \u0005[הכל]\u0006 \u0003לא פליגי דשרי\u0004 \u0005[חלוקים שמותר].\u0006 \u0003כי פליגי\u0004 \u0005[כאשר נחלקו],\u0006 הרי זה כש\u0003לא אפשר וקא מיכוין\u0004 \u0005[והוא מתכוון]\u0006 ליהנות. \u0003ו\u0004עוד סייג: \u0003אליבא\u0004 \u0005[לפי\u0006 שיטת\u0005]\u0006 \u0003ר' שמעון דאזיל בתר\u0004 \u0005[שהולך\u0006 בכלל \u0005אחר]\u0006 ה\u0003כוונה\u0004 של העושה — \u0003כולי עלמא\u0004 \u0005[הכל]\u0006 \u0003לא פליגי\u0004 \u0005[חלוקים]\u0006 ש\u0003אסור, כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003אליבא\u0004 \u0005[לפי\u0006 שיטת\u0005]\u0006 \u0003ר' יהודה,\u0004 ש\u0003אמר: לא שנא\u0004 \u0005[שונה]\u0006 \u0003מתכוין ולא שנא\u0004 \u0005[שונה]\u0006 \u0003שאין מתכוין\u0004 אלא דנים לפי המעשה, ולכן \u0003אפשר אסור.\u0004","ולפי שיטה זו שיטת \u0003אביי\u0004 היא בפשטות \u0003כ\u0004שיטת \u0003ר' יהודה.\u0004"]]};
